  ('kettlebell-swing', 'Kettlebell swing', 'compound', 'hinge', array['kettlebell']::text[], array['glutes', 'hamstrings']::text[], 'weight_reps', 'total', '{"id":"kettlebell-swing","name":"Kettlebell swing","aliases":["KB swing","Russian swing","two-hand swing"],"category":"compound","primaryMuscles":["glutes","hamstrings"],"secondaryMuscles":["lower_back","abs","forearms","shoulders"],"pattern":"hinge","equipment":["kettlebell"],"difficulty":2,"tracking":"weight_reps","load":"total","stresses":["lower_back"],"increment":{"kg":4,"lb":10},"setup":"Stand with feet a little wider than hip width and a kettlebell about a foot in front of you. Hinge down, grab the handle with both hands, and tilt it toward you.","execution":"Hike the bell back between your legs, then snap your hips forward to float it to about chest height with straight arms. Let it fall back and hinge again as it passes between your legs. The power comes from the hips, not the arms.","cues":["Hinge, don’t squat","Snap the hips and squeeze the glutes","Arms are just ropes"],"mistakes":["Lifting the bell with the shoulders","Squatting down instead of hinging","Leaning back at the top"],"substitutions":["cable-pull-through","dumbbell-romanian-deadlift","glute-bridge","band-romanian-deadlift"]}'::jsonb),
