  ('cable-pull-through', 'Cable pull-through', 'compound', 'hinge', array['cable']::text[], array['glutes', 'hamstrings']::text[], 'weight_reps', 'stack', '{"id":"cable-pull-through","name":"Cable pull-through","aliases":["pull-through","rope pull-through"],"category":"compound","primaryMuscles":["glutes","hamstrings"],"secondaryMuscles":["lower_back"],"pattern":"hinge","equipment":["cable"],"difficulty":1,"tracking":"weight_reps","load":"stack","stresses":["lower_back"],"increment":{"kg":5,"lb":10},"setup":"Attach a rope to a low cable pulley. Face away from the machine, reach between your legs to grab the rope, and walk forward a couple of steps. Stand with feet a little wider than hip width.","execution":"Push your hips back and let the rope travel between your legs until you feel a hamstring stretch. Drive the hips forward to stand tall, squeezing the glutes at the top.","cues":["Hips back to load the hamstrings","Arms stay long","Finish tall with glutes"],"mistakes":["Pulling with the arms","Squatting down instead of hinging","Leaning back to finish"],"substitutions":["kettlebell-swing","barbell-hip-thrust","band-romanian-deadlift","glute-bridge"]}'::jsonb),
