  ('kale', 'Kale', 'vegetable', 'raw', '{}'::text[], '{"id":"kale","name":"Kale","category":"vegetable","state":"raw","per100g":{"kcal":35,"protein":2.92,"carbs":4.42,"fat":1.49,"fiber":4.1},"source":"Typical value (USDA FDC generic, approximate): \"Kale, raw\"","allergens":[],"diet":{"vegetarian":true,"vegan":true,"dairyFree":true,"glutenFree":true,"pescatarian":true},"units":{"cup":21},"costTier":2}'::jsonb),
