  ('passata', 'Tomato passata', 'condiment', 'as_sold', '{}'::text[], '{"id":"passata","name":"Tomato passata","category":"condiment","state":"as_sold","per100g":{"kcal":38,"protein":1.65,"carbs":8.98,"fat":0.21,"fiber":1.9},"source":"Typical value (USDA FDC generic, approximate): \"Tomato products, canned, puree, without salt added\"","allergens":[],"diet":{"vegetarian":true,"vegan":true,"dairyFree":true,"glutenFree":true,"pescatarian":true},"units":{"cup":250},"costTier":1}'::jsonb),
