insert into public.ref_recipes (id, name, meal, servings, data) values
  ('skyr-berry-oat-bowl', 'Skyr berry bowl with oats', 'breakfast', 1, '{"id":"skyr-berry-oat-bowl","name":"Skyr berry bowl with oats","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"skyr-plain","grams":200,"display":"200 g (about ¾ cup)"},{"ingredientId":"blueberries","grams":75,"display":"½ cup","prep":"fresh or thawed"},{"ingredientId":"oats-dry","grams":30,"display":"⅓ cup","prep":"dry"},{"ingredientId":"chia-seeds","grams":6,"display":"½ tbsp"},{"ingredientId":"honey","grams":7,"display":"1 tsp","optional":true}],"steps":["Spoon the skyr into a bowl and stir until smooth.","Scatter the oats and chia seeds over the top.","Add the berries and drizzle with honey if you like it sweeter."],"substitutions":[{"ingredientId":"skyr-plain","alternatives":["greek-yogurt-0","soy-yogurt"]},{"ingredientId":"blueberries","alternatives":["strawberries","banana"]}]}'::jsonb),
  ('overnight-oats-banana', 'Banana overnight oats', 'breakfast', 1, '{"id":"overnight-oats-banana","name":"Banana overnight oats","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"oats-dry","grams":50,"display":"½ cup","prep":"dry"},{"ingredientId":"milk","grams":150,"display":"⅔ cup"},{"ingredientId":"greek-yogurt-0","grams":100,"display":"100 g"},{"ingredientId":"chia-seeds","grams":10,"display":"1 tbsp"},{"ingredientId":"banana","grams":60,"display":"½ banana","prep":"sliced"}],"steps":["Stir the oats, milk, yogurt and chia seeds together in a jar.","Cover and refrigerate for at least 4 hours or overnight.","Top with sliced banana before eating. Loosen with a splash of milk if it is too thick."],"substitutions":[{"ingredientId":"milk","alternatives":["soy-drink","oat-drink"]},{"ingredientId":"greek-yogurt-0","alternatives":["skyr-plain","soy-yogurt"]}],"notes":"Keeps for 2 days in the fridge, so make two jars at once."}'::jsonb),
  ('veggie-eggs-on-rye', 'Spinach & tomato eggs on rye', 'breakfast', 1, '{"id":"veggie-eggs-on-rye","name":"Spinach & tomato eggs on rye","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":5,"ingredients":[{"ingredientId":"egg","grams":150,"display":"3 eggs"},{"ingredientId":"spinach","grams":30,"display":"1 large handful"},{"ingredientId":"tomato","grams":60,"display":"½ tomato","prep":"diced"},{"ingredientId":"rye-bread","grams":64,"display":"2 slices"},{"ingredientId":"olive-oil","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":1,"display":"salt & pepper"}],"steps":["Warm the oil in a non-stick pan over medium heat and wilt the spinach with the tomato for 1 minute.","Beat the eggs with salt and pepper, pour into the pan and stir gently until just set.","Toast the rye bread and pile the eggs on top."],"substitutions":[{"ingredientId":"rye-bread","alternatives":["wholewheat-bread","rye-crispbread"]},{"ingredientId":"egg","alternatives":["tofu-firm"]}]}'::jsonb),
  ('tofu-scramble-peppers', 'Tofu scramble with peppers', 'breakfast', 1, '{"id":"tofu-scramble-peppers","name":"Tofu scramble with peppers","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":8,"ingredients":[{"ingredientId":"tofu-firm","grams":150,"display":"150 g","prep":"drained, crumbled"},{"ingredientId":"bell-pepper","grams":60,"display":"½ pepper","prep":"diced"},{"ingredientId":"onion","grams":40,"display":"⅓ onion","prep":"diced"},{"ingredientId":"spinach","grams":30,"display":"1 large handful"},{"ingredientId":"olive-oil","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":3,"display":"turmeric, paprika, salt & pepper"},{"ingredientId":"wholewheat-bread","grams":64,"display":"2 slices","prep":"toasted"}],"steps":["Fry the onion and pepper in the oil for 4 minutes until soft.","Crumble in the tofu, add the spices and cook for 3 minutes, stirring.","Fold through the spinach until wilted and serve with toast."],"substitutions":[{"ingredientId":"tofu-firm","alternatives":["egg"]},{"ingredientId":"wholewheat-bread","alternatives":["rye-bread"]}]}'::jsonb),
  ('peanut-banana-porridge', 'Peanut butter banana porridge', 'breakfast', 1, '{"id":"peanut-banana-porridge","name":"Peanut butter banana porridge","meal":"breakfast","servings":1,"prepMinutes":2,"cookMinutes":5,"ingredients":[{"ingredientId":"oats-dry","grams":60,"display":"¾ cup","prep":"dry"},{"ingredientId":"soy-drink","grams":250,"display":"1 cup"},{"ingredientId":"banana","grams":100,"display":"1 small banana","prep":"sliced"},{"ingredientId":"peanut-butter","grams":16,"display":"1 tbsp"}],"steps":["Simmer the oats in the soy drink for 4–5 minutes, stirring, until creamy.","Stir in half the banana to sweeten.","Top with the rest of the banana and the peanut butter."],"substitutions":[{"ingredientId":"soy-drink","alternatives":["milk","oat-drink"]},{"ingredientId":"peanut-butter","alternatives":["tahini","almonds"]}]}'::jsonb),
  ('cottage-cheese-rye-toast', 'Cottage cheese & tomato rye toast', 'breakfast', 1, '{"id":"cottage-cheese-rye-toast","name":"Cottage cheese & tomato rye toast","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":2,"ingredients":[{"ingredientId":"rye-bread","grams":64,"display":"2 slices","prep":"toasted"},{"ingredientId":"cottage-cheese","grams":150,"display":"⅔ cup"},{"ingredientId":"tomato","grams":80,"display":"1 small tomato","prep":"sliced"},{"ingredientId":"cucumber","grams":40,"display":"5 cm piece","prep":"sliced"},{"ingredientId":"spices","grams":1,"display":"black pepper, dill or chives"}],"steps":["Toast the rye bread.","Spread the cottage cheese on the toast.","Top with tomato and cucumber slices and season with pepper and herbs."],"substitutions":[{"ingredientId":"cottage-cheese","alternatives":["skyr-plain","hummus"]},{"ingredientId":"rye-bread","alternatives":["wholewheat-bread","rye-crispbread"]}]}'::jsonb),
  ('chicken-rice-broccoli-bowl', 'Garlic chicken, rice & broccoli bowls', 'lunch', 2, '{"id":"chicken-rice-broccoli-bowl","name":"Garlic chicken, rice & broccoli bowls","meal":"lunch","servings":2,"prepMinutes":10,"cookMinutes":20,"ingredients":[{"ingredientId":"chicken-breast-raw","grams":300,"display":"2 small breasts","prep":"raw, cut into strips"},{"ingredientId":"rice-white-dry","grams":150,"display":"¾ cup","prep":"dry"},{"ingredientId":"broccoli","grams":300,"display":"1 head","prep":"florets"},{"ingredientId":"soy-sauce","grams":16,"display":"1 tbsp"},{"ingredientId":"olive-oil","grams":10,"display":"2 tsp"},{"ingredientId":"garlic","grams":6,"display":"2 cloves","prep":"grated"}],"steps":["Cook the rice according to the packet (about 12–15 minutes).","Meanwhile, fry the chicken in the oil over medium-high heat for 6–8 minutes until cooked through.","Add the garlic and broccoli with a splash of water, cover and steam for 3–4 minutes.","Stir in the soy sauce and serve over the rice."],"substitutions":[{"ingredientId":"chicken-breast-raw","alternatives":["tofu-firm","chicken-thigh-raw"]},{"ingredientId":"rice-white-dry","alternatives":["quinoa-dry"]}],"notes":"Packs well for two lunches."}'::jsonb),
  ('red-lentil-soup', 'Red lentil & tomato soup', 'lunch', 4, '{"id":"red-lentil-soup","name":"Red lentil & tomato soup","meal":"lunch","servings":4,"prepMinutes":10,"cookMinutes":25,"ingredients":[{"ingredientId":"lentils-dry","grams":200,"display":"1 cup","prep":"dry, rinsed"},{"ingredientId":"onion","grams":110,"display":"1 onion","prep":"diced"},{"ingredientId":"carrot","grams":120,"display":"2 carrots","prep":"diced"},{"ingredientId":"garlic","grams":6,"display":"2 cloves","prep":"chopped"},{"ingredientId":"tomatoes-canned","grams":400,"display":"1 can"},{"ingredientId":"vegetable-stock","grams":800,"display":"800 ml"},{"ingredientId":"olive-oil","grams":13.5,"display":"1 tbsp"},{"ingredientId":"spices","grams":4,"display":"cumin, paprika, salt & pepper"},{"ingredientId":"lemon-juice","grams":15,"display":"1 tbsp"}],"steps":["Soften the onion and carrot in the oil for 5 minutes. Add the garlic and spices for 1 minute.","Add the lentils, tomatoes and stock. Bring to the boil, then simmer for 20 minutes until the lentils collapse.","Blend partly or fully, then stir in the lemon juice and season to taste."],"substitutions":[{"ingredientId":"lentils-dry","alternatives":["chickpeas-cooked"]}],"notes":"Freezes well. Stock cubes often contain celery; check the label."}'::jsonb),
  ('tuna-chickpea-salad', 'Tuna & chickpea crunch salad', 'lunch', 2, '{"id":"tuna-chickpea-salad","name":"Tuna & chickpea crunch salad","meal":"lunch","servings":2,"prepMinutes":10,"cookMinutes":0,"ingredients":[{"ingredientId":"tuna-canned","grams":240,"display":"2 cans","prep":"drained"},{"ingredientId":"chickpeas-cooked","grams":240,"display":"1 can","prep":"drained, rinsed"},{"ingredientId":"cucumber","grams":150,"display":"½ cucumber","prep":"diced"},{"ingredientId":"tomato","grams":200,"display":"2 tomatoes","prep":"diced"},{"ingredientId":"bell-pepper","grams":120,"display":"1 pepper","prep":"diced"},{"ingredientId":"onion","grams":30,"display":"¼ red onion","prep":"finely sliced"},{"ingredientId":"lettuce","grams":80,"display":"2 handfuls"},{"ingredientId":"olive-oil","grams":20,"display":"1½ tbsp"},{"ingredientId":"lemon-juice","grams":20,"display":"1½ tbsp"}],"steps":["Whisk the oil and lemon juice with salt and pepper in a large bowl.","Add the chickpeas, vegetables and onion and toss to coat.","Flake in the tuna, fold gently and serve over the lettuce."],"substitutions":[{"ingredientId":"tuna-canned","alternatives":["chicken-breast-cooked","egg"]},{"ingredientId":"chickpeas-cooked","alternatives":["black-beans-cooked"]}]}'::jsonb),
  ('greek-chicken-wraps', 'Chicken wraps with garlic yogurt', 'lunch', 2, '{"id":"greek-chicken-wraps","name":"Chicken wraps with garlic yogurt","meal":"lunch","servings":2,"prepMinutes":10,"cookMinutes":0,"ingredients":[{"ingredientId":"tortilla-wheat","grams":90,"display":"2 tortillas"},{"ingredientId":"chicken-breast-cooked","grams":160,"display":"160 g","prep":"cooked, sliced"},{"ingredientId":"greek-yogurt-0","grams":80,"display":"⅓ cup"},{"ingredientId":"garlic","grams":3,"display":"1 clove","prep":"grated"},{"ingredientId":"cucumber","grams":60,"display":"¼ cucumber","prep":"grated or sliced"},{"ingredientId":"tomato","grams":60,"display":"½ tomato","prep":"sliced"},{"ingredientId":"lettuce","grams":40,"display":"1 handful","prep":"shredded"}],"steps":["Mix the yogurt with the garlic, a pinch of salt and half the cucumber.","Warm the tortillas in a dry pan for 20 seconds each side.","Spread with the yogurt sauce, add lettuce, tomato, the rest of the cucumber and chicken, then roll up tightly."],"substitutions":[{"ingredientId":"chicken-breast-cooked","alternatives":["tofu-firm","chickpeas-cooked"]},{"ingredientId":"greek-yogurt-0","alternatives":["soy-yogurt","hummus"]}],"notes":"Use leftover roast chicken or chicken from the rice bowls."}'::jsonb),
  ('quinoa-black-bean-bowl', 'Quinoa black bean bowls', 'lunch', 2, '{"id":"quinoa-black-bean-bowl","name":"Quinoa black bean bowls","meal":"lunch","servings":2,"prepMinutes":10,"cookMinutes":15,"ingredients":[{"ingredientId":"quinoa-dry","grams":120,"display":"⅔ cup","prep":"dry, rinsed"},{"ingredientId":"black-beans-cooked","grams":240,"display":"1 can","prep":"drained, rinsed"},{"ingredientId":"bell-pepper","grams":120,"display":"1 pepper","prep":"diced"},{"ingredientId":"tomato","grams":120,"display":"1 tomato","prep":"diced"},{"ingredientId":"avocado","grams":100,"display":"⅔ avocado","prep":"sliced"},{"ingredientId":"lemon-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"olive-oil","grams":10,"display":"2 tsp"},{"ingredientId":"spices","grams":3,"display":"cumin, chilli, salt"}],"steps":["Simmer the quinoa in twice its volume of water for 12–15 minutes, then drain.","Warm the beans with the spices and a splash of water for 2 minutes.","Toss the quinoa with the oil and lemon juice, then top with beans, pepper, tomato and avocado."],"substitutions":[{"ingredientId":"quinoa-dry","alternatives":["rice-white-dry"]},{"ingredientId":"black-beans-cooked","alternatives":["chickpeas-cooked","edamame"]}]}'::jsonb),
  ('egg-hummus-rye', 'Egg & hummus open rye sandwiches', 'lunch', 1, '{"id":"egg-hummus-rye","name":"Egg & hummus open rye sandwiches","meal":"lunch","servings":1,"prepMinutes":5,"cookMinutes":9,"ingredients":[{"ingredientId":"rye-bread","grams":64,"display":"2 slices"},{"ingredientId":"hummus","grams":40,"display":"2½ tbsp"},{"ingredientId":"egg","grams":100,"display":"2 eggs","prep":"hard-boiled"},{"ingredientId":"cucumber","grams":40,"display":"5 cm piece","prep":"sliced"},{"ingredientId":"spinach","grams":15,"display":"a few leaves"}],"steps":["Boil the eggs for 9 minutes, cool in cold water and peel.","Spread the hummus over the rye bread.","Top with spinach, cucumber and sliced egg. Season with pepper."],"substitutions":[{"ingredientId":"egg","alternatives":["tuna-canned","tofu-firm"]},{"ingredientId":"rye-bread","alternatives":["wholewheat-bread"]}]}'::jsonb),
  ('baked-cod-potatoes-peas', 'Lemon baked cod with potatoes & peas', 'dinner', 2, '{"id":"baked-cod-potatoes-peas","name":"Lemon baked cod with potatoes & peas","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":30,"ingredients":[{"ingredientId":"cod-raw","grams":320,"display":"2 fillets","prep":"raw"},{"ingredientId":"potato-raw","grams":450,"display":"2 medium potatoes","prep":"cut into wedges"},{"ingredientId":"peas-green","grams":160,"display":"1 cup","prep":"frozen"},{"ingredientId":"olive-oil","grams":13.5,"display":"1 tbsp"},{"ingredientId":"lemon-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"spices","grams":2,"display":"dill, salt & pepper"}],"steps":["Heat the oven to 220 °C (200 °C fan). Toss the potato wedges with most of the oil and salt, and roast for 20 minutes.","Push the potatoes aside, add the cod, drizzle with the remaining oil and lemon juice, season, and bake 10–12 minutes until it flakes.","Meanwhile, boil the peas for 3 minutes. Serve together with dill."],"substitutions":[{"ingredientId":"cod-raw","alternatives":["salmon-raw","tofu-firm"]},{"ingredientId":"potato-raw","alternatives":["sweet-potato-raw"]}]}'::jsonb),
  ('salmon-sweet-potato-traybake', 'Salmon & sweet potato traybake', 'dinner', 2, '{"id":"salmon-sweet-potato-traybake","name":"Salmon & sweet potato traybake","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":30,"ingredients":[{"ingredientId":"salmon-raw","grams":280,"display":"2 fillets","prep":"raw"},{"ingredientId":"sweet-potato-raw","grams":400,"display":"2 medium","prep":"cubed"},{"ingredientId":"broccoli","grams":250,"display":"1 small head","prep":"florets"},{"ingredientId":"olive-oil","grams":10,"display":"2 tsp"},{"ingredientId":"lemon-juice","grams":10,"display":"2 tsp"},{"ingredientId":"spices","grams":2,"display":"paprika, salt & pepper"}],"steps":["Heat the oven to 200 °C (180 °C fan). Toss the sweet potato with the oil and spices and roast for 15 minutes.","Add the broccoli and salmon to the tray and roast 12–15 minutes more, until the salmon flakes easily.","Finish with lemon juice."],"substitutions":[{"ingredientId":"salmon-raw","alternatives":["cod-raw","chicken-breast-raw"]},{"ingredientId":"sweet-potato-raw","alternatives":["potato-raw"]}]}'::jsonb),
  ('beef-bean-chilli', 'Beef & black bean chilli with rice', 'dinner', 4, '{"id":"beef-bean-chilli","name":"Beef & black bean chilli with rice","meal":"dinner","servings":4,"prepMinutes":10,"cookMinutes":35,"ingredients":[{"ingredientId":"beef-mince-10-raw","grams":400,"display":"400 g","prep":"raw"},{"ingredientId":"black-beans-cooked","grams":480,"display":"2 cans","prep":"drained"},{"ingredientId":"tomatoes-canned","grams":800,"display":"2 cans"},{"ingredientId":"onion","grams":150,"display":"1 large onion","prep":"diced"},{"ingredientId":"bell-pepper","grams":150,"display":"1 large pepper","prep":"diced"},{"ingredientId":"garlic","grams":9,"display":"3 cloves","prep":"chopped"},{"ingredientId":"spices","grams":8,"display":"chilli, cumin, paprika, salt"},{"ingredientId":"rice-white-dry","grams":240,"display":"1¼ cups","prep":"dry"}],"steps":["Brown the mince in a large pan over high heat, breaking it up, for 5 minutes.","Add the onion, pepper and garlic and cook 5 minutes. Stir in the spices for 1 minute.","Add the tomatoes and beans, then simmer uncovered for 25 minutes, stirring now and then.","Cook the rice according to the packet and serve with the chilli."],"substitutions":[{"ingredientId":"beef-mince-10-raw","alternatives":["lentils-dry","chicken-thigh-raw"]},{"ingredientId":"rice-white-dry","alternatives":["quinoa-dry"]}],"notes":"Freezes well in portions."}'::jsonb),
  ('chicken-thigh-traybake', 'Chicken thigh, potato & carrot traybake', 'dinner', 4, '{"id":"chicken-thigh-traybake","name":"Chicken thigh, potato & carrot traybake","meal":"dinner","servings":4,"prepMinutes":10,"cookMinutes":40,"ingredients":[{"ingredientId":"chicken-thigh-raw","grams":600,"display":"8 boneless thighs","prep":"raw, skinless"},{"ingredientId":"potato-raw","grams":800,"display":"4 medium potatoes","prep":"chunks"},{"ingredientId":"carrot","grams":300,"display":"5 carrots","prep":"chunks"},{"ingredientId":"onion","grams":200,"display":"2 onions","prep":"wedges"},{"ingredientId":"garlic","grams":9,"display":"3 cloves","prep":"smashed"},{"ingredientId":"olive-oil","grams":20,"display":"1½ tbsp"},{"ingredientId":"spices","grams":4,"display":"thyme, paprika, salt & pepper"}],"steps":["Heat the oven to 210 °C (190 °C fan).","Toss everything with the oil and spices on a large tray, keeping the chicken on top.","Roast for 35–40 minutes, turning the vegetables once, until the chicken is cooked through and the potatoes are golden."],"substitutions":[{"ingredientId":"chicken-thigh-raw","alternatives":["chicken-breast-raw","tofu-firm"]},{"ingredientId":"potato-raw","alternatives":["sweet-potato-raw"]}]}'::jsonb),
  ('lentil-bolognese', 'Lentil bolognese', 'dinner', 4, '{"id":"lentil-bolognese","name":"Lentil bolognese","meal":"dinner","servings":4,"prepMinutes":10,"cookMinutes":30,"ingredients":[{"ingredientId":"lentils-dry","grams":180,"display":"1 cup","prep":"dry, rinsed"},{"ingredientId":"pasta-dry","grams":320,"display":"320 g","prep":"dry"},{"ingredientId":"tomatoes-canned","grams":800,"display":"2 cans"},{"ingredientId":"onion","grams":150,"display":"1 large onion","prep":"diced"},{"ingredientId":"carrot","grams":120,"display":"2 carrots","prep":"finely diced"},{"ingredientId":"mushrooms","grams":150,"display":"2 cups","prep":"chopped"},{"ingredientId":"garlic","grams":9,"display":"3 cloves","prep":"chopped"},{"ingredientId":"olive-oil","grams":13.5,"display":"1 tbsp"},{"ingredientId":"spices","grams":4,"display":"oregano, salt & pepper"}],"steps":["Soften the onion, carrot and mushrooms in the oil for 8 minutes. Add the garlic for 1 minute.","Add the lentils, tomatoes and 300 ml water. Simmer for 25 minutes until the lentils are tender, adding water if it gets dry.","Meanwhile, cook the pasta according to the packet. Season the sauce and serve over the pasta."],"substitutions":[{"ingredientId":"lentils-dry","alternatives":["beef-mince-10-raw"]},{"ingredientId":"pasta-dry","alternatives":["rice-white-dry"]}]}'::jsonb),
  ('tofu-veg-stir-fry', 'Crispy tofu & edamame stir-fry', 'dinner', 2, '{"id":"tofu-veg-stir-fry","name":"Crispy tofu & edamame stir-fry","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":15,"ingredients":[{"ingredientId":"tofu-firm","grams":300,"display":"1 block","prep":"pressed, cubed"},{"ingredientId":"rice-white-dry","grams":150,"display":"¾ cup","prep":"dry"},{"ingredientId":"broccoli","grams":200,"display":"2 cups","prep":"florets"},{"ingredientId":"bell-pepper","grams":120,"display":"1 pepper","prep":"sliced"},{"ingredientId":"carrot","grams":80,"display":"1 large carrot","prep":"thin strips"},{"ingredientId":"edamame","grams":100,"display":"⅔ cup","prep":"shelled"},{"ingredientId":"soy-sauce","grams":24,"display":"1½ tbsp"},{"ingredientId":"garlic","grams":6,"display":"2 cloves","prep":"grated"},{"ingredientId":"rapeseed-oil","grams":14,"display":"1 tbsp"}],"steps":["Cook the rice according to the packet.","Fry the tofu in half the oil over high heat for 6–8 minutes, turning, until golden. Set aside.","Stir-fry the vegetables and edamame in the remaining oil for 4 minutes. Add the garlic for 30 seconds.","Return the tofu, add the soy sauce, toss and serve over the rice."],"substitutions":[{"ingredientId":"tofu-firm","alternatives":["chicken-breast-raw","tempeh"]},{"ingredientId":"rice-white-dry","alternatives":["quinoa-dry"]}]}'::jsonb),
  ('garlic-prawn-pasta', 'Garlic prawn & spinach pasta', 'dinner', 2, '{"id":"garlic-prawn-pasta","name":"Garlic prawn & spinach pasta","meal":"dinner","servings":2,"prepMinutes":5,"cookMinutes":15,"ingredients":[{"ingredientId":"pasta-dry","grams":180,"display":"180 g","prep":"dry"},{"ingredientId":"shrimp-cooked","grams":250,"display":"250 g","prep":"cooked, peeled"},{"ingredientId":"spinach","grams":100,"display":"3 large handfuls"},{"ingredientId":"tomato","grams":200,"display":"2 tomatoes","prep":"chopped"},{"ingredientId":"garlic","grams":9,"display":"3 cloves","prep":"sliced"},{"ingredientId":"olive-oil","grams":13.5,"display":"1 tbsp"},{"ingredientId":"lemon-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"spices","grams":2,"display":"chilli flakes, salt & pepper"}],"steps":["Cook the pasta according to the packet. Save a cup of the cooking water before draining.","Warm the oil and garlic gently for 1 minute, add the tomatoes and cook for 3 minutes.","Add the prawns and spinach and stir until the spinach wilts and the prawns are hot (2 minutes).","Toss in the pasta with lemon juice and a splash of the pasta water."],"substitutions":[{"ingredientId":"shrimp-cooked","alternatives":["chicken-breast-cooked","tuna-canned"]},{"ingredientId":"pasta-dry","alternatives":["rice-white-dry"]}]}'::jsonb),
  ('chickpea-sweet-potato-curry', 'Chickpea & sweet potato curry', 'dinner', 4, '{"id":"chickpea-sweet-potato-curry","name":"Chickpea & sweet potato curry","meal":"dinner","servings":4,"prepMinutes":10,"cookMinutes":30,"ingredients":[{"ingredientId":"chickpeas-cooked","grams":480,"display":"2 cans","prep":"drained"},{"ingredientId":"sweet-potato-raw","grams":400,"display":"2 medium","prep":"cubed"},{"ingredientId":"tomatoes-canned","grams":400,"display":"1 can"},{"ingredientId":"spinach","grams":100,"display":"3 large handfuls"},{"ingredientId":"onion","grams":110,"display":"1 onion","prep":"diced"},{"ingredientId":"garlic","grams":6,"display":"2 cloves","prep":"chopped"},{"ingredientId":"spices","grams":8,"display":"curry powder, cumin, salt"},{"ingredientId":"rapeseed-oil","grams":14,"display":"1 tbsp"},{"ingredientId":"rice-white-dry","grams":200,"display":"1 cup","prep":"dry"},{"ingredientId":"soy-yogurt","grams":120,"display":"½ cup","prep":"to serve"}],"steps":["Soften the onion in the oil for 5 minutes, add the garlic and spices for 1 minute.","Add the sweet potato, tomatoes and 250 ml water. Cover and simmer for 15 minutes.","Add the chickpeas and simmer 8 minutes more until the sweet potato is tender. Stir in the spinach.","Serve with rice and a spoon of yogurt."],"substitutions":[{"ingredientId":"soy-yogurt","alternatives":["greek-yogurt-0","skyr-plain"]},{"ingredientId":"chickpeas-cooked","alternatives":["lentils-cooked","tofu-firm"]}]}'::jsonb),
  ('skyr-peanut-apple-dip', 'Peanut skyr dip with apple', 'snack', 1, '{"id":"skyr-peanut-apple-dip","name":"Peanut skyr dip with apple","meal":"snack","servings":1,"prepMinutes":3,"cookMinutes":0,"ingredients":[{"ingredientId":"skyr-plain","grams":150,"display":"150 g"},{"ingredientId":"peanut-butter","grams":16,"display":"1 tbsp"},{"ingredientId":"apple","grams":150,"display":"1 small apple","prep":"sliced"}],"steps":["Stir the peanut butter into the skyr until smooth.","Serve with apple slices for dipping."],"substitutions":[{"ingredientId":"skyr-plain","alternatives":["greek-yogurt-0","soy-yogurt"]},{"ingredientId":"peanut-butter","alternatives":["tahini"]}]}'::jsonb),
  ('cottage-cheese-berries', 'Cottage cheese with berries & seeds', 'snack', 1, '{"id":"cottage-cheese-berries","name":"Cottage cheese with berries & seeds","meal":"snack","servings":1,"prepMinutes":2,"cookMinutes":0,"ingredients":[{"ingredientId":"cottage-cheese","grams":150,"display":"⅔ cup"},{"ingredientId":"strawberries","grams":100,"display":"⅔ cup","prep":"sliced"},{"ingredientId":"pumpkin-seeds","grams":9,"display":"1 tbsp"}],"steps":["Spoon the cottage cheese into a bowl.","Top with the strawberries and pumpkin seeds."],"substitutions":[{"ingredientId":"cottage-cheese","alternatives":["skyr-plain","soy-yogurt"]},{"ingredientId":"strawberries","alternatives":["blueberries"]}]}'::jsonb),
  ('roasted-spiced-chickpeas', 'Crunchy roasted chickpeas', 'snack', 3, '{"id":"roasted-spiced-chickpeas","name":"Crunchy roasted chickpeas","meal":"snack","servings":3,"prepMinutes":5,"cookMinutes":30,"ingredients":[{"ingredientId":"chickpeas-cooked","grams":240,"display":"1 can","prep":"drained, patted dry"},{"ingredientId":"olive-oil","grams":7,"display":"1½ tsp"},{"ingredientId":"spices","grams":3,"display":"smoked paprika, salt"}],"steps":["Heat the oven to 200 °C (180 °C fan). Pat the chickpeas very dry with a towel.","Toss with the oil and spices and spread on a tray in one layer.","Roast for 25–30 minutes, shaking halfway, until crisp. They crisp more as they cool."],"substitutions":[{"ingredientId":"chickpeas-cooked","alternatives":["edamame"]}],"notes":"Store in an open container so they stay crunchy."}'::jsonb),
  ('hummus-veg-crispbread', 'Hummus, veg sticks & crispbread', 'snack', 1, '{"id":"hummus-veg-crispbread","name":"Hummus, veg sticks & crispbread","meal":"snack","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"hummus","grams":60,"display":"4 tbsp"},{"ingredientId":"carrot","grams":80,"display":"1 large carrot","prep":"sticks"},{"ingredientId":"cucumber","grams":80,"display":"¼ cucumber","prep":"sticks"},{"ingredientId":"rye-crispbread","grams":20,"display":"2 crispbreads"},{"ingredientId":"edamame","grams":60,"display":"⅓ cup","prep":"shelled"}],"steps":["Cut the carrot and cucumber into sticks.","Serve with the hummus, edamame and crispbread."],"substitutions":[{"ingredientId":"rye-crispbread","alternatives":["wholewheat-bread"]},{"ingredientId":"hummus","alternatives":["cottage-cheese"]}]}'::jsonb),
  ('skyr-oat-pancakes', 'Skyr & oat pancakes', 'breakfast', 1, '{"id":"skyr-oat-pancakes","name":"Skyr & oat pancakes","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":8,"ingredients":[{"ingredientId":"skyr-plain","grams":150,"display":"150 g"},{"ingredientId":"egg","grams":100,"display":"2 eggs"},{"ingredientId":"oats-dry","grams":50,"display":"½ cup","prep":"dry"},{"ingredientId":"banana","grams":60,"display":"½ banana"},{"ingredientId":"rapeseed-oil","grams":4,"display":"1 tsp"},{"ingredientId":"blueberries","grams":50,"display":"⅓ cup","optional":true}],"steps":["Blend or mash the skyr, eggs, oats and banana into a thick batter. Rest it for 2 minutes.","Heat a non-stick pan over medium heat and brush with a little oil.","Spoon in small pancakes and cook about 2 minutes per side until golden and set.","Serve warm with berries on top."],"substitutions":[{"ingredientId":"skyr-plain","alternatives":["greek-yogurt-0","cottage-cheese"]},{"ingredientId":"blueberries","alternatives":["raspberries","strawberries"]}],"notes":"Keep the pancakes small so they are easy to flip."}'::jsonb),
  ('smoked-salmon-skyr-crispbread', 'Smoked salmon & skyr crispbreads', 'breakfast', 1, '{"id":"smoked-salmon-skyr-crispbread","name":"Smoked salmon & skyr crispbreads","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"rye-crispbread","grams":30,"display":"3 crispbreads"},{"ingredientId":"skyr-plain","grams":100,"display":"100 g"},{"ingredientId":"smoked-salmon","grams":100,"display":"100 g"},{"ingredientId":"cucumber","grams":50,"display":"5 cm piece","prep":"thinly sliced"},{"ingredientId":"lemon-juice","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":1,"display":"dill & black pepper"}],"steps":["Stir the lemon juice, dill and pepper into the skyr.","Spread the skyr over the crispbreads.","Top with cucumber slices and the smoked salmon."],"substitutions":[{"ingredientId":"smoked-salmon","alternatives":["tuna-canned","egg"]},{"ingredientId":"rye-crispbread","alternatives":["rye-bread","rice-cakes"]}]}'::jsonb),
  ('savoury-cottage-cheese-bowl', 'Savoury cottage cheese bowl', 'breakfast', 1, '{"id":"savoury-cottage-cheese-bowl","name":"Savoury cottage cheese bowl","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"cottage-cheese","grams":250,"display":"250 g (about 1 cup)"},{"ingredientId":"tomato","grams":80,"display":"1 small tomato","prep":"diced"},{"ingredientId":"cucumber","grams":80,"display":"¼ cucumber","prep":"diced"},{"ingredientId":"pumpkin-seeds","grams":15,"display":"1½ tbsp"},{"ingredientId":"rye-crispbread","grams":20,"display":"2 crispbreads"},{"ingredientId":"spices","grams":1,"display":"salt, pepper & chilli flakes"}],"steps":["Spoon the cottage cheese into a bowl.","Pile the tomato and cucumber on top and season.","Scatter with pumpkin seeds and eat with the crispbreads."],"substitutions":[{"ingredientId":"cottage-cheese","alternatives":["skyr-plain","greek-yogurt-0"]},{"ingredientId":"rye-crispbread","alternatives":["rice-cakes"]}]}'::jsonb),
  ('egg-white-feta-omelette', 'Spinach & feta egg-white omelette', 'breakfast', 1, '{"id":"egg-white-feta-omelette","name":"Spinach & feta egg-white omelette","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":5,"ingredients":[{"ingredientId":"egg","grams":100,"display":"2 eggs"},{"ingredientId":"egg-white","grams":132,"display":"4 egg whites"},{"ingredientId":"spinach","grams":30,"display":"1 large handful"},{"ingredientId":"tomato","grams":80,"display":"1 small tomato","prep":"sliced"},{"ingredientId":"feta","grams":30,"display":"30 g","prep":"crumbled"},{"ingredientId":"olive-oil","grams":4,"display":"1 tsp"},{"ingredientId":"spices","grams":1,"display":"salt & pepper"}],"steps":["Whisk the eggs and egg whites with salt and pepper.","Heat the oil in a non-stick pan, add the spinach and let it wilt for 30 seconds.","Pour in the eggs and cook gently, pulling the edges in, until almost set.","Scatter the feta over half, fold and serve with the sliced tomato."],"substitutions":[{"ingredientId":"feta","alternatives":["gouda","cottage-cheese"]},{"ingredientId":"spinach","alternatives":["mushrooms","bell-pepper"]}]}'::jsonb),
  ('chocolate-skyr-overnight-oats', 'Chocolate raspberry overnight oats', 'breakfast', 1, '{"id":"chocolate-skyr-overnight-oats","name":"Chocolate raspberry overnight oats","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"oats-dry","grams":50,"display":"½ cup","prep":"dry"},{"ingredientId":"skyr-plain","grams":170,"display":"170 g"},{"ingredientId":"milk","grams":100,"display":"100 ml"},{"ingredientId":"cocoa-powder","grams":8,"display":"1½ tbsp"},{"ingredientId":"chia-seeds","grams":10,"display":"1 tbsp"},{"ingredientId":"raspberries","grams":60,"display":"½ cup","prep":"fresh or frozen"},{"ingredientId":"maple-syrup","grams":7,"display":"1 tsp","optional":true}],"steps":["Stir the oats, skyr, milk, cocoa and chia together in a jar until no dry cocoa is left.","Press the raspberries on top, cover and chill overnight.","Sweeten with a little maple syrup in the morning if you like."],"substitutions":[{"ingredientId":"skyr-plain","alternatives":["greek-yogurt-0","soy-yogurt"]},{"ingredientId":"milk","alternatives":["soy-drink","oat-drink"]}],"notes":"Frozen raspberries thaw overnight and make their own sauce."}'::jsonb),
  ('vegan-chocolate-chia-pudding', 'Chocolate chia pudding', 'breakfast', 1, '{"id":"vegan-chocolate-chia-pudding","name":"Chocolate chia pudding","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"soy-drink","grams":250,"display":"1 cup"},{"ingredientId":"chia-seeds","grams":30,"display":"2½ tbsp"},{"ingredientId":"cocoa-powder","grams":8,"display":"1½ tbsp"},{"ingredientId":"maple-syrup","grams":10,"display":"½ tbsp"},{"ingredientId":"raspberries","grams":80,"display":"⅔ cup"}],"steps":["Whisk the soy drink, cocoa and maple syrup until smooth, then whisk in the chia.","Leave 5 minutes, whisk again to break up clumps, then chill for at least 2 hours.","Top with raspberries before eating."],"substitutions":[{"ingredientId":"soy-drink","alternatives":["milk","oat-drink"]},{"ingredientId":"raspberries","alternatives":["strawberries","banana"]}]}'::jsonb),
  ('apple-cinnamon-porridge', 'Apple cinnamon porridge', 'breakfast', 1, '{"id":"apple-cinnamon-porridge","name":"Apple cinnamon porridge","meal":"breakfast","servings":1,"prepMinutes":3,"cookMinutes":5,"ingredients":[{"ingredientId":"oats-dry","grams":60,"display":"¾ cup","prep":"dry"},{"ingredientId":"soy-drink","grams":250,"display":"1 cup"},{"ingredientId":"apple","grams":100,"display":"½ apple","prep":"grated"},{"ingredientId":"walnuts","grams":10,"display":"1½ tbsp","prep":"chopped"},{"ingredientId":"spices","grams":1,"display":"cinnamon & a pinch of salt"}],"steps":["Put the oats, soy drink, grated apple and cinnamon in a small pan.","Simmer for 4–5 minutes, stirring, until thick and creamy.","Top with the chopped walnuts."],"substitutions":[{"ingredientId":"soy-drink","alternatives":["milk","oat-drink"]},{"ingredientId":"walnuts","alternatives":["almonds","pumpkin-seeds"]}]}'::jsonb),
  ('egg-bean-breakfast-burrito', 'Egg & black bean breakfast burrito', 'breakfast', 1, '{"id":"egg-bean-breakfast-burrito","name":"Egg & black bean breakfast burrito","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":5,"ingredients":[{"ingredientId":"tortilla-wheat","grams":45,"display":"1 tortilla"},{"ingredientId":"egg","grams":150,"display":"3 eggs"},{"ingredientId":"black-beans-cooked","grams":60,"display":"¼ can","prep":"drained"},{"ingredientId":"bell-pepper","grams":40,"display":"⅓ pepper","prep":"diced"},{"ingredientId":"gouda","grams":20,"display":"1 slice","prep":"grated"},{"ingredientId":"rapeseed-oil","grams":4,"display":"1 tsp"},{"ingredientId":"spices","grams":1,"display":"smoked paprika, salt & pepper"}],"steps":["Soften the pepper in the oil for 2 minutes, then add the beans to warm through.","Pour in the beaten, seasoned eggs and stir until softly set.","Warm the tortilla, add the cheese and the egg filling, then roll it up tightly."],"substitutions":[{"ingredientId":"tortilla-wheat","alternatives":["tortilla-corn"]},{"ingredientId":"black-beans-cooked","alternatives":["kidney-beans-cooked"]}]}'::jsonb),
  ('tofu-breakfast-tacos', 'Tofu breakfast tacos', 'breakfast', 1, '{"id":"tofu-breakfast-tacos","name":"Tofu breakfast tacos","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":6,"ingredients":[{"ingredientId":"tortilla-corn","grams":52,"display":"2 corn tortillas"},{"ingredientId":"tofu-firm","grams":150,"display":"150 g","prep":"crumbled"},{"ingredientId":"black-beans-cooked","grams":60,"display":"¼ can","prep":"drained"},{"ingredientId":"avocado","grams":40,"display":"¼ avocado","prep":"sliced"},{"ingredientId":"lime-juice","grams":10,"display":"2 tsp"},{"ingredientId":"olive-oil","grams":4,"display":"1 tsp"},{"ingredientId":"spices","grams":2,"display":"turmeric, cumin, salt & pepper"}],"steps":["Fry the crumbled tofu in the oil with the spices for 4 minutes until lightly golden.","Add the beans and warm for 1 minute.","Warm the tortillas in a dry pan, fill with the tofu, add avocado and a squeeze of lime."],"substitutions":[{"ingredientId":"tofu-firm","alternatives":["egg"]},{"ingredientId":"tortilla-corn","alternatives":["tortilla-wheat"]}]}'::jsonb),
  ('egg-veg-muffins', 'Egg & veg breakfast muffins', 'breakfast', 4, '{"id":"egg-veg-muffins","name":"Egg & veg breakfast muffins","meal":"breakfast","servings":4,"prepMinutes":10,"cookMinutes":20,"ingredients":[{"ingredientId":"egg","grams":400,"display":"8 eggs"},{"ingredientId":"cottage-cheese","grams":200,"display":"200 g"},{"ingredientId":"bell-pepper","grams":120,"display":"1 pepper","prep":"diced"},{"ingredientId":"spinach","grams":60,"display":"2 handfuls","prep":"chopped"},{"ingredientId":"spring-onion","grams":30,"display":"2 spring onions","prep":"sliced"},{"ingredientId":"feta","grams":80,"display":"80 g","prep":"crumbled"},{"ingredientId":"rapeseed-oil","grams":5,"display":"1 tsp","prep":"for the tin"},{"ingredientId":"spices","grams":2,"display":"salt & pepper"}],"steps":["Heat the oven to 190 °C (170 °C fan) and oil a 12-hole muffin tin.","Whisk the eggs with the cottage cheese, salt and pepper.","Divide the vegetables and feta between the holes and pour the egg mixture over.","Bake for 18–20 minutes until puffed and set in the middle."],"substitutions":[{"ingredientId":"feta","alternatives":["gouda"]},{"ingredientId":"spinach","alternatives":["mushrooms","zucchini"]}],"notes":"Three muffins per serving. They keep 4 days in the fridge; reheat for 30 seconds or eat cold."}'::jsonb),
  ('peanut-butter-banana-toast', 'Peanut butter & banana toast', 'breakfast', 1, '{"id":"peanut-butter-banana-toast","name":"Peanut butter & banana toast","meal":"breakfast","servings":1,"prepMinutes":3,"cookMinutes":2,"ingredients":[{"ingredientId":"wholewheat-bread","grams":64,"display":"2 slices"},{"ingredientId":"peanut-butter","grams":32,"display":"2 tbsp"},{"ingredientId":"banana","grams":100,"display":"1 small banana","prep":"sliced"},{"ingredientId":"chia-seeds","grams":5,"display":"1 tsp","optional":true}],"steps":["Toast the bread.","Spread with peanut butter and cover with banana slices.","Sprinkle with chia seeds if you have them."],"substitutions":[{"ingredientId":"peanut-butter","alternatives":["tahini"]},{"ingredientId":"wholewheat-bread","alternatives":["rye-bread","rice-cakes"]}]}'::jsonb),
  ('skyr-berry-smoothie', 'Skyr berry smoothie', 'breakfast', 1, '{"id":"skyr-berry-smoothie","name":"Skyr berry smoothie","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"skyr-plain","grams":200,"display":"200 g"},{"ingredientId":"milk","grams":200,"display":"200 ml"},{"ingredientId":"banana","grams":100,"display":"1 small banana"},{"ingredientId":"strawberries","grams":100,"display":"⅔ cup","prep":"frozen is fine"},{"ingredientId":"chia-seeds","grams":10,"display":"1 tbsp"}],"steps":["Put everything in a blender, milk first.","Blend for 30–60 seconds until smooth. Add a splash more milk if it is too thick.","Pour into a large glass and drink straight away."],"substitutions":[{"ingredientId":"skyr-plain","alternatives":["greek-yogurt-0","soy-yogurt"]},{"ingredientId":"milk","alternatives":["soy-drink","oat-drink"]}]}'::jsonb),
  ('berry-smoothie-bowl-vegan', 'Berry smoothie bowl with seeds', 'breakfast', 1, '{"id":"berry-smoothie-bowl-vegan","name":"Berry smoothie bowl with seeds","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"soy-yogurt","grams":200,"display":"200 g"},{"ingredientId":"soy-drink","grams":100,"display":"100 ml"},{"ingredientId":"raspberries","grams":150,"display":"1¼ cups","prep":"frozen"},{"ingredientId":"banana","grams":100,"display":"1 small banana","prep":"frozen if possible"},{"ingredientId":"pumpkin-seeds","grams":15,"display":"1½ tbsp"},{"ingredientId":"chia-seeds","grams":10,"display":"1 tbsp"}],"steps":["Blend the soy yogurt, soy drink, raspberries and banana until thick and smooth.","Spoon into a bowl.","Top with pumpkin and chia seeds."],"substitutions":[{"ingredientId":"soy-yogurt","alternatives":["skyr-plain","greek-yogurt-0"]},{"ingredientId":"raspberries","alternatives":["blueberries","strawberries"]}]}'::jsonb),
  ('shakshuka-for-one', 'Shakshuka for one', 'breakfast', 1, '{"id":"shakshuka-for-one","name":"Shakshuka for one","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":12,"ingredients":[{"ingredientId":"egg","grams":150,"display":"3 eggs"},{"ingredientId":"tomatoes-canned","grams":200,"display":"½ can"},{"ingredientId":"bell-pepper","grams":60,"display":"½ pepper","prep":"sliced"},{"ingredientId":"onion","grams":40,"display":"⅓ onion","prep":"sliced"},{"ingredientId":"feta","grams":50,"display":"50 g","prep":"crumbled"},{"ingredientId":"olive-oil","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":2,"display":"cumin, paprika, salt & pepper"},{"ingredientId":"rye-bread","grams":32,"display":"1 slice"}],"steps":["Soften the onion and pepper in the oil in a small frying pan for 4 minutes.","Add the spices and tomatoes and simmer for 3 minutes until slightly thickened.","Make three hollows, crack in the eggs, cover and cook on low for 4–5 minutes until the whites set.","Crumble the feta over and eat from the pan with the rye bread."],"substitutions":[{"ingredientId":"feta","alternatives":["gouda"]},{"ingredientId":"rye-bread","alternatives":["wholewheat-bread","pita-wholewheat"]}]}'::jsonb),
  ('bircher-muesli-batch', 'Skyr Bircher muesli', 'breakfast', 4, '{"id":"bircher-muesli-batch","name":"Skyr Bircher muesli","meal":"breakfast","servings":4,"prepMinutes":10,"cookMinutes":0,"ingredients":[{"ingredientId":"oats-dry","grams":200,"display":"2½ cups","prep":"dry"},{"ingredientId":"skyr-plain","grams":400,"display":"400 g"},{"ingredientId":"milk","grams":400,"display":"400 ml"},{"ingredientId":"apple","grams":360,"display":"2 apples","prep":"grated"},{"ingredientId":"raisins","grams":40,"display":"4 tbsp"},{"ingredientId":"walnuts","grams":40,"display":"6 tbsp","prep":"chopped"},{"ingredientId":"spices","grams":1,"display":"cinnamon"}],"steps":["Mix the oats, milk, skyr, raisins and cinnamon in a large container.","Grate in the apples, skin and all, and stir through.","Cover and chill overnight. Scoop into bowls and top with walnuts."],"substitutions":[{"ingredientId":"milk","alternatives":["soy-drink","oat-drink"]},{"ingredientId":"skyr-plain","alternatives":["greek-yogurt-0","soy-yogurt"]}],"notes":"Keeps 3 days in the fridge. Add the nuts just before eating so they stay crunchy."}'::jsonb),
  ('tuna-white-bean-salad', 'Tuna & white bean salad', 'lunch', 1, '{"id":"tuna-white-bean-salad","name":"Tuna & white bean salad","meal":"lunch","servings":1,"prepMinutes":8,"cookMinutes":0,"ingredients":[{"ingredientId":"tuna-canned","grams":120,"display":"1 can","prep":"drained"},{"ingredientId":"white-beans-cooked","grams":120,"display":"½ can","prep":"drained, rinsed"},{"ingredientId":"tomato","grams":80,"display":"1 small tomato","prep":"chopped"},{"ingredientId":"cucumber","grams":60,"display":"¼ cucumber","prep":"chopped"},{"ingredientId":"spring-onion","grams":15,"display":"1 spring onion","prep":"sliced"},{"ingredientId":"olive-oil","grams":7,"display":"½ tbsp"},{"ingredientId":"lemon-juice","grams":10,"display":"2 tsp"},{"ingredientId":"spices","grams":1,"display":"salt & pepper"}],"steps":["Whisk the oil, lemon juice, salt and pepper in a bowl.","Add the beans, tomato, cucumber and spring onion and toss.","Flake the tuna over the top in large pieces."],"substitutions":[{"ingredientId":"tuna-canned","alternatives":["sardines-canned","chicken-breast-cooked"]},{"ingredientId":"white-beans-cooked","alternatives":["chickpeas-cooked","kidney-beans-cooked"]}],"notes":"Packs well for work: keep the dressing separate until lunch."}'::jsonb),
  ('chicken-caesar-skyr-wrap', 'Chicken Caesar-style wrap', 'lunch', 1, '{"id":"chicken-caesar-skyr-wrap","name":"Chicken Caesar-style wrap","meal":"lunch","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"tortilla-wheat","grams":45,"display":"1 tortilla"},{"ingredientId":"chicken-breast-cooked","grams":100,"display":"100 g","prep":"sliced"},{"ingredientId":"lettuce","grams":40,"display":"1 cup","prep":"shredded"},{"ingredientId":"skyr-plain","grams":50,"display":"3 tbsp"},{"ingredientId":"parmesan","grams":10,"display":"2 tbsp","prep":"finely grated"},{"ingredientId":"lemon-juice","grams":5,"display":"1 tsp"},{"ingredientId":"mustard","grams":5,"display":"1 tsp"}],"steps":["Stir the skyr, parmesan, lemon juice and mustard into a quick dressing.","Toss the lettuce and chicken in the dressing.","Pile onto the tortilla, fold in the sides and roll up. Cut in half."],"substitutions":[{"ingredientId":"chicken-breast-cooked","alternatives":["tuna-canned","tofu-firm"]},{"ingredientId":"tortilla-wheat","alternatives":["pita-wholewheat","tortilla-corn"]}]}'::jsonb),
  ('egg-cottage-cheese-rye', 'Egg & cottage cheese open sandwich', 'lunch', 1, '{"id":"egg-cottage-cheese-rye","name":"Egg & cottage cheese open sandwich","meal":"lunch","servings":1,"prepMinutes":5,"cookMinutes":8,"ingredients":[{"ingredientId":"egg","grams":100,"display":"2 eggs"},{"ingredientId":"cottage-cheese","grams":150,"display":"150 g"},{"ingredientId":"rye-bread","grams":64,"display":"2 slices"},{"ingredientId":"tomato","grams":60,"display":"½ tomato","prep":"sliced"},{"ingredientId":"spring-onion","grams":10,"display":"½ spring onion","prep":"sliced"},{"ingredientId":"spices","grams":1,"display":"salt, pepper & paprika"}],"steps":["Boil the eggs for 8 minutes, then cool them in cold water and peel.","Spread the cottage cheese thickly over the rye bread.","Top with tomato, sliced egg and spring onion, then season."],"substitutions":[{"ingredientId":"cottage-cheese","alternatives":["skyr-plain","hummus"]},{"ingredientId":"rye-bread","alternatives":["rye-crispbread","wholewheat-bread"]}],"notes":"Boil a batch of eggs at the start of the week to make this a 5-minute lunch."}'::jsonb),
  ('prawn-rice-noodle-salad', 'Prawn & edamame rice-noodle salad', 'lunch', 1, '{"id":"prawn-rice-noodle-salad","name":"Prawn & edamame rice-noodle salad","meal":"lunch","servings":1,"prepMinutes":10,"cookMinutes":3,"ingredients":[{"ingredientId":"rice-noodles-cooked","grams":150,"display":"150 g cooked (about 50 g dry)"},{"ingredientId":"shrimp-cooked","grams":120,"display":"120 g"},{"ingredientId":"edamame","grams":50,"display":"⅓ cup","prep":"thawed"},{"ingredientId":"carrot","grams":50,"display":"1 small carrot","prep":"grated"},{"ingredientId":"cucumber","grams":60,"display":"¼ cucumber","prep":"cut into sticks"},{"ingredientId":"lime-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"sesame-oil","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":1,"display":"chilli flakes & salt"}],"steps":["Soak or boil the noodles as the packet says, then rinse under cold water and drain well.","Whisk the lime juice, sesame oil, chilli and a pinch of salt.","Toss the noodles with the vegetables, edamame and dressing.","Top with the prawns."],"substitutions":[{"ingredientId":"shrimp-cooked","alternatives":["chicken-breast-cooked","tofu-firm"]},{"ingredientId":"rice-noodles-cooked","alternatives":["rice-white-cooked","quinoa-cooked"]}]}'::jsonb),
  ('chickpea-feta-couscous', 'Chickpea & feta couscous salad', 'lunch', 1, '{"id":"chickpea-feta-couscous","name":"Chickpea & feta couscous salad","meal":"lunch","servings":1,"prepMinutes":10,"cookMinutes":0,"ingredients":[{"ingredientId":"couscous-dry","grams":60,"display":"⅓ cup","prep":"dry"},{"ingredientId":"chickpeas-cooked","grams":120,"display":"½ can","prep":"drained"},{"ingredientId":"feta","grams":40,"display":"40 g","prep":"crumbled"},{"ingredientId":"cucumber","grams":80,"display":"¼ cucumber","prep":"diced"},{"ingredientId":"tomato","grams":80,"display":"1 small tomato","prep":"diced"},{"ingredientId":"lemon-juice","grams":10,"display":"2 tsp"},{"ingredientId":"olive-oil","grams":7,"display":"½ tbsp"},{"ingredientId":"spices","grams":1,"display":"salt, pepper & dried mint"}],"steps":["Pour 80 ml boiling water over the couscous, cover and leave for 5 minutes, then fluff with a fork.","Stir in the lemon juice, oil and seasoning.","Fold through the chickpeas, cucumber and tomato, then crumble the feta over."],"substitutions":[{"ingredientId":"couscous-dry","alternatives":["quinoa-dry"]},{"ingredientId":"feta","alternatives":["cottage-cheese"]}]}'::jsonb),
  ('bean-cheese-quesadilla', 'Bean & cheese quesadilla', 'lunch', 1, '{"id":"bean-cheese-quesadilla","name":"Bean & cheese quesadilla","meal":"lunch","servings":1,"prepMinutes":5,"cookMinutes":6,"ingredients":[{"ingredientId":"tortilla-wheat","grams":90,"display":"2 tortillas"},{"ingredientId":"kidney-beans-cooked","grams":100,"display":"⅖ can","prep":"drained, mashed"},{"ingredientId":"mozzarella-light","grams":40,"display":"40 g","prep":"grated"},{"ingredientId":"bell-pepper","grams":50,"display":"½ small pepper","prep":"finely diced"},{"ingredientId":"spring-onion","grams":15,"display":"1 spring onion","prep":"sliced"},{"ingredientId":"spices","grams":1,"display":"cumin & chilli"}],"steps":["Mash the beans roughly with the spices and spread over one tortilla.","Scatter with pepper, spring onion and cheese, then lay the second tortilla on top.","Cook in a dry pan over medium heat for about 3 minutes per side until crisp and melted. Cut into wedges."],"substitutions":[{"ingredientId":"kidney-beans-cooked","alternatives":["black-beans-cooked"]},{"ingredientId":"mozzarella-light","alternatives":["gouda"]}]}'::jsonb),
  ('sardines-tomato-rye', 'Sardines & tomato on rye', 'lunch', 1, '{"id":"sardines-tomato-rye","name":"Sardines & tomato on rye","meal":"lunch","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"rye-bread","grams":64,"display":"2 slices"},{"ingredientId":"sardines-canned","grams":100,"display":"1 can","prep":"drained"},{"ingredientId":"tomato","grams":80,"display":"1 small tomato","prep":"sliced"},{"ingredientId":"spring-onion","grams":10,"display":"½ spring onion","prep":"sliced"},{"ingredientId":"lemon-juice","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":1,"display":"black pepper"}],"steps":["Lay the tomato slices on the rye bread.","Mash the sardines lightly with lemon juice and pepper and spoon on top.","Finish with the spring onion."],"substitutions":[{"ingredientId":"sardines-canned","alternatives":["tuna-canned","smoked-salmon"]},{"ingredientId":"rye-bread","alternatives":["rye-crispbread","rice-cakes"]}]}'::jsonb),
  ('lentil-herb-salad', 'Lemony lentil salad with seeds', 'lunch', 1, '{"id":"lentil-herb-salad","name":"Lemony lentil salad with seeds","meal":"lunch","servings":1,"prepMinutes":8,"cookMinutes":0,"ingredients":[{"ingredientId":"lentils-cooked","grams":200,"display":"1 cup (½ can)","prep":"drained"},{"ingredientId":"cucumber","grams":80,"display":"¼ cucumber","prep":"diced"},{"ingredientId":"tomato","grams":80,"display":"1 small tomato","prep":"diced"},{"ingredientId":"spring-onion","grams":15,"display":"1 spring onion","prep":"sliced"},{"ingredientId":"lemon-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"olive-oil","grams":10,"display":"¾ tbsp"},{"ingredientId":"pumpkin-seeds","grams":15,"display":"1½ tbsp"},{"ingredientId":"spices","grams":2,"display":"parsley, salt & pepper"}],"steps":["Whisk the lemon juice, oil, salt and pepper in a bowl.","Add the lentils, cucumber, tomato, spring onion and herbs and toss well.","Scatter the pumpkin seeds on top."],"substitutions":[{"ingredientId":"lentils-cooked","alternatives":["chickpeas-cooked","white-beans-cooked"]},{"ingredientId":"pumpkin-seeds","alternatives":["sunflower-seeds"]}],"notes":"Gets better after an hour in the fridge."}'::jsonb),
  ('chicken-quinoa-salad-box', 'Chicken & quinoa salad box', 'lunch', 1, '{"id":"chicken-quinoa-salad-box","name":"Chicken & quinoa salad box","meal":"lunch","servings":1,"prepMinutes":8,"cookMinutes":0,"ingredients":[{"ingredientId":"quinoa-cooked","grams":150,"display":"¾ cup","prep":"cooked, cooled"},{"ingredientId":"chicken-breast-cooked","grams":120,"display":"120 g","prep":"sliced"},{"ingredientId":"spinach","grams":30,"display":"1 large handful"},{"ingredientId":"bell-pepper","grams":60,"display":"½ pepper","prep":"diced"},{"ingredientId":"feta","grams":30,"display":"30 g","prep":"crumbled"},{"ingredientId":"lemon-juice","grams":10,"display":"2 tsp"},{"ingredientId":"olive-oil","grams":7,"display":"½ tbsp"}],"steps":["Put the spinach in the bottom of a lunch box.","Mix the quinoa with the lemon juice and oil and spoon on top.","Add the pepper, chicken and feta."],"substitutions":[{"ingredientId":"chicken-breast-cooked","alternatives":["tuna-canned","chickpeas-cooked"]},{"ingredientId":"quinoa-cooked","alternatives":["rice-white-cooked","pasta-cooked"]}]}'::jsonb),
  ('tofu-edamame-noodle-bowl', 'Tofu & edamame noodle bowl', 'lunch', 1, '{"id":"tofu-edamame-noodle-bowl","name":"Tofu & edamame noodle bowl","meal":"lunch","servings":1,"prepMinutes":8,"cookMinutes":8,"ingredients":[{"ingredientId":"tofu-firm","grams":150,"display":"150 g","prep":"cubed"},{"ingredientId":"edamame","grams":80,"display":"½ cup","prep":"thawed"},{"ingredientId":"rice-noodles-cooked","grams":150,"display":"150 g cooked (about 50 g dry)"},{"ingredientId":"carrot","grams":50,"display":"1 small carrot","prep":"grated"},{"ingredientId":"spring-onion","grams":15,"display":"1 spring onion","prep":"sliced"},{"ingredientId":"soy-sauce","grams":10,"display":"2 tsp"},{"ingredientId":"sesame-oil","grams":5,"display":"1 tsp"},{"ingredientId":"lime-juice","grams":10,"display":"2 tsp"}],"steps":["Fry the tofu in the sesame oil over medium-high heat for 6 minutes, turning, until golden.","Add the edamame and soy sauce and toss for 1 minute.","Cook the noodles as the packet says and drain.","Pile the noodles into a bowl with the tofu, carrot and spring onion, then squeeze over the lime."],"substitutions":[{"ingredientId":"tofu-firm","alternatives":["tempeh","chicken-breast-raw"]},{"ingredientId":"rice-noodles-cooked","alternatives":["rice-white-cooked"]}]}'::jsonb),
  ('turkey-lettuce-cups', 'Ginger turkey lettuce cups', 'lunch', 1, '{"id":"turkey-lettuce-cups","name":"Ginger turkey lettuce cups","meal":"lunch","servings":1,"prepMinutes":5,"cookMinutes":10,"ingredients":[{"ingredientId":"turkey-mince-raw","grams":150,"display":"150 g","prep":"raw"},{"ingredientId":"lettuce","grams":60,"display":"6 leaves"},{"ingredientId":"carrot","grams":40,"display":"½ carrot","prep":"grated"},{"ingredientId":"spring-onion","grams":15,"display":"1 spring onion","prep":"sliced"},{"ingredientId":"ginger","grams":5,"display":"1 tsp","prep":"grated"},{"ingredientId":"soy-sauce","grams":10,"display":"2 tsp"},{"ingredientId":"rapeseed-oil","grams":5,"display":"1 tsp"},{"ingredientId":"rice-white-cooked","grams":100,"display":"⅔ cup","prep":"cooked"}],"steps":["Fry the turkey in the oil over high heat for 6–7 minutes, breaking it up, until browned and cooked through.","Stir in the ginger and soy sauce and cook 1 more minute.","Spoon rice and turkey into the lettuce leaves and top with carrot and spring onion."],"substitutions":[{"ingredientId":"turkey-mince-raw","alternatives":["chicken-thigh-raw","tofu-firm"]},{"ingredientId":"rice-white-cooked","alternatives":["rice-noodles-cooked","quinoa-cooked"]}]}'::jsonb),
  ('cottage-cheese-veg-pitta', 'Cottage cheese & veg pitta', 'lunch', 1, '{"id":"cottage-cheese-veg-pitta","name":"Cottage cheese & veg pitta","meal":"lunch","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"pita-wholewheat","grams":64,"display":"1 pitta"},{"ingredientId":"cottage-cheese","grams":150,"display":"150 g"},{"ingredientId":"cucumber","grams":50,"display":"5 cm piece","prep":"diced"},{"ingredientId":"tomato","grams":50,"display":"½ small tomato","prep":"diced"},{"ingredientId":"spinach","grams":20,"display":"a handful"},{"ingredientId":"spices","grams":1,"display":"pepper & chilli flakes"}],"steps":["Warm the pitta briefly and cut it open into a pocket.","Mix the cottage cheese with the cucumber, tomato and seasoning.","Line the pitta with spinach and spoon in the filling."],"substitutions":[{"ingredientId":"cottage-cheese","alternatives":["hummus","skyr-plain"]},{"ingredientId":"pita-wholewheat","alternatives":["tortilla-wheat","wholewheat-bread"]}]}'::jsonb),
  ('white-bean-spinach-soup', 'White bean, tomato & spinach soup', 'lunch', 2, '{"id":"white-bean-spinach-soup","name":"White bean, tomato & spinach soup","meal":"lunch","servings":2,"prepMinutes":5,"cookMinutes":15,"ingredients":[{"ingredientId":"white-beans-cooked","grams":480,"display":"2 cans","prep":"drained"},{"ingredientId":"tomatoes-canned","grams":400,"display":"1 can"},{"ingredientId":"vegetable-stock","grams":500,"display":"500 ml"},{"ingredientId":"onion","grams":100,"display":"1 onion","prep":"chopped"},{"ingredientId":"garlic","grams":6,"display":"2 cloves","prep":"chopped"},{"ingredientId":"spinach","grams":100,"display":"3 large handfuls"},{"ingredientId":"olive-oil","grams":10,"display":"¾ tbsp"},{"ingredientId":"spices","grams":2,"display":"dried thyme, salt & pepper"}],"steps":["Soften the onion and garlic in the oil for 4 minutes.","Add the beans, tomatoes, stock and thyme and simmer for 10 minutes.","Mash some of the beans against the side of the pan to thicken the soup.","Stir in the spinach until wilted and season to taste."],"substitutions":[{"ingredientId":"white-beans-cooked","alternatives":["chickpeas-cooked","kidney-beans-cooked"]},{"ingredientId":"spinach","alternatives":["cabbage"]}],"notes":"Freezes well. Many stock cubes contain celery: check the label if that matters to you."}'::jsonb),
  ('chicken-egg-fried-rice', 'Chicken & egg fried rice', 'lunch', 1, '{"id":"chicken-egg-fried-rice","name":"Chicken & egg fried rice","meal":"lunch","servings":1,"prepMinutes":5,"cookMinutes":8,"ingredients":[{"ingredientId":"rice-white-cooked","grams":200,"display":"1¼ cups","prep":"cooked, cold"},{"ingredientId":"chicken-breast-cooked","grams":80,"display":"80 g","prep":"diced"},{"ingredientId":"egg","grams":100,"display":"2 eggs","prep":"beaten"},{"ingredientId":"peas-green","grams":80,"display":"½ cup","prep":"frozen"},{"ingredientId":"spring-onion","grams":15,"display":"1 spring onion","prep":"sliced"},{"ingredientId":"soy-sauce","grams":10,"display":"2 tsp"},{"ingredientId":"rapeseed-oil","grams":7,"display":"½ tbsp"}],"steps":["Heat the oil in a large pan or wok over high heat and cook the peas for 1 minute.","Push them aside, pour in the eggs and scramble until just set.","Add the rice and chicken and stir-fry for 3–4 minutes until piping hot.","Season with soy sauce and scatter with spring onion."],"substitutions":[{"ingredientId":"chicken-breast-cooked","alternatives":["shrimp-cooked","tofu-firm"]},{"ingredientId":"rice-white-cooked","alternatives":["quinoa-cooked"]}],"notes":"Day-old rice fries best. Cool cooked rice quickly and keep it in the fridge for no more than a day."}'::jsonb),
  ('tuna-melt-rye', 'Open tuna melt on rye', 'lunch', 1, '{"id":"tuna-melt-rye","name":"Open tuna melt on rye","meal":"lunch","servings":1,"prepMinutes":5,"cookMinutes":4,"ingredients":[{"ingredientId":"rye-bread","grams":64,"display":"2 slices"},{"ingredientId":"tuna-canned","grams":120,"display":"1 can","prep":"drained"},{"ingredientId":"skyr-plain","grams":30,"display":"2 tbsp"},{"ingredientId":"gouda","grams":20,"display":"1 slice"},{"ingredientId":"spring-onion","grams":10,"display":"½ spring onion","prep":"sliced"},{"ingredientId":"tomato","grams":60,"display":"½ tomato","prep":"sliced"}],"steps":["Heat the grill. Mix the tuna with the skyr and spring onion.","Toast the rye bread lightly, then spread with the tuna mix.","Top with tomato and cheese and grill for 3–4 minutes until bubbling."],"substitutions":[{"ingredientId":"tuna-canned","alternatives":["sardines-canned","chicken-breast-cooked"]},{"ingredientId":"gouda","alternatives":["mozzarella-light"]}]}'::jsonb),
  ('haddock-potatoes-green-beans', 'Pan-fried haddock, potatoes & green beans', 'dinner', 2, '{"id":"haddock-potatoes-green-beans","name":"Pan-fried haddock, potatoes & green beans","meal":"dinner","servings":2,"prepMinutes":5,"cookMinutes":20,"ingredients":[{"ingredientId":"haddock-raw","grams":300,"display":"2 fillets (300 g)"},{"ingredientId":"potato-raw","grams":400,"display":"400 g","prep":"halved"},{"ingredientId":"green-beans","grams":200,"display":"2 cups","prep":"trimmed"},{"ingredientId":"olive-oil","grams":10,"display":"¾ tbsp"},{"ingredientId":"lemon-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"spices","grams":2,"display":"salt, pepper & dill"}],"steps":["Boil the potatoes in salted water for 15 minutes, adding the green beans for the last 4.","Pat the haddock dry and season with salt and pepper.","Fry in the oil over medium-high heat for 3 minutes, flip gently and cook 2 minutes more until it flakes.","Drain the vegetables and serve with the fish, a squeeze of lemon and dill."],"substitutions":[{"ingredientId":"haddock-raw","alternatives":["cod-raw","salmon-raw"]},{"ingredientId":"potato-raw","alternatives":["sweet-potato-raw","rice-white-dry"]}]}'::jsonb),
  ('lamb-couscous-skyr', 'Spiced lamb couscous with skyr', 'dinner', 2, '{"id":"lamb-couscous-skyr","name":"Spiced lamb couscous with skyr","meal":"dinner","servings":2,"prepMinutes":5,"cookMinutes":15,"ingredients":[{"ingredientId":"lamb-mince-raw","grams":250,"display":"250 g","prep":"raw"},{"ingredientId":"couscous-dry","grams":120,"display":"⅔ cup","prep":"dry"},{"ingredientId":"zucchini","grams":150,"display":"¾ courgette","prep":"diced"},{"ingredientId":"onion","grams":80,"display":"¾ onion","prep":"chopped"},{"ingredientId":"tomatoes-canned","grams":200,"display":"½ can"},{"ingredientId":"skyr-plain","grams":100,"display":"100 g"},{"ingredientId":"spices","grams":4,"display":"cumin, cinnamon, salt & pepper"}],"steps":["Brown the lamb in a dry pan over high heat for 5 minutes. Spoon off excess fat.","Add the onion, courgette and spices and cook 4 minutes.","Stir in the tomatoes and simmer for 5 minutes.","Meanwhile pour 160 ml boiling water over the couscous, cover for 5 minutes and fluff.","Serve the lamb over the couscous with a spoonful of skyr."],"substitutions":[{"ingredientId":"lamb-mince-raw","alternatives":["beef-mince-10-raw","turkey-mince-raw"]},{"ingredientId":"couscous-dry","alternatives":["quinoa-dry","rice-white-dry"]}]}'::jsonb),
  ('cod-white-bean-tomato', 'One-pan cod with tomato & white beans', 'dinner', 2, '{"id":"cod-white-bean-tomato","name":"One-pan cod with tomato & white beans","meal":"dinner","servings":2,"prepMinutes":5,"cookMinutes":15,"ingredients":[{"ingredientId":"cod-raw","grams":300,"display":"2 fillets (300 g)"},{"ingredientId":"white-beans-cooked","grams":240,"display":"1 can","prep":"drained"},{"ingredientId":"tomatoes-canned","grams":400,"display":"1 can"},{"ingredientId":"garlic","grams":6,"display":"2 cloves","prep":"sliced"},{"ingredientId":"spinach","grams":60,"display":"2 handfuls"},{"ingredientId":"olive-oil","grams":10,"display":"¾ tbsp"},{"ingredientId":"spices","grams":2,"display":"paprika, salt & pepper"}],"steps":["Warm the oil and garlic in a wide pan for 1 minute without letting it brown.","Add the tomatoes, beans and paprika and simmer for 5 minutes.","Season the cod, nestle it into the sauce, cover and cook on low for 7–8 minutes until it flakes.","Lift out the fish, stir the spinach into the sauce until wilted and serve together."],"substitutions":[{"ingredientId":"cod-raw","alternatives":["haddock-raw","salmon-raw"]},{"ingredientId":"white-beans-cooked","alternatives":["chickpeas-cooked"]}]}'::jsonb),
  ('turkey-bolognese-batch', 'Turkey bolognese', 'dinner', 4, '{"id":"turkey-bolognese-batch","name":"Turkey bolognese","meal":"dinner","servings":4,"prepMinutes":10,"cookMinutes":25,"ingredients":[{"ingredientId":"turkey-mince-raw","grams":500,"display":"500 g","prep":"raw"},{"ingredientId":"pasta-dry","grams":320,"display":"320 g","prep":"dry"},{"ingredientId":"tomatoes-canned","grams":800,"display":"2 cans"},{"ingredientId":"onion","grams":150,"display":"1 large onion","prep":"chopped"},{"ingredientId":"carrot","grams":120,"display":"2 carrots","prep":"grated"},{"ingredientId":"garlic","grams":9,"display":"3 cloves","prep":"chopped"},{"ingredientId":"olive-oil","grams":10,"display":"¾ tbsp"},{"ingredientId":"spices","grams":4,"display":"oregano, salt & pepper"}],"steps":["Soften the onion, carrot and garlic in the oil for 5 minutes.","Add the turkey and cook over high heat, breaking it up, until no longer pink.","Stir in the tomatoes and oregano and simmer for 15–20 minutes until thick.","Cook the pasta as the packet says, drain and serve with the sauce."],"substitutions":[{"ingredientId":"turkey-mince-raw","alternatives":["beef-mince-10-raw","lentils-dry"]},{"ingredientId":"pasta-dry","alternatives":["rice-white-dry"]}],"notes":"The sauce freezes well in portions for up to 3 months."}'::jsonb),
  ('soy-ginger-salmon-rice', 'Soy-ginger salmon with rice & broccoli', 'dinner', 2, '{"id":"soy-ginger-salmon-rice","name":"Soy-ginger salmon with rice & broccoli","meal":"dinner","servings":2,"prepMinutes":5,"cookMinutes":15,"ingredients":[{"ingredientId":"salmon-raw","grams":260,"display":"2 fillets (260 g)"},{"ingredientId":"rice-white-dry","grams":150,"display":"¾ cup","prep":"dry"},{"ingredientId":"broccoli","grams":250,"display":"1 small head","prep":"florets"},{"ingredientId":"soy-sauce","grams":20,"display":"1¼ tbsp"},{"ingredientId":"ginger","grams":10,"display":"1½ tbsp","prep":"grated"},{"ingredientId":"honey","grams":10,"display":"½ tbsp"},{"ingredientId":"spring-onion","grams":15,"display":"1 spring onion","prep":"sliced"}],"steps":["Start the rice cooking. Heat the oven to 200 °C (180 °C fan).","Mix the soy sauce, ginger and honey and brush over the salmon on a lined tray.","Roast for 12 minutes. Steam or boil the broccoli for the last 4–5 minutes of the rice.","Serve the salmon on the rice with the broccoli and spring onion."],"substitutions":[{"ingredientId":"salmon-raw","alternatives":["cod-raw","tofu-firm"]},{"ingredientId":"rice-white-dry","alternatives":["quinoa-dry"]}]}'::jsonb),
  ('pork-noodle-stir-fry', 'Pork & broccoli noodle stir-fry', 'dinner', 2, '{"id":"pork-noodle-stir-fry","name":"Pork & broccoli noodle stir-fry","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":8,"ingredients":[{"ingredientId":"pork-tenderloin-raw","grams":300,"display":"300 g","prep":"thinly sliced"},{"ingredientId":"rice-noodles-cooked","grams":300,"display":"300 g cooked (about 100 g dry)"},{"ingredientId":"bell-pepper","grams":120,"display":"1 pepper","prep":"sliced"},{"ingredientId":"broccoli","grams":150,"display":"1½ cups","prep":"small florets"},{"ingredientId":"soy-sauce","grams":20,"display":"1¼ tbsp"},{"ingredientId":"ginger","grams":10,"display":"1½ tbsp","prep":"grated"},{"ingredientId":"garlic","grams":6,"display":"2 cloves","prep":"chopped"},{"ingredientId":"rapeseed-oil","grams":10,"display":"¾ tbsp"}],"steps":["Prepare the noodles as the packet says and drain.","Stir-fry the pork in half the oil over high heat for 3 minutes, then tip onto a plate.","Add the rest of the oil, the broccoli, pepper, garlic and ginger and stir-fry for 3 minutes.","Return the pork with the noodles and soy sauce and toss until hot."],"substitutions":[{"ingredientId":"pork-tenderloin-raw","alternatives":["chicken-breast-raw","tofu-firm"]},{"ingredientId":"soy-sauce","alternatives":["lime-juice"]}]}'::jsonb),
  ('chicken-fajitas-skyr', 'Chicken fajitas with skyr', 'dinner', 2, '{"id":"chicken-fajitas-skyr","name":"Chicken fajitas with skyr","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":10,"ingredients":[{"ingredientId":"chicken-breast-raw","grams":300,"display":"2 breasts (300 g)","prep":"sliced"},{"ingredientId":"tortilla-wheat","grams":180,"display":"4 tortillas"},{"ingredientId":"bell-pepper","grams":150,"display":"1 large pepper","prep":"sliced"},{"ingredientId":"onion","grams":100,"display":"1 onion","prep":"sliced"},{"ingredientId":"skyr-plain","grams":100,"display":"100 g"},{"ingredientId":"lime-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"rapeseed-oil","grams":10,"display":"¾ tbsp"},{"ingredientId":"spices","grams":5,"display":"paprika, cumin, chilli & salt"}],"steps":["Toss the chicken with the spices.","Fry the pepper and onion in half the oil over high heat for 4 minutes, then push aside.","Add the remaining oil and the chicken and cook 5–6 minutes until cooked through. Squeeze over the lime.","Warm the tortillas and fill with chicken, vegetables and a spoon of skyr."],"substitutions":[{"ingredientId":"chicken-breast-raw","alternatives":["shrimp-cooked","tofu-firm"]},{"ingredientId":"tortilla-wheat","alternatives":["tortilla-corn"]},{"ingredientId":"skyr-plain","alternatives":["greek-yogurt-0","soy-yogurt"]}]}'::jsonb),
  ('prawn-tacos-cabbage', 'Prawn tacos with crunchy cabbage', 'dinner', 2, '{"id":"prawn-tacos-cabbage","name":"Prawn tacos with crunchy cabbage","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":5,"ingredients":[{"ingredientId":"shrimp-cooked","grams":200,"display":"200 g"},{"ingredientId":"tortilla-corn","grams":104,"display":"4 corn tortillas"},{"ingredientId":"cabbage","grams":100,"display":"1 cup","prep":"finely shredded"},{"ingredientId":"avocado","grams":70,"display":"½ avocado","prep":"sliced"},{"ingredientId":"skyr-plain","grams":60,"display":"4 tbsp"},{"ingredientId":"lime-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"spices","grams":2,"display":"chilli, garlic powder & salt"}],"steps":["Toss the cabbage with half the lime juice and a pinch of salt.","Warm the prawns in a hot pan with the spices for 2 minutes.","Stir the remaining lime juice into the skyr.","Warm the tortillas and fill with cabbage, prawns, avocado and the lime skyr."],"substitutions":[{"ingredientId":"shrimp-cooked","alternatives":["cod-raw","chicken-breast-cooked"]},{"ingredientId":"skyr-plain","alternatives":["greek-yogurt-0","soy-yogurt"]}]}'::jsonb),
  ('red-lentil-dal-batch', 'Red lentil dal with rice', 'dinner', 4, '{"id":"red-lentil-dal-batch","name":"Red lentil dal with rice","meal":"dinner","servings":4,"prepMinutes":10,"cookMinutes":25,"ingredients":[{"ingredientId":"lentils-dry","grams":300,"display":"1½ cups","prep":"red, rinsed"},{"ingredientId":"tomatoes-canned","grams":400,"display":"1 can"},{"ingredientId":"onion","grams":150,"display":"1 large onion","prep":"chopped"},{"ingredientId":"garlic","grams":9,"display":"3 cloves","prep":"chopped"},{"ingredientId":"ginger","grams":15,"display":"2½ tbsp","prep":"grated"},{"ingredientId":"vegetable-stock","grams":750,"display":"750 ml"},{"ingredientId":"rice-white-dry","grams":240,"display":"1¼ cups","prep":"dry"},{"ingredientId":"spices","grams":6,"display":"curry powder, turmeric, salt"}],"steps":["Soften the onion, garlic and ginger in a splash of the stock for 5 minutes.","Stir in the spices, then add the lentils, tomatoes and remaining stock.","Simmer for 20 minutes, stirring now and then, until the lentils break down.","Cook the rice while the dal simmers and serve together."],"substitutions":[{"ingredientId":"rice-white-dry","alternatives":["quinoa-dry"]},{"ingredientId":"tomatoes-canned","alternatives":["tomato"]}],"notes":"Thickens as it cools; loosen with water when reheating. Freezes well."}'::jsonb),
  ('peanut-tofu-green-beans', 'Peanut tofu with green beans & rice', 'dinner', 2, '{"id":"peanut-tofu-green-beans","name":"Peanut tofu with green beans & rice","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":15,"ingredients":[{"ingredientId":"tofu-firm","grams":300,"display":"300 g","prep":"pressed, cubed"},{"ingredientId":"green-beans","grams":200,"display":"2 cups","prep":"trimmed, halved"},{"ingredientId":"peanut-butter","grams":32,"display":"2 tbsp"},{"ingredientId":"soy-sauce","grams":20,"display":"1¼ tbsp"},{"ingredientId":"lime-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"garlic","grams":6,"display":"2 cloves","prep":"grated"},{"ingredientId":"rice-white-dry","grams":150,"display":"¾ cup","prep":"dry"},{"ingredientId":"rapeseed-oil","grams":10,"display":"¾ tbsp"}],"steps":["Start the rice. Whisk the peanut butter, soy sauce, lime, garlic and 3 tbsp hot water into a sauce.","Fry the tofu in the oil over medium-high heat for 8 minutes until golden on most sides.","Add the green beans and a splash of water, cover and steam for 4 minutes.","Pour in the sauce, toss for 1 minute and serve over the rice."],"substitutions":[{"ingredientId":"tofu-firm","alternatives":["tempeh","chicken-breast-raw"]},{"ingredientId":"peanut-butter","alternatives":["tahini"]}]}'::jsonb),
  ('two-bean-chilli-batch', 'Two-bean chilli', 'dinner', 4, '{"id":"two-bean-chilli-batch","name":"Two-bean chilli","meal":"dinner","servings":4,"prepMinutes":10,"cookMinutes":25,"ingredients":[{"ingredientId":"kidney-beans-cooked","grams":480,"display":"2 cans","prep":"drained"},{"ingredientId":"black-beans-cooked","grams":480,"display":"2 cans","prep":"drained"},{"ingredientId":"tomatoes-canned","grams":800,"display":"2 cans"},{"ingredientId":"onion","grams":150,"display":"1 large onion","prep":"chopped"},{"ingredientId":"bell-pepper","grams":150,"display":"1 large pepper","prep":"diced"},{"ingredientId":"garlic","grams":9,"display":"3 cloves","prep":"chopped"},{"ingredientId":"rice-white-dry","grams":240,"display":"1¼ cups","prep":"dry"},{"ingredientId":"spices","grams":8,"display":"chilli, cumin, smoked paprika, salt"}],"steps":["Soften the onion, pepper and garlic in a large pan with a splash of water for 5 minutes.","Add the spices and stir for 1 minute.","Add the tomatoes and both beans and simmer for 20 minutes until thick.","Cook the rice and serve with the chilli."],"substitutions":[{"ingredientId":"rice-white-dry","alternatives":["quinoa-dry"]},{"ingredientId":"kidney-beans-cooked","alternatives":["lentils-cooked","chickpeas-cooked"]}],"notes":"Freezes well. Top with skyr or avocado if you like."}'::jsonb),
  ('cauliflower-chickpea-traybake', 'Roast cauliflower & chickpeas with tahini', 'dinner', 2, '{"id":"cauliflower-chickpea-traybake","name":"Roast cauliflower & chickpeas with tahini","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":25,"ingredients":[{"ingredientId":"cauliflower","grams":400,"display":"1 small head","prep":"florets"},{"ingredientId":"chickpeas-cooked","grams":240,"display":"1 can","prep":"drained, dried"},{"ingredientId":"onion","grams":100,"display":"1 red onion","prep":"wedges"},{"ingredientId":"olive-oil","grams":15,"display":"1 tbsp"},{"ingredientId":"tahini","grams":30,"display":"2 tbsp"},{"ingredientId":"lemon-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"spinach","grams":60,"display":"2 handfuls"},{"ingredientId":"spices","grams":4,"display":"cumin, paprika, salt"}],"steps":["Heat the oven to 220 °C (200 °C fan).","Toss the cauliflower, chickpeas and onion with the oil and spices on a large tray.","Roast for 25 minutes, turning once, until browned at the edges.","Whisk the tahini with the lemon juice and 2–3 tbsp water. Toss the tray with the spinach and drizzle with the sauce."],"substitutions":[{"ingredientId":"chickpeas-cooked","alternatives":["white-beans-cooked"]},{"ingredientId":"cauliflower","alternatives":["broccoli","sweet-potato-raw"]}]}'::jsonb),
  ('lemon-chicken-couscous', 'Lemon chicken couscous with cucumber skyr', 'dinner', 2, '{"id":"lemon-chicken-couscous","name":"Lemon chicken couscous with cucumber skyr","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":12,"ingredients":[{"ingredientId":"chicken-breast-raw","grams":300,"display":"2 breasts (300 g)"},{"ingredientId":"couscous-dry","grams":120,"display":"⅔ cup","prep":"dry"},{"ingredientId":"cucumber","grams":100,"display":"⅓ cucumber","prep":"grated"},{"ingredientId":"skyr-plain","grams":150,"display":"150 g"},{"ingredientId":"lemon-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"garlic","grams":3,"display":"1 clove","prep":"grated"},{"ingredientId":"olive-oil","grams":10,"display":"¾ tbsp"},{"ingredientId":"spices","grams":3,"display":"oregano, salt & pepper"}],"steps":["Flatten the chicken slightly, rub with half the oil, oregano, salt and pepper.","Cook in a hot pan for 5–6 minutes per side until cooked through. Rest, then slice.","Pour 160 ml boiling water over the couscous with the rest of the oil and half the lemon juice; cover for 5 minutes.","Squeeze the grated cucumber, mix it into the skyr with the garlic and remaining lemon, and serve with the chicken and couscous."],"substitutions":[{"ingredientId":"chicken-breast-raw","alternatives":["chicken-thigh-raw","salmon-raw"]},{"ingredientId":"couscous-dry","alternatives":["quinoa-dry","rice-white-dry"]}]}'::jsonb),
  ('haddock-potato-hash', 'Creamy haddock & potato hash', 'dinner', 2, '{"id":"haddock-potato-hash","name":"Creamy haddock & potato hash","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":20,"ingredients":[{"ingredientId":"haddock-raw","grams":300,"display":"300 g"},{"ingredientId":"potato-raw","grams":400,"display":"400 g","prep":"peeled, chunks"},{"ingredientId":"onion","grams":100,"display":"1 onion","prep":"finely chopped"},{"ingredientId":"milk","grams":150,"display":"150 ml"},{"ingredientId":"butter","grams":15,"display":"1 tbsp"},{"ingredientId":"spices","grams":2,"display":"white pepper, salt & chives"}],"steps":["Boil the potatoes for 15 minutes until tender, then drain.","Meanwhile poach the haddock in the milk in a covered pan for 6–7 minutes. Lift out the fish and keep the milk.","Soften the onion in the butter, add the potatoes and some of the milk and mash roughly.","Flake in the fish, fold gently, season well and finish with chives."],"substitutions":[{"ingredientId":"haddock-raw","alternatives":["cod-raw"]},{"ingredientId":"milk","alternatives":["oat-drink","soy-drink"]}],"notes":"Inspired by Icelandic fish stew. Lovely with buttered rye bread on the side."}'::jsonb),
  ('lamb-cabbage-skillet', 'Lamb, cabbage & potato skillet', 'dinner', 2, '{"id":"lamb-cabbage-skillet","name":"Lamb, cabbage & potato skillet","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":20,"ingredients":[{"ingredientId":"lamb-mince-raw","grams":300,"display":"300 g","prep":"raw"},{"ingredientId":"cabbage","grams":300,"display":"¼ cabbage","prep":"shredded"},{"ingredientId":"potato-raw","grams":300,"display":"2 small potatoes","prep":"small cubes"},{"ingredientId":"carrot","grams":100,"display":"1½ carrots","prep":"sliced"},{"ingredientId":"onion","grams":100,"display":"1 onion","prep":"sliced"},{"ingredientId":"vegetable-stock","grams":200,"display":"200 ml"},{"ingredientId":"spices","grams":3,"display":"thyme, salt & pepper"}],"steps":["Brown the lamb in a large deep pan for 5 minutes and spoon off most of the fat.","Add the potato, carrot and onion and cook 3 minutes.","Pour in the stock, cover and simmer for 8 minutes.","Stir in the cabbage, cover again and cook 5 minutes more until everything is tender. Season."],"substitutions":[{"ingredientId":"lamb-mince-raw","alternatives":["beef-mince-10-raw","turkey-mince-raw"]},{"ingredientId":"potato-raw","alternatives":["sweet-potato-raw"]}]}'::jsonb),
  ('mushroom-spinach-pasta', 'Creamy mushroom & spinach pasta', 'dinner', 2, '{"id":"mushroom-spinach-pasta","name":"Creamy mushroom & spinach pasta","meal":"dinner","servings":2,"prepMinutes":5,"cookMinutes":12,"ingredients":[{"ingredientId":"pasta-dry","grams":160,"display":"160 g","prep":"dry"},{"ingredientId":"mushrooms","grams":200,"display":"3 cups","prep":"sliced"},{"ingredientId":"spinach","grams":100,"display":"3 large handfuls"},{"ingredientId":"cottage-cheese","grams":200,"display":"200 g"},{"ingredientId":"parmesan","grams":30,"display":"6 tbsp","prep":"grated"},{"ingredientId":"garlic","grams":6,"display":"2 cloves","prep":"chopped"},{"ingredientId":"olive-oil","grams":10,"display":"¾ tbsp"},{"ingredientId":"spices","grams":2,"display":"black pepper & nutmeg"}],"steps":["Cook the pasta as the packet says. Keep a mug of the cooking water.","Fry the mushrooms in the oil over high heat for 5 minutes, add the garlic for 1 minute.","Blend or whisk the cottage cheese and parmesan with a splash of pasta water until smooth.","Toss the pasta with the mushrooms, spinach and sauce off the heat, loosening with more water. Season."],"substitutions":[{"ingredientId":"cottage-cheese","alternatives":["skyr-plain"]},{"ingredientId":"pasta-dry","alternatives":["rice-white-dry"]}],"notes":"Keep the pan off the heat when adding the sauce so it stays smooth."}'::jsonb),
  ('tempeh-broccoli-rice', 'Maple-soy tempeh with broccoli rice', 'dinner', 2, '{"id":"tempeh-broccoli-rice","name":"Maple-soy tempeh with broccoli rice","meal":"dinner","servings":2,"prepMinutes":5,"cookMinutes":15,"ingredients":[{"ingredientId":"tempeh","grams":250,"display":"250 g","prep":"sliced"},{"ingredientId":"rice-white-dry","grams":150,"display":"¾ cup","prep":"dry"},{"ingredientId":"broccoli","grams":200,"display":"2 cups","prep":"florets"},{"ingredientId":"soy-sauce","grams":20,"display":"1¼ tbsp"},{"ingredientId":"maple-syrup","grams":10,"display":"½ tbsp"},{"ingredientId":"ginger","grams":5,"display":"1 tsp","prep":"grated"},{"ingredientId":"sesame-oil","grams":5,"display":"1 tsp"}],"steps":["Cook the rice, adding the broccoli for the last 4 minutes to steam on top.","Fry the tempeh in the sesame oil for 3 minutes per side until golden.","Mix the soy sauce, maple syrup and ginger, pour into the pan and let it bubble and coat the tempeh.","Serve over the rice and broccoli."],"substitutions":[{"ingredientId":"tempeh","alternatives":["tofu-firm","chicken-breast-raw"]},{"ingredientId":"maple-syrup","alternatives":["honey"]}]}'::jsonb),
  ('beef-broccoli-rice', 'Garlic beef & broccoli rice bowl', 'dinner', 2, '{"id":"beef-broccoli-rice","name":"Garlic beef & broccoli rice bowl","meal":"dinner","servings":2,"prepMinutes":5,"cookMinutes":12,"ingredients":[{"ingredientId":"beef-mince-10-raw","grams":300,"display":"300 g","prep":"raw"},{"ingredientId":"rice-white-dry","grams":150,"display":"¾ cup","prep":"dry"},{"ingredientId":"broccoli","grams":250,"display":"1 small head","prep":"small florets"},{"ingredientId":"soy-sauce","grams":20,"display":"1¼ tbsp"},{"ingredientId":"garlic","grams":9,"display":"3 cloves","prep":"chopped"},{"ingredientId":"ginger","grams":5,"display":"1 tsp","prep":"grated"},{"ingredientId":"spring-onion","grams":15,"display":"1 spring onion","prep":"sliced"}],"steps":["Start the rice.","Brown the beef in a hot pan for 5 minutes, breaking it up. Add the garlic and ginger for 1 minute.","Add the broccoli and 3 tbsp water, cover and cook 4 minutes until just tender.","Stir in the soy sauce and serve over rice with spring onion."],"substitutions":[{"ingredientId":"beef-mince-10-raw","alternatives":["turkey-mince-raw","lentils-dry"]},{"ingredientId":"soy-sauce","alternatives":["lime-juice"]}]}'::jsonb),
  ('tuna-pea-lemon-pasta', 'Lemony tuna & pea pasta', 'dinner', 2, '{"id":"tuna-pea-lemon-pasta","name":"Lemony tuna & pea pasta","meal":"dinner","servings":2,"prepMinutes":5,"cookMinutes":12,"ingredients":[{"ingredientId":"pasta-dry","grams":160,"display":"160 g","prep":"dry"},{"ingredientId":"tuna-canned","grams":240,"display":"2 cans","prep":"drained"},{"ingredientId":"peas-green","grams":150,"display":"1 cup","prep":"frozen"},{"ingredientId":"spinach","grams":60,"display":"2 handfuls"},{"ingredientId":"lemon-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"olive-oil","grams":15,"display":"1 tbsp"},{"ingredientId":"parmesan","grams":20,"display":"4 tbsp","prep":"grated"},{"ingredientId":"spices","grams":1,"display":"black pepper & chilli flakes"}],"steps":["Cook the pasta, adding the peas for the last 2 minutes.","Drain, keeping a little water, and return to the pan.","Stir through the spinach, tuna, oil, lemon juice and a splash of water until glossy.","Serve topped with parmesan, pepper and chilli."],"substitutions":[{"ingredientId":"tuna-canned","alternatives":["salmon-raw","chickpeas-cooked"]},{"ingredientId":"pasta-dry","alternatives":["rice-white-dry"]}]}'::jsonb),
