  ('cocoa-peanut-energy-balls', 'Cocoa peanut energy balls', 'snack', 4, '{"id":"cocoa-peanut-energy-balls","name":"Cocoa peanut energy balls","meal":"snack","servings":4,"prepMinutes":15,"cookMinutes":0,"ingredients":[{"ingredientId":"oats-dry","grams":100,"display":"1¼ cups","prep":"dry"},{"ingredientId":"peanut-butter","grams":64,"display":"4 tbsp"},{"ingredientId":"maple-syrup","grams":40,"display":"2 tbsp"},{"ingredientId":"cocoa-powder","grams":15,"display":"3 tbsp"},{"ingredientId":"chia-seeds","grams":20,"display":"1½ tbsp"}],"steps":["Stir everything together in a bowl until it clumps. Add 1–2 tsp water if it is too dry.","Roll into 12 walnut-sized balls with damp hands.","Chill for 30 minutes to firm up."],"substitutions":[{"ingredientId":"peanut-butter","alternatives":["tahini"]},{"ingredientId":"maple-syrup","alternatives":["honey"]}],"notes":"Three balls per serving. Keeps a week in the fridge."}'::jsonb),
  ('chicken-sweet-potato-hash', 'Chicken & sweet potato breakfast hash', 'breakfast', 1, '{"id":"chicken-sweet-potato-hash","name":"Chicken & sweet potato breakfast hash","meal":"breakfast","servings":1,"prepMinutes":8,"cookMinutes":12,"ingredients":[{"ingredientId":"chicken-thigh-raw","grams":150,"display":"150 g","prep":"diced"},{"ingredientId":"sweet-potato-raw","grams":150,"display":"1 small","prep":"cut into 1 cm cubes"},{"ingredientId":"bell-pepper","grams":60,"display":"½ pepper","prep":"diced"},{"ingredientId":"onion","grams":40,"display":"¼ onion","prep":"sliced"},{"ingredientId":"spinach","grams":30,"display":"1 large handful"},{"ingredientId":"rapeseed-oil","grams":7,"display":"½ tbsp"},{"ingredientId":"spices","grams":2,"display":"smoked paprika, salt & pepper"}],"steps":["Microwave the sweet potato cubes in a covered bowl for 3 minutes until just soft.","Heat the oil in a large frying pan and brown the chicken with the paprika for 5 minutes.","Add the sweet potato, pepper and onion and fry for 6–7 minutes until crisp at the edges and the chicken is cooked through.","Stir in the spinach until it wilts, season and serve."],"substitutions":[{"ingredientId":"chicken-thigh-raw","alternatives":["turkey-breast-raw","tofu-firm"]},{"ingredientId":"sweet-potato-raw","alternatives":["potato-raw"]}]}'::jsonb),
