  ('chicken-chickpea-curry-batch', 'Chicken & chickpea coconut curry', 'dinner', 4, '{"id":"chicken-chickpea-curry-batch","name":"Chicken & chickpea coconut curry","meal":"dinner","servings":4,"prepMinutes":15,"cookMinutes":30,"ingredients":[{"ingredientId":"chicken-thigh-raw","grams":600,"display":"600 g","prep":"diced"},{"ingredientId":"chickpeas-cooked","grams":240,"display":"1 can","prep":"drained"},{"ingredientId":"coconut-milk-light","grams":400,"display":"1 can"},{"ingredientId":"tomatoes-canned","grams":400,"display":"1 can"},{"ingredientId":"onion","grams":110,"display":"1 onion","prep":"diced"},{"ingredientId":"rapeseed-oil","grams":14,"display":"1 tbsp"},{"ingredientId":"spices","grams":4,"display":"curry powder, cumin & salt"},{"ingredientId":"rice-white-dry","grams":280,"display":"1½ cups","prep":"dry"}],"steps":["Fry the onion in the oil in a large pot for 5 minutes until soft.","Add the chicken and spices and stir for 3 minutes.","Add the tomatoes, coconut milk and chickpeas and simmer for 25 minutes until the chicken is tender.","Meanwhile, cook the rice and serve the curry over it."],"substitutions":[{"ingredientId":"chicken-thigh-raw","alternatives":["tofu-firm","turkey-breast-raw"]},{"ingredientId":"chickpeas-cooked","alternatives":["lentils-cooked"]}],"notes":"Keeps 3 days in the fridge; freeze the curry without the rice."}'::jsonb),
  ('lemon-herb-chicken-potatoes', 'Lemon herb chicken with roast potatoes', 'dinner', 2, '{"id":"lemon-herb-chicken-potatoes","name":"Lemon herb chicken with roast potatoes","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":40,"ingredients":[{"ingredientId":"chicken-breast-raw","grams":320,"display":"2 breasts"},{"ingredientId":"potato-raw","grams":450,"display":"3 medium","prep":"cut into chunks"},{"ingredientId":"green-beans","grams":200,"display":"2 cups","prep":"trimmed"},{"ingredientId":"lemon-juice","grams":30,"display":"2 tbsp"},{"ingredientId":"olive-oil","grams":14,"display":"1 tbsp"},{"ingredientId":"garlic","grams":6,"display":"2 cloves","prep":"crushed"},{"ingredientId":"spices","grams":3,"display":"dried oregano, salt & pepper"}],"steps":["Heat the oven to 210°C. Toss the potatoes with half the oil and roast for 20 minutes.","Rub the chicken with the lemon juice, garlic, oregano, salt and the rest of the oil.","Add the chicken and green beans to the tray and roast for 20 minutes more, until the chicken is cooked through.","Spoon the pan juices over everything before serving."],"substitutions":[{"ingredientId":"chicken-breast-raw","alternatives":["pork-tenderloin-raw","cod-raw"]},{"ingredientId":"green-beans","alternatives":["broccoli"]}]}'::jsonb),
