  ('chicken-cacciatore-white-beans', 'Chicken cacciatore with white beans', 'dinner', 4, '{"id":"chicken-cacciatore-white-beans","name":"Chicken cacciatore with white beans","meal":"dinner","servings":4,"prepMinutes":15,"cookMinutes":35,"ingredients":[{"ingredientId":"chicken-thigh-raw","grams":600,"display":"600 g","prep":"large chunks"},{"ingredientId":"white-beans-cooked","grams":240,"display":"1 can","prep":"drained"},{"ingredientId":"tomatoes-canned","grams":400,"display":"1 can"},{"ingredientId":"potato-raw","grams":600,"display":"4 medium","prep":"cut into chunks"},{"ingredientId":"bell-pepper","grams":240,"display":"2 peppers","prep":"sliced"},{"ingredientId":"onion","grams":110,"display":"1 onion","prep":"sliced"},{"ingredientId":"olive-oil","grams":14,"display":"1 tbsp"},{"ingredientId":"spices","grams":3,"display":"rosemary, oregano, salt & pepper"}],"steps":["Brown the chicken in the oil in a large pot for 5 minutes.","Add the onion and peppers and cook for 3 minutes.","Add the tomatoes, potatoes, herbs and 200 ml water, cover and simmer for 25 minutes.","Stir in the beans for the last 5 minutes and season to taste."],"substitutions":[{"ingredientId":"chicken-thigh-raw","alternatives":["turkey-breast-raw","tofu-firm"]},{"ingredientId":"white-beans-cooked","alternatives":["chickpeas-cooked"]}],"notes":"Freezes well in portions."}'::jsonb),
  ('turkey-sage-patties-toast', 'Turkey sage patties on toast', 'breakfast', 1, '{"id":"turkey-sage-patties-toast","name":"Turkey sage patties on toast","meal":"breakfast","servings":1,"prepMinutes":10,"cookMinutes":10,"ingredients":[{"ingredientId":"turkey-mince-raw","grams":130,"display":"130 g"},{"ingredientId":"wholewheat-bread","grams":64,"display":"2 slices"},{"ingredientId":"tomato","grams":120,"display":"1 tomato","prep":"halved"},{"ingredientId":"spinach","grams":30,"display":"1 large handful"},{"ingredientId":"rapeseed-oil","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":2,"display":"dried sage, salt & pepper"}],"steps":["Mix the turkey with the sage, salt and pepper and shape into 3 small patties.","Fry in the oil for 4–5 minutes per side until cooked through, with the tomato halves cut side down alongside.","Wilt the spinach in the pan for the last minute.","Toast the bread and pile the patties, tomato and spinach on top."],"substitutions":[{"ingredientId":"turkey-mince-raw","alternatives":["chicken-breast-raw","tofu-firm"]},{"ingredientId":"wholewheat-bread","alternatives":["rye-bread"]}]}'::jsonb),
  ('turkey-meatball-bites', 'Baked turkey meatball bites', 'snack', 4, '{"id":"turkey-meatball-bites","name":"Baked turkey meatball bites","meal":"snack","servings":4,"prepMinutes":10,"cookMinutes":15,"ingredients":[{"ingredientId":"turkey-mince-raw","grams":400,"display":"400 g"},{"ingredientId":"oats-dry","grams":30,"display":"⅓ cup","prep":"dry"},{"ingredientId":"egg","grams":50,"display":"1 egg"},{"ingredientId":"spring-onion","grams":30,"display":"2 spring onions","prep":"finely sliced"},{"ingredientId":"spices","grams":3,"display":"garlic powder, paprika, salt & pepper"},{"ingredientId":"passata","grams":100,"display":"⅖ cup","prep":"warmed, to dip","optional":true}],"steps":["Heat the oven to 200°C and line a tray with baking paper.","Mix everything except the passata together and roll into 16 small balls.","Bake for 15 minutes until golden and cooked through.","Eat warm or cold, with warm passata to dip if you like."],"substitutions":[{"ingredientId":"turkey-mince-raw","alternatives":["beef-mince-10-raw","lamb-mince-raw"]}],"notes":"Keeps 3 days in the fridge, so it covers four snacks."}'::jsonb),
  ('turkey-tzatziki-feta-pitta', 'Turkey pitta with tzatziki & feta', 'lunch', 1, '{"id":"turkey-tzatziki-feta-pitta","name":"Turkey pitta with tzatziki & feta","meal":"lunch","servings":1,"prepMinutes":10,"cookMinutes":8,"ingredients":[{"ingredientId":"turkey-breast-raw","grams":150,"display":"150 g","prep":"sliced into strips"},{"ingredientId":"greek-yogurt-0","grams":150,"display":"150 g"},{"ingredientId":"feta","grams":30,"display":"30 g","prep":"crumbled"},{"ingredientId":"pita-wholewheat","grams":64,"display":"1 pitta"},{"ingredientId":"cucumber","grams":80,"display":"¼ cucumber"},{"ingredientId":"tomato","grams":60,"display":"½ tomato","prep":"sliced"},{"ingredientId":"olive-oil","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":2,"display":"garlic powder, dried mint, salt & pepper"}],"steps":["Season the turkey and fry in the oil for 6–7 minutes until cooked through.","Grate half the cucumber into the yogurt with the garlic powder and mint to make the tzatziki; slice the rest.","Warm the pitta and fill with the turkey, tomato, cucumber slices and tzatziki.","Crumble the feta over the top."],"substitutions":[{"ingredientId":"turkey-breast-raw","alternatives":["chicken-breast-raw","tofu-firm"]},{"ingredientId":"greek-yogurt-0","alternatives":["skyr-plain","soy-yogurt"]}]}'::jsonb),
  ('turkey-ginger-green-bean-noodles', 'Ginger turkey & green bean noodles', 'lunch', 1, '{"id":"turkey-ginger-green-bean-noodles","name":"Ginger turkey & green bean noodles","meal":"lunch","servings":1,"prepMinutes":10,"cookMinutes":8,"ingredients":[{"ingredientId":"turkey-breast-raw","grams":150,"display":"150 g","prep":"thinly sliced"},{"ingredientId":"rice-noodles-cooked","grams":150,"display":"1 nest, cooked (150 g)"},{"ingredientId":"green-beans","grams":100,"display":"1 cup","prep":"halved"},{"ingredientId":"spring-onion","grams":15,"display":"1 spring onion","prep":"sliced"},{"ingredientId":"ginger","grams":6,"display":"1 tbsp","prep":"grated"},{"ingredientId":"soy-sauce","grams":15,"display":"1 tbsp"},{"ingredientId":"sesame-oil","grams":5,"display":"1 tsp"},{"ingredientId":"lime-juice","grams":10,"display":"2 tsp"}],"steps":["Heat the sesame oil in a wok and stir-fry the turkey for 3 minutes.","Add the green beans and ginger with a splash of water and stir-fry for 3 minutes more.","Toss in the noodles, soy sauce and lime juice for 1–2 minutes until hot.","Scatter with spring onion."],"substitutions":[{"ingredientId":"turkey-breast-raw","alternatives":["chicken-breast-raw","tofu-firm"]},{"ingredientId":"green-beans","alternatives":["broccoli"]}]}'::jsonb),
  ('turkey-lentil-soup-batch', 'Turkey & red lentil soup', 'lunch', 4, '{"id":"turkey-lentil-soup-batch","name":"Turkey & red lentil soup","meal":"lunch","servings":4,"prepMinutes":15,"cookMinutes":30,"ingredients":[{"ingredientId":"turkey-mince-raw","grams":500,"display":"500 g"},{"ingredientId":"lentils-dry","grams":160,"display":"¾ cup","prep":"rinsed"},{"ingredientId":"carrot","grams":180,"display":"3 carrots","prep":"diced"},{"ingredientId":"onion","grams":110,"display":"1 onion","prep":"diced"},{"ingredientId":"tomatoes-canned","grams":400,"display":"1 can"},{"ingredientId":"vegetable-stock","grams":1000,"display":"4 cups"},{"ingredientId":"rapeseed-oil","grams":10,"display":"2 tsp"},{"ingredientId":"spices","grams":3,"display":"cumin, smoked paprika, salt & pepper"}],"steps":["Brown the turkey in the oil in a large pot for 5 minutes, breaking it up.","Add the onion and carrot and cook for 3 minutes.","Add the lentils, tomatoes, stock and spices and simmer for 25 minutes until the lentils are soft.","Season and serve, or cool and portion into boxes."],"substitutions":[{"ingredientId":"turkey-mince-raw","alternatives":["chicken-breast-raw","chickpeas-cooked"]}],"notes":"Freezes well; thicken with a little water when reheating."}'::jsonb),
  ('baked-turkey-meatballs-spaghetti', 'Baked turkey meatballs with spaghetti', 'dinner', 2, '{"id":"baked-turkey-meatballs-spaghetti","name":"Baked turkey meatballs with spaghetti","meal":"dinner","servings":2,"prepMinutes":15,"cookMinutes":25,"ingredients":[{"ingredientId":"turkey-mince-raw","grams":300,"display":"300 g"},{"ingredientId":"pasta-dry","grams":150,"display":"150 g spaghetti","prep":"dry"},{"ingredientId":"passata","grams":300,"display":"1¼ cups"},{"ingredientId":"onion","grams":55,"display":"½ onion","prep":"grated"},{"ingredientId":"garlic","grams":6,"display":"2 cloves","prep":"crushed"},{"ingredientId":"spinach","grams":60,"display":"2 handfuls"},{"ingredientId":"olive-oil","grams":7,"display":"½ tbsp"},{"ingredientId":"spices","grams":3,"display":"dried basil, oregano, salt & pepper"},{"ingredientId":"parmesan","grams":10,"display":"2 tbsp grated","optional":true}],"steps":["Heat the oven to 200°C. Mix the turkey with the grated onion and half the herbs and roll into 12 meatballs.","Bake in an ovenproof dish for 12 minutes.","Stir the passata with the garlic, oil and remaining herbs, pour over the meatballs and bake 10 minutes more.","Cook the spaghetti, adding the spinach just before draining. Serve with the meatballs and parmesan if using."],"substitutions":[{"ingredientId":"turkey-mince-raw","alternatives":["beef-mince-10-raw","lentils-cooked"]},{"ingredientId":"pasta-dry","alternatives":["rice-white-dry"]}]}'::jsonb),
  ('turkey-burgers-sweet-potato-wedges', 'Turkey burgers with sweet potato wedges', 'dinner', 2, '{"id":"turkey-burgers-sweet-potato-wedges","name":"Turkey burgers with sweet potato wedges","meal":"dinner","servings":2,"prepMinutes":15,"cookMinutes":30,"ingredients":[{"ingredientId":"turkey-mince-raw","grams":300,"display":"300 g"},{"ingredientId":"sweet-potato-raw","grams":400,"display":"2 medium","prep":"cut into wedges"},{"ingredientId":"egg-white","grams":33,"display":"1 egg white"},{"ingredientId":"lettuce","grams":50,"display":"4 large leaves"},{"ingredientId":"tomato","grams":100,"display":"1 tomato","prep":"sliced"},{"ingredientId":"mustard","grams":15,"display":"1 tbsp"},{"ingredientId":"olive-oil","grams":10,"display":"2 tsp"},{"ingredientId":"spices","grams":3,"display":"smoked paprika, garlic powder, salt & pepper"}],"steps":["Heat the oven to 220°C. Toss the wedges in the oil and half the paprika and roast for 30 minutes, turning once.","Mix the turkey with the egg white, garlic powder, remaining paprika, salt and pepper and shape 4 patties.","Bake the patties on a second tray for the last 18 minutes, until cooked through.","Wrap the burgers in lettuce with tomato and mustard and serve with the wedges."],"substitutions":[{"ingredientId":"turkey-mince-raw","alternatives":["beef-mince-10-raw","chickpeas-cooked"]},{"ingredientId":"sweet-potato-raw","alternatives":["potato-raw"]}]}'::jsonb),
  ('turkey-mushroom-stroganoff', 'Turkey & mushroom stroganoff', 'dinner', 2, '{"id":"turkey-mushroom-stroganoff","name":"Turkey & mushroom stroganoff","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":20,"ingredients":[{"ingredientId":"turkey-breast-raw","grams":300,"display":"300 g","prep":"sliced into strips"},{"ingredientId":"mushrooms","grams":200,"display":"3 cups","prep":"sliced"},{"ingredientId":"onion","grams":110,"display":"1 onion","prep":"sliced"},{"ingredientId":"greek-yogurt-0","grams":150,"display":"150 g"},{"ingredientId":"mustard","grams":10,"display":"2 tsp"},{"ingredientId":"rice-white-dry","grams":140,"display":"¾ cup","prep":"dry"},{"ingredientId":"rapeseed-oil","grams":10,"display":"2 tsp"},{"ingredientId":"spices","grams":3,"display":"paprika, salt & pepper"}],"steps":["Cook the rice according to the packet.","Fry the turkey in the oil for 5 minutes until browned, then lift out.","Fry the onion and mushrooms for 6 minutes until soft and golden.","Return the turkey with the paprika, mustard and a splash of water and simmer for 3 minutes.","Take off the heat, stir in the yogurt (do not boil) and serve over the rice."],"substitutions":[{"ingredientId":"turkey-breast-raw","alternatives":["chicken-breast-raw","tofu-firm"]},{"ingredientId":"greek-yogurt-0","alternatives":["skyr-plain","soy-yogurt"]}]}'::jsonb),
  ('turkey-keema-peas-potatoes', 'Turkey keema with peas & potatoes', 'dinner', 4, '{"id":"turkey-keema-peas-potatoes","name":"Turkey keema with peas & potatoes","meal":"dinner","servings":4,"prepMinutes":15,"cookMinutes":30,"ingredients":[{"ingredientId":"turkey-mince-raw","grams":600,"display":"600 g"},{"ingredientId":"potato-raw","grams":600,"display":"4 medium","prep":"cut into 2 cm cubes"},{"ingredientId":"peas-green","grams":200,"display":"1½ cups","prep":"frozen"},{"ingredientId":"tomatoes-canned","grams":400,"display":"1 can"},{"ingredientId":"onion","grams":110,"display":"1 onion","prep":"diced"},{"ingredientId":"ginger","grams":12,"display":"2 tbsp","prep":"grated"},{"ingredientId":"rapeseed-oil","grams":14,"display":"1 tbsp"},{"ingredientId":"spices","grams":4,"display":"garam masala, cumin, turmeric & salt"}],"steps":["Fry the onion and ginger in the oil in a large pot for 5 minutes.","Add the turkey and brown for 5 minutes, breaking it up.","Stir in the spices, potatoes, tomatoes and 200 ml water, cover and simmer for 20 minutes.","Add the peas and simmer 5 minutes more until the potatoes are tender."],"substitutions":[{"ingredientId":"turkey-mince-raw","alternatives":["lamb-mince-raw","lentils-cooked"]}],"notes":"Keeps 3 days in the fridge and freezes well."}'::jsonb),
  ('steak-eggs-spinach-rye', 'Steak & eggs with spinach on rye', 'breakfast', 1, '{"id":"steak-eggs-spinach-rye","name":"Steak & eggs with spinach on rye","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":8,"ingredients":[{"ingredientId":"beef-steak-raw","grams":120,"display":"1 small steak (120 g)"},{"ingredientId":"egg","grams":100,"display":"2 eggs"},{"ingredientId":"spinach","grams":50,"display":"2 handfuls"},{"ingredientId":"rye-bread","grams":32,"display":"1 slice"},{"ingredientId":"rapeseed-oil","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":1,"display":"salt & pepper"}],"steps":["Season the steak and sear in the oil in a hot pan for 2–3 minutes per side, then rest on a board.","Fry the eggs in the same pan and wilt the spinach beside them.","Slice the steak and serve with the eggs and spinach on the rye bread."],"substitutions":[{"ingredientId":"beef-steak-raw","alternatives":["pork-loin-raw","smoked-salmon"]},{"ingredientId":"rye-bread","alternatives":["wholewheat-bread"]}]}'::jsonb),
  ('seared-steak-tomato-bites', 'Seared steak bites with tomatoes', 'snack', 1, '{"id":"seared-steak-tomato-bites","name":"Seared steak bites with tomatoes","meal":"snack","servings":1,"prepMinutes":3,"cookMinutes":5,"ingredients":[{"ingredientId":"beef-steak-raw","grams":80,"display":"80 g","prep":"cut into cubes"},{"ingredientId":"tomato","grams":80,"display":"6 cherry tomatoes","prep":"halved"},{"ingredientId":"rocket","grams":20,"display":"1 handful"},{"ingredientId":"olive-oil","grams":3,"display":"½ tsp"},{"ingredientId":"spices","grams":1,"display":"salt & cracked pepper"}],"steps":["Heat a pan until very hot and add the oil.","Sear the steak cubes for 2–3 minutes, turning, until browned outside and pink inside.","Season and serve on the rocket with the tomatoes."],"substitutions":[{"ingredientId":"beef-steak-raw","alternatives":["chicken-breast-raw","tofu-firm"]}]}'::jsonb),
  ('beef-bean-taco-wraps', 'Beef & kidney bean taco wraps', 'lunch', 2, '{"id":"beef-bean-taco-wraps","name":"Beef & kidney bean taco wraps","meal":"lunch","servings":2,"prepMinutes":10,"cookMinutes":10,"ingredients":[{"ingredientId":"beef-mince-10-raw","grams":250,"display":"250 g"},{"ingredientId":"kidney-beans-cooked","grams":120,"display":"½ can","prep":"drained"},{"ingredientId":"tortilla-wheat","grams":180,"display":"4 tortillas"},{"ingredientId":"lettuce","grams":60,"display":"1 cup","prep":"shredded"},{"ingredientId":"tomato","grams":120,"display":"1 tomato","prep":"diced"},{"ingredientId":"onion","grams":55,"display":"½ onion","prep":"diced"},{"ingredientId":"lime-juice","grams":10,"display":"2 tsp"},{"ingredientId":"spices","grams":3,"display":"cumin, chilli, oregano & salt"}],"steps":["Fry the beef and onion in a dry pan for 6 minutes, breaking up the mince.","Add the beans, spices and a splash of water and cook for 3 minutes, lightly crushing some beans.","Toss the tomato with the lime juice.","Fill the warmed tortillas with beef, lettuce and tomato and roll up."],"substitutions":[{"ingredientId":"beef-mince-10-raw","alternatives":["turkey-mince-raw","black-beans-cooked"]},{"ingredientId":"tortilla-wheat","alternatives":["tortilla-corn"]}]}'::jsonb),
  ('beef-bulgur-tabbouleh-bowl', 'Spiced beef & bulgur tabbouleh bowl', 'lunch', 2, '{"id":"beef-bulgur-tabbouleh-bowl","name":"Spiced beef & bulgur tabbouleh bowl","meal":"lunch","servings":2,"prepMinutes":15,"cookMinutes":12,"ingredients":[{"ingredientId":"beef-mince-10-raw","grams":250,"display":"250 g"},{"ingredientId":"bulgur-dry","grams":120,"display":"¾ cup","prep":"dry"},{"ingredientId":"tomato","grams":200,"display":"2 tomatoes","prep":"diced"},{"ingredientId":"cucumber","grams":150,"display":"½ cucumber","prep":"diced"},{"ingredientId":"spring-onion","grams":30,"display":"2 spring onions","prep":"sliced"},{"ingredientId":"lemon-juice","grams":30,"display":"2 tbsp"},{"ingredientId":"olive-oil","grams":10,"display":"2 tsp"},{"ingredientId":"spices","grams":3,"display":"cumin, cinnamon, dried mint & salt"}],"steps":["Pour 250 ml boiling water over the bulgur, cover and leave for 12 minutes, then fluff with a fork.","Fry the beef with the cumin and cinnamon in a dry pan for 7–8 minutes until browned.","Toss the bulgur with the tomato, cucumber, spring onion, lemon juice, oil and mint.","Spoon the beef over the tabbouleh."],"substitutions":[{"ingredientId":"beef-mince-10-raw","alternatives":["lamb-mince-raw","chickpeas-cooked"]},{"ingredientId":"bulgur-dry","alternatives":["quinoa-dry","couscous-dry"]}],"notes":"Packs well for lunch boxes; keep the beef separate until eating."}'::jsonb),
  ('steak-quinoa-pepper-salad', 'Steak, quinoa & charred pepper salad', 'lunch', 1, '{"id":"steak-quinoa-pepper-salad","name":"Steak, quinoa & charred pepper salad","meal":"lunch","servings":1,"prepMinutes":10,"cookMinutes":8,"ingredients":[{"ingredientId":"beef-steak-raw","grams":150,"display":"150 g"},{"ingredientId":"quinoa-cooked","grams":150,"display":"¾ cup cooked"},{"ingredientId":"bell-pepper","grams":100,"display":"1 small pepper","prep":"sliced"},{"ingredientId":"rocket","grams":30,"display":"1½ cups"},{"ingredientId":"olive-oil","grams":10,"display":"2 tsp"},{"ingredientId":"lemon-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"spices","grams":1,"display":"salt & pepper"}],"steps":["Season the steak and sear in a hot pan with a little of the oil for 3–4 minutes per side. Rest for 5 minutes.","Char the pepper strips in the same pan for 4 minutes.","Toss the quinoa, rocket and peppers with the lemon juice and remaining oil.","Slice the steak and lay it over the salad."],"substitutions":[{"ingredientId":"beef-steak-raw","alternatives":["chicken-breast-raw","salmon-raw"]},{"ingredientId":"quinoa-cooked","alternatives":["rice-white-cooked"]}]}'::jsonb),
  ('beef-pho-noodle-soup', 'Beef pho-style noodle soup', 'lunch', 2, '{"id":"beef-pho-noodle-soup","name":"Beef pho-style noodle soup","meal":"lunch","servings":2,"prepMinutes":10,"cookMinutes":15,"ingredients":[{"ingredientId":"beef-steak-raw","grams":250,"display":"250 g","prep":"very thinly sliced"},{"ingredientId":"rice-noodles-cooked","grams":300,"display":"2 nests, cooked (300 g)"},{"ingredientId":"vegetable-stock","grams":1000,"display":"4 cups"},{"ingredientId":"ginger","grams":18,"display":"3 tbsp","prep":"sliced"},{"ingredientId":"spring-onion","grams":30,"display":"2 spring onions","prep":"sliced"},{"ingredientId":"spinach","grams":60,"display":"2 handfuls"},{"ingredientId":"lime-juice","grams":20,"display":"1½ tbsp"},{"ingredientId":"spices","grams":2,"display":"star anise, cinnamon, chilli & salt"}],"steps":["Simmer the stock with the ginger and spices for 10 minutes.","Divide the noodles and spinach between two deep bowls.","Drop the steak into the simmering broth for 1 minute, then ladle broth and beef over the noodles.","Finish with spring onion and lime juice."],"substitutions":[{"ingredientId":"beef-steak-raw","alternatives":["chicken-breast-raw","tofu-firm"]}]}'::jsonb),
  ('beef-sweet-potato-chilli-batch', 'Beef & sweet potato chilli', 'lunch', 4, '{"id":"beef-sweet-potato-chilli-batch","name":"Beef & sweet potato chilli","meal":"lunch","servings":4,"prepMinutes":15,"cookMinutes":35,"ingredients":[{"ingredientId":"beef-mince-10-raw","grams":500,"display":"500 g"},{"ingredientId":"kidney-beans-cooked","grams":240,"display":"1 can","prep":"drained"},{"ingredientId":"sweet-potato-raw","grams":500,"display":"2 large","prep":"cut into 2 cm cubes"},{"ingredientId":"tomatoes-canned","grams":400,"display":"1 can"},{"ingredientId":"onion","grams":110,"display":"1 onion","prep":"diced"},{"ingredientId":"carrot","grams":120,"display":"2 carrots","prep":"diced"},{"ingredientId":"rapeseed-oil","grams":10,"display":"2 tsp"},{"ingredientId":"spices","grams":4,"display":"chilli, cumin, smoked paprika & salt"}],"steps":["Brown the beef and onion in the oil in a large pot for 6 minutes.","Add the spices, sweet potato, carrot, tomatoes and 250 ml water.","Cover and simmer for 25 minutes until the sweet potato is tender.","Stir in the beans, simmer 5 minutes more and season."],"substitutions":[{"ingredientId":"beef-mince-10-raw","alternatives":["turkey-mince-raw","lentils-cooked"]},{"ingredientId":"sweet-potato-raw","alternatives":["potato-raw"]}],"notes":"Portion into four lunch boxes; keeps 4 days in the fridge."}'::jsonb),
  ('steak-potato-salad-mustard', 'Warm steak & potato salad', 'lunch', 2, '{"id":"steak-potato-salad-mustard","name":"Warm steak & potato salad","meal":"lunch","servings":2,"prepMinutes":10,"cookMinutes":20,"ingredients":[{"ingredientId":"beef-steak-raw","grams":300,"display":"2 small steaks"},{"ingredientId":"potato-raw","grams":400,"display":"6 small new potatoes","prep":"halved"},{"ingredientId":"green-beans","grams":150,"display":"1½ cups","prep":"trimmed"},{"ingredientId":"rocket","grams":40,"display":"2 handfuls"},{"ingredientId":"mustard","grams":15,"display":"1 tbsp"},{"ingredientId":"olive-oil","grams":14,"display":"1 tbsp"},{"ingredientId":"spices","grams":2,"display":"salt & cracked pepper"}],"steps":["Simmer the potatoes in salted water for 15 minutes, adding the green beans for the last 4 minutes. Drain.","Meanwhile sear the seasoned steaks in a hot pan for 3–4 minutes per side and rest.","Whisk the mustard with the oil and 1 tbsp water and toss with the warm potatoes and beans.","Fold through the rocket and top with the sliced steak."],"substitutions":[{"ingredientId":"beef-steak-raw","alternatives":["pork-loin-raw","salmon-raw"]},{"ingredientId":"green-beans","alternatives":["broccoli"]}]}'::jsonb),
  ('beef-egg-bibimbap-bowl', 'Beef & egg bibimbap bowl', 'dinner', 2, '{"id":"beef-egg-bibimbap-bowl","name":"Beef & egg bibimbap bowl","meal":"dinner","servings":2,"prepMinutes":15,"cookMinutes":20,"ingredients":[{"ingredientId":"beef-mince-10-raw","grams":250,"display":"250 g"},{"ingredientId":"egg","grams":200,"display":"4 eggs"},{"ingredientId":"rice-white-dry","grams":140,"display":"¾ cup","prep":"dry"},{"ingredientId":"spinach","grams":100,"display":"3 handfuls"},{"ingredientId":"carrot","grams":100,"display":"2 small","prep":"grated"},{"ingredientId":"soy-sauce","grams":20,"display":"1 tbsp + 1 tsp"},{"ingredientId":"sesame-oil","grams":10,"display":"2 tsp"},{"ingredientId":"spices","grams":2,"display":"chilli flakes & garlic powder"}],"steps":["Cook the rice according to the packet.","Fry the beef in half the sesame oil with the soy sauce, garlic and chilli for 7 minutes until browned.","Push to one side and wilt the spinach in the pan for 1 minute.","Fry the eggs in the remaining oil until the whites are set.","Top bowls of rice with the beef, spinach, grated carrot and two eggs each."],"substitutions":[{"ingredientId":"beef-mince-10-raw","alternatives":["turkey-mince-raw","tofu-firm"]}]}'::jsonb),
  ('beef-mushroom-ragu-batch', 'Beef & mushroom ragù with pasta', 'dinner', 4, '{"id":"beef-mushroom-ragu-batch","name":"Beef & mushroom ragù with pasta","meal":"dinner","servings":4,"prepMinutes":15,"cookMinutes":35,"ingredients":[{"ingredientId":"beef-mince-10-raw","grams":500,"display":"500 g"},{"ingredientId":"pasta-dry","grams":300,"display":"300 g","prep":"dry"},{"ingredientId":"tomatoes-canned","grams":800,"display":"2 cans"},{"ingredientId":"mushrooms","grams":250,"display":"4 cups","prep":"finely chopped"},{"ingredientId":"onion","grams":110,"display":"1 onion","prep":"diced"},{"ingredientId":"zucchini","grams":200,"display":"1 courgette","prep":"finely diced"},{"ingredientId":"garlic","grams":9,"display":"3 cloves","prep":"crushed"},{"ingredientId":"spices","grams":3,"display":"dried oregano, bay leaf, salt & pepper"}],"steps":["Brown the beef in a large dry pot for 5 minutes.","Add the onion, courgette, mushrooms and garlic and cook for 5 minutes.","Add the tomatoes and herbs and simmer, half covered, for 25 minutes until thick.","Cook the pasta and toss with the sauce."],"substitutions":[{"ingredientId":"beef-mince-10-raw","alternatives":["turkey-mince-raw","lentils-cooked"]},{"ingredientId":"pasta-dry","alternatives":["rice-white-dry"]}],"notes":"The sauce freezes well for up to 3 months."}'::jsonb),
  ('beef-lentil-cottage-pie', 'Beef & lentil cottage pie', 'dinner', 4, '{"id":"beef-lentil-cottage-pie","name":"Beef & lentil cottage pie","meal":"dinner","servings":4,"prepMinutes":20,"cookMinutes":40,"ingredients":[{"ingredientId":"beef-mince-10-raw","grams":400,"display":"400 g"},{"ingredientId":"lentils-dry","grams":100,"display":"½ cup","prep":"rinsed"},{"ingredientId":"potato-raw","grams":900,"display":"6 medium","prep":"peeled and chunked"},{"ingredientId":"onion","grams":110,"display":"1 onion","prep":"diced"},{"ingredientId":"carrot","grams":150,"display":"2 large","prep":"diced"},{"ingredientId":"tomatoes-canned","grams":400,"display":"1 can"},{"ingredientId":"vegetable-stock","grams":300,"display":"1¼ cups"},{"ingredientId":"spices","grams":3,"display":"dried thyme, salt & pepper"}],"steps":["Simmer the potatoes for 15 minutes until soft, then drain and mash with a splash of the cooking water.","Meanwhile brown the beef with the onion and carrot for 6 minutes.","Add the lentils, tomatoes, stock and thyme and simmer for 15 minutes until thick.","Heat the oven to 200°C. Spoon the filling into a dish, top with the mash and bake for 20 minutes until golden."],"substitutions":[{"ingredientId":"beef-mince-10-raw","alternatives":["lamb-mince-raw","lentils-cooked"]},{"ingredientId":"potato-raw","alternatives":["sweet-potato-raw"]}],"notes":"Keeps 3 days in the fridge; reheat portions in the microwave."}'::jsonb),
  ('pepper-steak-sweet-potato-mash', 'Pepper steak with sweet potato mash', 'dinner', 2, '{"id":"pepper-steak-sweet-potato-mash","name":"Pepper steak with sweet potato mash","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":25,"ingredients":[{"ingredientId":"beef-steak-raw","grams":300,"display":"2 steaks"},{"ingredientId":"sweet-potato-raw","grams":450,"display":"2 large","prep":"peeled and chunked"},{"ingredientId":"broccoli","grams":200,"display":"2 cups","prep":"florets"},{"ingredientId":"olive-oil","grams":10,"display":"2 tsp"},{"ingredientId":"spices","grams":3,"display":"cracked black pepper & salt"}],"steps":["Simmer the sweet potato for 15 minutes, adding the broccoli for the last 4 minutes.","Press the cracked pepper onto both sides of the steaks.","Sear the steaks in a hot pan with the oil for 3–4 minutes per side, then rest for 5 minutes.","Drain and mash the sweet potato with salt and serve with the sliced steak and broccoli."],"substitutions":[{"ingredientId":"beef-steak-raw","alternatives":["pork-loin-raw","salmon-raw"]},{"ingredientId":"sweet-potato-raw","alternatives":["potato-raw"]}]}'::jsonb),
  ('beef-ricotta-pasta-bake', 'Beef & ricotta pasta bake', 'dinner', 4, '{"id":"beef-ricotta-pasta-bake","name":"Beef & ricotta pasta bake","meal":"dinner","servings":4,"prepMinutes":15,"cookMinutes":30,"ingredients":[{"ingredientId":"beef-mince-10-raw","grams":400,"display":"400 g"},{"ingredientId":"ricotta","grams":250,"display":"1 tub (250 g)"},{"ingredientId":"mozzarella-light","grams":100,"display":"¾ ball","prep":"torn"},{"ingredientId":"pasta-dry","grams":300,"display":"300 g penne","prep":"dry"},{"ingredientId":"passata","grams":500,"display":"2 cups"},{"ingredientId":"spinach","grams":100,"display":"3 handfuls"},{"ingredientId":"onion","grams":110,"display":"1 onion","prep":"diced"},{"ingredientId":"spices","grams":3,"display":"dried basil, oregano, garlic powder & salt"}],"steps":["Heat the oven to 200°C and cook the pasta for 2 minutes less than the packet says.","Brown the beef and onion in a pan for 6 minutes, then add the passata and herbs and stir in the spinach.","Mix the drained pasta into the sauce and tip into a baking dish.","Dot with spoonfuls of ricotta, scatter the mozzarella over and bake for 20 minutes until bubbling."],"substitutions":[{"ingredientId":"beef-mince-10-raw","alternatives":["turkey-mince-raw","lentils-cooked"]},{"ingredientId":"ricotta","alternatives":["cottage-cheese"]}],"notes":"Keeps 3 days in the fridge; portions freeze well."}'::jsonb),
  ('beef-broccoli-egg-noodles', 'Honey ginger beef with egg noodles', 'dinner', 2, '{"id":"beef-broccoli-egg-noodles","name":"Honey ginger beef with egg noodles","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":10,"ingredients":[{"ingredientId":"beef-steak-raw","grams":300,"display":"300 g","prep":"thinly sliced"},{"ingredientId":"egg-noodles-dry","grams":120,"display":"2 nests","prep":"dry"},{"ingredientId":"bell-pepper","grams":120,"display":"1 pepper","prep":"sliced"},{"ingredientId":"broccoli","grams":150,"display":"1½ cups","prep":"small florets"},{"ingredientId":"soy-sauce","grams":30,"display":"2 tbsp"},{"ingredientId":"ginger","grams":10,"display":"1½ tbsp","prep":"grated"},{"ingredientId":"honey","grams":7,"display":"1 tsp"},{"ingredientId":"rapeseed-oil","grams":10,"display":"2 tsp"}],"steps":["Cook the noodles according to the packet and drain.","Stir-fry the beef in half the oil in a very hot wok for 2 minutes, then lift out.","Stir-fry the broccoli and pepper in the remaining oil with a splash of water for 4 minutes.","Return the beef with the noodles, soy sauce, ginger and honey and toss for 1 minute."],"substitutions":[{"ingredientId":"beef-steak-raw","alternatives":["chicken-breast-raw","tofu-firm"]},{"ingredientId":"egg-noodles-dry","alternatives":["rice-noodles-cooked"]}]}'::jsonb),
  ('ham-egg-spinach-wrap', 'Ham, egg & spinach breakfast wrap', 'breakfast', 1, '{"id":"ham-egg-spinach-wrap","name":"Ham, egg & spinach breakfast wrap","meal":"breakfast","servings":1,"prepMinutes":4,"cookMinutes":6,"ingredients":[{"ingredientId":"ham-sliced","grams":90,"display":"6 slices"},{"ingredientId":"egg","grams":100,"display":"2 eggs","prep":"beaten"},{"ingredientId":"tortilla-wheat","grams":45,"display":"1 tortilla"},{"ingredientId":"spinach","grams":30,"display":"1 large handful"},{"ingredientId":"rapeseed-oil","grams":3,"display":"½ tsp"},{"ingredientId":"spices","grams":1,"display":"salt & pepper"}],"steps":["Wilt the spinach in the oil in a non-stick pan for 30 seconds.","Pour in the eggs and stir gently over medium heat until just set. Season.","Lay the ham on the tortilla, spoon the eggs on top, roll up and toast seam side down in the pan for 1 minute."],"substitutions":[{"ingredientId":"ham-sliced","alternatives":["chicken-breast-cooked","smoked-salmon"]},{"ingredientId":"tortilla-wheat","alternatives":["tortilla-corn"]}]}'::jsonb),
  ('ham-cottage-cheese-rye', 'Ham & cottage cheese on rye', 'breakfast', 1, '{"id":"ham-cottage-cheese-rye","name":"Ham & cottage cheese on rye","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"ham-sliced","grams":100,"display":"7 slices"},{"ingredientId":"cottage-cheese","grams":100,"display":"100 g"},{"ingredientId":"rye-bread","grams":64,"display":"2 slices"},{"ingredientId":"tomato","grams":80,"display":"⅔ tomato","prep":"sliced"},{"ingredientId":"spices","grams":1,"display":"chives or black pepper"}],"steps":["Spread the cottage cheese thickly over the rye bread.","Fold the ham slices on top.","Finish with tomato slices and a grind of pepper."],"substitutions":[{"ingredientId":"ham-sliced","alternatives":["smoked-salmon","chicken-breast-cooked"]},{"ingredientId":"cottage-cheese","alternatives":["skyr-plain","hummus"]}]}'::jsonb),
  ('ham-potato-hash-egg', 'Ham & potato hash with a fried egg', 'breakfast', 1, '{"id":"ham-potato-hash-egg","name":"Ham & potato hash with a fried egg","meal":"breakfast","servings":1,"prepMinutes":10,"cookMinutes":15,"ingredients":[{"ingredientId":"ham-sliced","grams":120,"display":"8 slices","prep":"cut into strips"},{"ingredientId":"egg","grams":50,"display":"1 egg"},{"ingredientId":"potato-raw","grams":200,"display":"1 medium","prep":"cut into 1 cm cubes"},{"ingredientId":"onion","grams":40,"display":"¼ onion","prep":"diced"},{"ingredientId":"bell-pepper","grams":60,"display":"½ pepper","prep":"diced"},{"ingredientId":"rapeseed-oil","grams":7,"display":"½ tbsp"},{"ingredientId":"spices","grams":1,"display":"paprika, salt & pepper"}],"steps":["Microwave the potato cubes in a covered bowl for 4 minutes.","Fry the potato, onion and pepper in the oil for 8 minutes until golden.","Add the ham and paprika and fry 2 minutes more.","Push to one side, fry the egg in the pan and serve on top."],"substitutions":[{"ingredientId":"ham-sliced","alternatives":["chicken-breast-cooked","tofu-firm"]},{"ingredientId":"potato-raw","alternatives":["sweet-potato-raw"]}]}'::jsonb),
  ('ham-hummus-cucumber-rolls', 'Ham & hummus cucumber rolls', 'snack', 1, '{"id":"ham-hummus-cucumber-rolls","name":"Ham & hummus cucumber rolls","meal":"snack","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"ham-sliced","grams":90,"display":"6 slices"},{"ingredientId":"hummus","grams":30,"display":"2 tbsp"},{"ingredientId":"cucumber","grams":60,"display":"¼ cucumber","prep":"cut into sticks"},{"ingredientId":"carrot","grams":40,"display":"1 small","prep":"cut into sticks"}],"steps":["Spread each ham slice with a little hummus.","Lay a cucumber and carrot stick across each slice.","Roll up tightly and eat straight away or box for later."],"substitutions":[{"ingredientId":"ham-sliced","alternatives":["chicken-breast-cooked","smoked-salmon"]},{"ingredientId":"hummus","alternatives":["cottage-cheese"]}]}'::jsonb),
  ('ham-white-bean-salad', 'Ham & white bean salad', 'lunch', 1, '{"id":"ham-white-bean-salad","name":"Ham & white bean salad","meal":"lunch","servings":1,"prepMinutes":8,"cookMinutes":0,"ingredients":[{"ingredientId":"ham-sliced","grams":100,"display":"7 slices","prep":"torn"},{"ingredientId":"white-beans-cooked","grams":120,"display":"½ can","prep":"drained and rinsed"},{"ingredientId":"rocket","grams":30,"display":"1½ cups"},{"ingredientId":"tomato","grams":100,"display":"1 small tomato","prep":"diced"},{"ingredientId":"olive-oil","grams":10,"display":"2 tsp"},{"ingredientId":"lemon-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"mustard","grams":5,"display":"1 tsp"}],"steps":["Whisk the oil, lemon juice and mustard in a bowl.","Add the beans and tomato and toss to coat.","Fold in the rocket and ham just before eating."],"substitutions":[{"ingredientId":"ham-sliced","alternatives":["tuna-canned","chicken-breast-cooked"]},{"ingredientId":"white-beans-cooked","alternatives":["chickpeas-cooked"]}]}'::jsonb),
  ('five-spice-pork-pitta', 'Five-spice pork pitta with quick pickles', 'lunch', 1, '{"id":"five-spice-pork-pitta","name":"Five-spice pork pitta with quick pickles","meal":"lunch","servings":1,"prepMinutes":10,"cookMinutes":8,"ingredients":[{"ingredientId":"pork-tenderloin-raw","grams":150,"display":"150 g","prep":"thinly sliced"},{"ingredientId":"pita-wholewheat","grams":64,"display":"1 pitta"},{"ingredientId":"carrot","grams":60,"display":"1 carrot","prep":"cut into matchsticks"},{"ingredientId":"cucumber","grams":60,"display":"¼ cucumber","prep":"thinly sliced"},{"ingredientId":"lime-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"honey","grams":7,"display":"1 tsp"},{"ingredientId":"rapeseed-oil","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":2,"display":"five-spice, chilli & salt"}],"steps":["Toss the carrot and cucumber with the lime juice and a pinch of salt and set aside to pickle.","Toss the pork with the five-spice and fry in the oil for 5–6 minutes until cooked through.","Drizzle the honey over the pork in the pan for the last 30 seconds.","Warm the pitta and stuff with the pork and drained pickles."],"substitutions":[{"ingredientId":"pork-tenderloin-raw","alternatives":["chicken-breast-raw","tofu-firm"]},{"ingredientId":"pita-wholewheat","alternatives":["tortilla-wheat"]}]}'::jsonb),
  ('ham-pea-pasta-parmesan', 'Ham & pea pasta with parmesan', 'lunch', 1, '{"id":"ham-pea-pasta-parmesan","name":"Ham & pea pasta with parmesan","meal":"lunch","servings":1,"prepMinutes":5,"cookMinutes":12,"ingredients":[{"ingredientId":"ham-sliced","grams":90,"display":"6 slices","prep":"cut into strips"},{"ingredientId":"pasta-dry","grams":80,"display":"80 g","prep":"dry"},{"ingredientId":"peas-green","grams":80,"display":"⅔ cup","prep":"frozen"},{"ingredientId":"parmesan","grams":15,"display":"3 tbsp grated"},{"ingredientId":"spinach","grams":30,"display":"1 large handful"},{"ingredientId":"olive-oil","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":1,"display":"black pepper"}],"steps":["Cook the pasta, adding the peas for the last 3 minutes. Save a splash of water and drain.","Warm the oil in the empty pan, add the ham and spinach and stir for 1 minute.","Toss in the pasta, peas, parmesan and a splash of cooking water until glossy. Season with pepper."],"substitutions":[{"ingredientId":"ham-sliced","alternatives":["chicken-breast-cooked","smoked-salmon"]},{"ingredientId":"parmesan","alternatives":["feta"]}]}'::jsonb),
  ('honey-mustard-pork-rye-slaw', 'Honey mustard pork on rye with apple slaw', 'lunch', 1, '{"id":"honey-mustard-pork-rye-slaw","name":"Honey mustard pork on rye with apple slaw","meal":"lunch","servings":1,"prepMinutes":10,"cookMinutes":8,"ingredients":[{"ingredientId":"pork-tenderloin-raw","grams":150,"display":"150 g","prep":"sliced into medallions"},{"ingredientId":"rye-bread","grams":64,"display":"2 slices"},{"ingredientId":"cabbage","grams":60,"display":"⅔ cup","prep":"finely shredded"},{"ingredientId":"apple","grams":80,"display":"½ apple","prep":"cut into matchsticks"},{"ingredientId":"mustard","grams":10,"display":"2 tsp"},{"ingredientId":"honey","grams":7,"display":"1 tsp"},{"ingredientId":"lemon-juice","grams":10,"display":"2 tsp"},{"ingredientId":"rapeseed-oil","grams":5,"display":"1 tsp"}],"steps":["Toss the cabbage and apple with the lemon juice and half the mustard.","Fry the pork in the oil for 3 minutes per side until cooked through.","Brush the pork with the honey and remaining mustard in the pan for the last 30 seconds.","Pile the slaw and pork onto the rye bread."],"substitutions":[{"ingredientId":"pork-tenderloin-raw","alternatives":["chicken-breast-raw","smoked-salmon"]},{"ingredientId":"rye-bread","alternatives":["wholewheat-bread"]}]}'::jsonb),
  ('pork-souvlaki-couscous', 'Pork souvlaki couscous bowl', 'lunch', 1, '{"id":"pork-souvlaki-couscous","name":"Pork souvlaki couscous bowl","meal":"lunch","servings":1,"prepMinutes":10,"cookMinutes":10,"ingredients":[{"ingredientId":"pork-loin-raw","grams":150,"display":"1 chop","prep":"cubed"},{"ingredientId":"couscous-dry","grams":60,"display":"⅓ cup","prep":"dry"},{"ingredientId":"cucumber","grams":80,"display":"¼ cucumber","prep":"diced"},{"ingredientId":"tomato","grams":80,"display":"⅔ tomato","prep":"diced"},{"ingredientId":"greek-yogurt-0","grams":60,"display":"3 tbsp"},{"ingredientId":"lemon-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"olive-oil","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":2,"display":"dried oregano, garlic powder & salt"}],"steps":["Pour 90 ml boiling water over the couscous, cover for 5 minutes, then fluff.","Toss the pork with the oil, oregano, garlic and half the lemon juice and fry for 7–8 minutes until cooked through.","Stir the cucumber, tomato and remaining lemon into the couscous.","Top with the pork and a spoonful of yogurt."],"substitutions":[{"ingredientId":"pork-loin-raw","alternatives":["chicken-breast-raw","chickpeas-cooked"]},{"ingredientId":"greek-yogurt-0","alternatives":["soy-yogurt"]}]}'::jsonb),
  ('roast-pork-apples-potatoes', 'Roast pork tenderloin with apples', 'dinner', 2, '{"id":"roast-pork-apples-potatoes","name":"Roast pork tenderloin with apples","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":35,"ingredients":[{"ingredientId":"pork-tenderloin-raw","grams":350,"display":"1 tenderloin (350 g)"},{"ingredientId":"potato-raw","grams":450,"display":"3 medium","prep":"cut into chunks"},{"ingredientId":"apple","grams":180,"display":"1 apple","prep":"cut into wedges"},{"ingredientId":"onion","grams":110,"display":"1 red onion","prep":"cut into wedges"},{"ingredientId":"mustard","grams":10,"display":"2 tsp"},{"ingredientId":"olive-oil","grams":14,"display":"1 tbsp"},{"ingredientId":"spices","grams":3,"display":"dried thyme, salt & pepper"}],"steps":["Heat the oven to 200°C. Toss the potatoes and onion with most of the oil and roast for 15 minutes.","Rub the pork with the mustard, thyme, salt and remaining oil.","Add the pork and apple to the tray and roast for 20 minutes until the pork is just cooked (63°C inside).","Rest the pork for 5 minutes, slice and serve with the potatoes and apples."],"substitutions":[{"ingredientId":"pork-tenderloin-raw","alternatives":["chicken-breast-raw","turkey-breast-raw"]}]}'::jsonb),
  ('mustard-pork-chops-sweet-potato', 'Mustard pork chops with sweet potato mash', 'dinner', 2, '{"id":"mustard-pork-chops-sweet-potato","name":"Mustard pork chops with sweet potato mash","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":20,"ingredients":[{"ingredientId":"pork-loin-raw","grams":300,"display":"2 chops"},{"ingredientId":"sweet-potato-raw","grams":400,"display":"2 medium","prep":"peeled and chunked"},{"ingredientId":"green-beans","grams":150,"display":"1½ cups","prep":"trimmed"},{"ingredientId":"mustard","grams":20,"display":"1 heaped tbsp"},{"ingredientId":"vegetable-stock","grams":100,"display":"⅖ cup"},{"ingredientId":"rapeseed-oil","grams":10,"display":"2 tsp"},{"ingredientId":"spices","grams":2,"display":"salt & pepper"}],"steps":["Simmer the sweet potato for 15 minutes, adding the green beans for the last 4 minutes. Drain and mash the potato.","Season the chops and fry in the oil for 4 minutes per side until cooked through. Rest on a plate.","Add the stock and mustard to the pan and bubble for 1 minute to make a sauce.","Serve the chops on the mash with the beans and spoon over the sauce."],"substitutions":[{"ingredientId":"pork-loin-raw","alternatives":["chicken-breast-raw","turkey-breast-raw"]},{"ingredientId":"sweet-potato-raw","alternatives":["potato-raw"]}]}'::jsonb),
  ('orange-ginger-pork-rice', 'Orange & ginger pork with rice', 'dinner', 2, '{"id":"orange-ginger-pork-rice","name":"Orange & ginger pork with rice","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":15,"ingredients":[{"ingredientId":"pork-tenderloin-raw","grams":300,"display":"300 g","prep":"thinly sliced"},{"ingredientId":"rice-white-dry","grams":140,"display":"¾ cup","prep":"dry"},{"ingredientId":"orange","grams":130,"display":"1 orange","prep":"juiced, half segmented"},{"ingredientId":"bell-pepper","grams":120,"display":"1 pepper","prep":"sliced"},{"ingredientId":"ginger","grams":10,"display":"1½ tbsp","prep":"grated"},{"ingredientId":"soy-sauce","grams":20,"display":"1 tbsp + 1 tsp"},{"ingredientId":"honey","grams":7,"display":"1 tsp"},{"ingredientId":"rapeseed-oil","grams":10,"display":"2 tsp"}],"steps":["Cook the rice according to the packet.","Stir-fry the pork in the oil in a hot wok for 4 minutes, then add the pepper for 3 minutes.","Add the orange juice, ginger, soy sauce and honey and bubble for 2 minutes until glossy.","Stir in the orange segments and serve over the rice."],"substitutions":[{"ingredientId":"pork-tenderloin-raw","alternatives":["chicken-breast-raw","tofu-firm"]}]}'::jsonb),
  ('pork-white-bean-cassoulet', 'Pork & white bean cassoulet', 'dinner', 4, '{"id":"pork-white-bean-cassoulet","name":"Pork & white bean cassoulet","meal":"dinner","servings":4,"prepMinutes":15,"cookMinutes":35,"ingredients":[{"ingredientId":"pork-loin-raw","grams":600,"display":"4 chops","prep":"cut into chunks"},{"ingredientId":"white-beans-cooked","grams":480,"display":"2 cans","prep":"drained"},{"ingredientId":"tomatoes-canned","grams":400,"display":"1 can"},{"ingredientId":"carrot","grams":150,"display":"2 large","prep":"sliced"},{"ingredientId":"onion","grams":110,"display":"1 onion","prep":"diced"},{"ingredientId":"garlic","grams":9,"display":"3 cloves","prep":"sliced"},{"ingredientId":"vegetable-stock","grams":300,"display":"1¼ cups"},{"ingredientId":"spices","grams":3,"display":"thyme, smoked paprika, salt & pepper"}],"steps":["Brown the pork in a large non-stick pot for 5 minutes.","Add the onion, carrot and garlic and cook for 3 minutes.","Add the tomatoes, stock, beans and herbs and simmer, half covered, for 25 minutes until thick.","Season and serve in bowls."],"substitutions":[{"ingredientId":"pork-loin-raw","alternatives":["chicken-thigh-raw","tofu-firm"]},{"ingredientId":"white-beans-cooked","alternatives":["kidney-beans-cooked"]}],"notes":"Tastes even better the next day; keeps 3 days in the fridge."}'::jsonb),
