  ('pork-paprika-goulash-rice', 'Pork & pepper goulash with rice', 'dinner', 4, '{"id":"pork-paprika-goulash-rice","name":"Pork & pepper goulash with rice","meal":"dinner","servings":4,"prepMinutes":15,"cookMinutes":35,"ingredients":[{"ingredientId":"pork-loin-raw","grams":600,"display":"4 chops","prep":"cut into chunks"},{"ingredientId":"rice-white-dry","grams":280,"display":"1½ cups","prep":"dry"},{"ingredientId":"onion","grams":220,"display":"2 onions","prep":"sliced"},{"ingredientId":"bell-pepper","grams":240,"display":"2 peppers","prep":"sliced"},{"ingredientId":"tomatoes-canned","grams":400,"display":"1 can"},{"ingredientId":"rapeseed-oil","grams":14,"display":"1 tbsp"},{"ingredientId":"spices","grams":4,"display":"sweet paprika, caraway, salt & pepper"},{"ingredientId":"greek-yogurt-0","grams":100,"display":"4 tbsp","prep":"to serve","optional":true}],"steps":["Brown the pork in the oil in a large pot for 5 minutes, then add the onions and cook for 5 minutes more.","Stir in the paprika and caraway, then the peppers, tomatoes and 200 ml water.","Cover and simmer for 25 minutes until the pork is tender.","Meanwhile cook the rice. Serve the goulash over it with a spoonful of yogurt if you like."],"substitutions":[{"ingredientId":"pork-loin-raw","alternatives":["beef-steak-raw","chicken-thigh-raw"]},{"ingredientId":"rice-white-dry","alternatives":["potato-raw"]}],"notes":"Freeze the goulash in portions without the rice."}'::jsonb),
  ('lamb-kofta-pitta-yogurt', 'Lamb kofta pitta with yogurt', 'lunch', 1, '{"id":"lamb-kofta-pitta-yogurt","name":"Lamb kofta pitta with yogurt","meal":"lunch","servings":1,"prepMinutes":10,"cookMinutes":10,"ingredients":[{"ingredientId":"lamb-mince-raw","grams":130,"display":"130 g"},{"ingredientId":"pita-wholewheat","grams":64,"display":"1 pitta"},{"ingredientId":"greek-yogurt-0","grams":80,"display":"4 tbsp"},{"ingredientId":"lettuce","grams":40,"display":"1 cup","prep":"shredded"},{"ingredientId":"tomato","grams":60,"display":"½ tomato","prep":"sliced"},{"ingredientId":"onion","grams":20,"display":"2 tbsp","prep":"grated"},{"ingredientId":"spices","grams":2,"display":"cumin, coriander, dried mint & salt"}],"steps":["Mix the lamb with the onion and spices and shape into 3 small sausages.","Fry in a dry non-stick pan for 8–10 minutes, turning, until cooked through.","Warm the pitta and fill with lettuce, tomato and the kofta, and spoon in the yogurt."],"substitutions":[{"ingredientId":"lamb-mince-raw","alternatives":["beef-mince-10-raw","chickpeas-cooked"]},{"ingredientId":"greek-yogurt-0","alternatives":["soy-yogurt","skyr-plain"]}]}'::jsonb),
  ('lamb-lentil-leek-soup', 'Lamb, lentil & leek soup', 'lunch', 4, '{"id":"lamb-lentil-leek-soup","name":"Lamb, lentil & leek soup","meal":"lunch","servings":4,"prepMinutes":15,"cookMinutes":35,"ingredients":[{"ingredientId":"lamb-leg-raw","grams":400,"display":"400 g","prep":"diced small"},{"ingredientId":"lentils-dry","grams":120,"display":"⅔ cup","prep":"rinsed"},{"ingredientId":"leek","grams":180,"display":"2 leeks","prep":"sliced"},{"ingredientId":"carrot","grams":150,"display":"2 large","prep":"diced"},{"ingredientId":"potato-raw","grams":300,"display":"2 medium","prep":"diced"},{"ingredientId":"vegetable-stock","grams":1200,"display":"5 cups"},{"ingredientId":"rapeseed-oil","grams":10,"display":"2 tsp"},{"ingredientId":"spices","grams":3,"display":"rosemary, thyme, salt & pepper"}],"steps":["Brown the lamb in the oil in a large pot for 5 minutes.","Add the leek and carrot and cook for 3 minutes.","Add the lentils, potato, stock and herbs and simmer for 30 minutes until everything is tender.","Season and serve, or portion into boxes."],"substitutions":[{"ingredientId":"lamb-leg-raw","alternatives":["beef-steak-raw","chickpeas-cooked"]},{"ingredientId":"leek","alternatives":["onion"]}],"notes":"A classic Icelandic-style lamb soup made heartier with lentils; freezes well."}'::jsonb),
  ('lamb-chickpea-rocket-salad', 'Seared lamb & chickpea salad', 'lunch', 1, '{"id":"lamb-chickpea-rocket-salad","name":"Seared lamb & chickpea salad","meal":"lunch","servings":1,"prepMinutes":10,"cookMinutes":8,"ingredients":[{"ingredientId":"lamb-leg-raw","grams":150,"display":"1 leg steak (150 g)"},{"ingredientId":"chickpeas-cooked","grams":120,"display":"½ can","prep":"drained"},{"ingredientId":"rocket","grams":30,"display":"1½ cups"},{"ingredientId":"tomato","grams":100,"display":"1 small tomato","prep":"diced"},{"ingredientId":"cucumber","grams":80,"display":"¼ cucumber","prep":"diced"},{"ingredientId":"lemon-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"olive-oil","grams":10,"display":"2 tsp"},{"ingredientId":"spices","grams":2,"display":"cumin, sumac or paprika & salt"}],"steps":["Rub the lamb with the cumin and salt and sear in a hot pan with a little oil for 3–4 minutes per side. Rest.","Warm the chickpeas in the pan juices for 2 minutes.","Toss the rocket, tomato, cucumber and chickpeas with the lemon juice and remaining oil.","Slice the lamb over the top and sprinkle with sumac."],"substitutions":[{"ingredientId":"lamb-leg-raw","alternatives":["beef-steak-raw","chicken-breast-raw"]},{"ingredientId":"chickpeas-cooked","alternatives":["white-beans-cooked"]}]}'::jsonb),
  ('spiced-lamb-rice-bowl', 'Spiced lamb rice bowl with yogurt', 'lunch', 1, '{"id":"spiced-lamb-rice-bowl","name":"Spiced lamb rice bowl with yogurt","meal":"lunch","servings":1,"prepMinutes":10,"cookMinutes":10,"ingredients":[{"ingredientId":"lamb-leg-raw","grams":150,"display":"150 g","prep":"thinly sliced"},{"ingredientId":"rice-white-cooked","grams":180,"display":"1 cup cooked"},{"ingredientId":"greek-yogurt-0","grams":60,"display":"3 tbsp"},{"ingredientId":"cucumber","grams":80,"display":"¼ cucumber","prep":"diced"},{"ingredientId":"spinach","grams":40,"display":"1 large handful"},{"ingredientId":"lemon-juice","grams":10,"display":"2 tsp"},{"ingredientId":"olive-oil","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":2,"display":"ras el hanout or cumin, garlic powder & salt"}],"steps":["Toss the lamb with the spices and fry in the oil for 4–5 minutes until browned.","Add the rice and spinach to the pan and stir for 2 minutes until hot and wilted.","Stir the lemon juice into the yogurt.","Spoon into a bowl and top with the cucumber and lemon yogurt."],"substitutions":[{"ingredientId":"lamb-leg-raw","alternatives":["beef-steak-raw","chickpeas-cooked"]},{"ingredientId":"greek-yogurt-0","alternatives":["soy-yogurt"]}]}'::jsonb),
  ('lamb-aubergine-moussaka', 'Lamb & aubergine moussaka', 'dinner', 4, '{"id":"lamb-aubergine-moussaka","name":"Lamb & aubergine moussaka","meal":"dinner","servings":4,"prepMinutes":20,"cookMinutes":45,"ingredients":[{"ingredientId":"lamb-mince-raw","grams":500,"display":"500 g"},{"ingredientId":"aubergine","grams":450,"display":"1 large","prep":"sliced 1 cm thick"},{"ingredientId":"potato-raw","grams":500,"display":"3 medium","prep":"thinly sliced"},{"ingredientId":"passata","grams":300,"display":"1¼ cups"},{"ingredientId":"onion","grams":110,"display":"1 onion","prep":"diced"},{"ingredientId":"ricotta","grams":200,"display":"200 g"},{"ingredientId":"olive-oil","grams":14,"display":"1 tbsp"},{"ingredientId":"spices","grams":3,"display":"cinnamon, oregano, salt & pepper"}],"steps":["Heat the oven to 200°C. Brush the aubergine and potato slices with the oil and roast on trays for 15 minutes.","Meanwhile brown the lamb and onion in a dry pan for 8 minutes, pour off excess fat, add the passata and spices and simmer for 5 minutes.","Layer potato, lamb sauce and aubergine in a baking dish and finish with spoonfuls of ricotta.","Bake for 25 minutes until golden on top."],"substitutions":[{"ingredientId":"lamb-mince-raw","alternatives":["beef-mince-10-raw","lentils-cooked"]},{"ingredientId":"ricotta","alternatives":["cottage-cheese","greek-yogurt-0"]}],"notes":"Keeps 3 days in the fridge; reheat portions covered."}'::jsonb),
  ('lamb-chickpea-tagine-couscous', 'Lamb & chickpea tagine with couscous', 'dinner', 4, '{"id":"lamb-chickpea-tagine-couscous","name":"Lamb & chickpea tagine with couscous","meal":"dinner","servings":4,"prepMinutes":15,"cookMinutes":40,"ingredients":[{"ingredientId":"lamb-leg-raw","grams":500,"display":"500 g","prep":"diced"},{"ingredientId":"chickpeas-cooked","grams":240,"display":"1 can","prep":"drained"},{"ingredientId":"couscous-dry","grams":240,"display":"1⅓ cups","prep":"dry"},{"ingredientId":"tomatoes-canned","grams":400,"display":"1 can"},{"ingredientId":"onion","grams":110,"display":"1 onion","prep":"diced"},{"ingredientId":"carrot","grams":200,"display":"3 carrots","prep":"thickly sliced"},{"ingredientId":"raisins","grams":40,"display":"4 tbsp"},{"ingredientId":"spices","grams":4,"display":"cumin, cinnamon, ground ginger & salt"}],"steps":["Brown the lamb and onion in a heavy non-stick pot for 6 minutes.","Stir in the spices, then add the carrot, tomatoes and 300 ml water.","Cover and simmer for 30 minutes, adding the chickpeas and raisins for the last 10 minutes.","Pour 360 ml boiling water over the couscous, cover for 5 minutes, fluff and serve with the tagine."],"substitutions":[{"ingredientId":"lamb-leg-raw","alternatives":["chicken-thigh-raw","beef-steak-raw"]},{"ingredientId":"couscous-dry","alternatives":["quinoa-dry","rice-white-dry"]}],"notes":"Freeze the tagine in portions; make couscous fresh."}'::jsonb),
  ('rosemary-lamb-sweet-potato-kale', 'Rosemary lamb with roast sweet potato & kale', 'dinner', 2, '{"id":"rosemary-lamb-sweet-potato-kale","name":"Rosemary lamb with roast sweet potato & kale","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":30,"ingredients":[{"ingredientId":"lamb-leg-raw","grams":300,"display":"2 leg steaks"},{"ingredientId":"sweet-potato-raw","grams":400,"display":"2 medium","prep":"cut into chunks"},{"ingredientId":"kale","grams":80,"display":"4 cups","prep":"stems removed, torn"},{"ingredientId":"onion","grams":110,"display":"1 red onion","prep":"cut into wedges"},{"ingredientId":"olive-oil","grams":14,"display":"1 tbsp"},{"ingredientId":"spices","grams":3,"display":"rosemary, garlic powder, salt & pepper"}],"steps":["Heat the oven to 210°C. Toss the sweet potato and onion with most of the oil and roast for 20 minutes.","Rub the lamb with rosemary, garlic, salt and pepper.","Add the lamb and the kale (tossed in the last of the oil) to the tray and roast for 10 minutes for pink lamb.","Rest the lamb for 5 minutes, slice and serve."],"substitutions":[{"ingredientId":"lamb-leg-raw","alternatives":["beef-steak-raw","chicken-breast-raw"]},{"ingredientId":"kale","alternatives":["spinach","broccoli"]}]}'::jsonb),
  ('chicken-tzatziki-pitta-pockets', 'Chicken & tzatziki mini pitta', 'snack', 1, '{"id":"chicken-tzatziki-pitta-pockets","name":"Chicken & tzatziki mini pitta","meal":"snack","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"chicken-breast-cooked","grams":70,"display":"70 g","prep":"sliced"},{"ingredientId":"pita-wholewheat","grams":32,"display":"½ pitta"},{"ingredientId":"greek-yogurt-0","grams":40,"display":"2½ tbsp"},{"ingredientId":"cucumber","grams":40,"display":"4 cm piece","prep":"grated"},{"ingredientId":"spices","grams":1,"display":"dill, garlic powder, salt & pepper"}],"steps":["Squeeze the grated cucumber dry and stir it into the yogurt with dill, garlic, salt and pepper.","Open the pitta half into a pocket and spread the tzatziki inside.","Fill with the sliced chicken and eat straight away, or wrap it for later."],"substitutions":[{"ingredientId":"chicken-breast-cooked","alternatives":["turkey-breast-raw","tofu-firm"]},{"ingredientId":"greek-yogurt-0","alternatives":["skyr-plain","soy-yogurt"]}]}'::jsonb),
  ('poached-haddock-egg-rye', 'Poached haddock & egg on rye', 'breakfast', 1, '{"id":"poached-haddock-egg-rye","name":"Poached haddock & egg on rye","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":8,"ingredients":[{"ingredientId":"haddock-raw","grams":150,"display":"1 fillet (150 g)"},{"ingredientId":"egg","grams":50,"display":"1 egg"},{"ingredientId":"spinach","grams":40,"display":"1 large handful"},{"ingredientId":"rye-bread","grams":64,"display":"2 slices"},{"ingredientId":"lemon-juice","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":1,"display":"salt, pepper & chives"}],"steps":["Bring a wide pan of water to a gentle simmer.","Poach the haddock for 5–6 minutes until it flakes. Lift out and poach the egg in the same water for 3 minutes.","Wilt the spinach in a dry pan for a minute while the rye bread toasts.","Top the rye with spinach, flaked haddock and the egg. Finish with lemon, salt, pepper and chives."],"substitutions":[{"ingredientId":"haddock-raw","alternatives":["cod-raw","smoked-salmon"]},{"ingredientId":"rye-bread","alternatives":["wholewheat-bread","potato-raw"]}]}'::jsonb),
  ('cod-red-lentil-soup', 'Cod & red lentil soup', 'lunch', 4, '{"id":"cod-red-lentil-soup","name":"Cod & red lentil soup","meal":"lunch","servings":4,"prepMinutes":10,"cookMinutes":30,"ingredients":[{"ingredientId":"cod-raw","grams":600,"display":"600 g","prep":"cut into chunks"},{"ingredientId":"lentils-dry","grams":160,"display":"¾ cup","prep":"rinsed"},{"ingredientId":"carrot","grams":180,"display":"3 carrots","prep":"diced"},{"ingredientId":"onion","grams":110,"display":"1 onion","prep":"diced"},{"ingredientId":"tomatoes-canned","grams":400,"display":"1 can (400 g)"},{"ingredientId":"vegetable-stock","grams":900,"display":"3¾ cups"},{"ingredientId":"olive-oil","grams":14,"display":"1 tbsp"},{"ingredientId":"spices","grams":4,"display":"cumin, smoked paprika, salt & pepper"}],"steps":["Soften the onion and carrot in the oil in a large pot for 5 minutes. Stir in the spices.","Add the lentils, tomatoes and stock. Simmer for 20 minutes until the lentils break down.","Add the cod chunks and simmer gently for 5 minutes until just cooked.","Season to taste and serve in deep bowls."],"substitutions":[{"ingredientId":"cod-raw","alternatives":["saithe-raw","chicken-breast-raw"]},{"ingredientId":"lentils-dry","alternatives":["white-beans-cooked"]}],"notes":"Keeps 3 days in the fridge; reheat gently so the fish stays tender."}'::jsonb),
  ('cod-potato-fishcakes', 'Cod & spring onion fishcakes', 'lunch', 2, '{"id":"cod-potato-fishcakes","name":"Cod & spring onion fishcakes","meal":"lunch","servings":2,"prepMinutes":20,"cookMinutes":25,"ingredients":[{"ingredientId":"cod-raw","grams":320,"display":"320 g"},{"ingredientId":"potato-raw","grams":400,"display":"2 medium potatoes","prep":"peeled, chunked"},{"ingredientId":"egg","grams":50,"display":"1 egg","prep":"beaten"},{"ingredientId":"spring-onion","grams":30,"display":"2 spring onions","prep":"sliced"},{"ingredientId":"lettuce","grams":100,"display":"2 cups","prep":"to serve"},{"ingredientId":"lemon-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"rapeseed-oil","grams":14,"display":"1 tbsp"},{"ingredientId":"spices","grams":2,"display":"dill, salt & pepper"}],"steps":["Boil the potatoes for 15 minutes until soft, adding the cod for the last 6 minutes. Drain well.","Mash the potatoes, flake in the cod and mix with the egg, spring onion, dill, salt and pepper.","Shape into 6 cakes and chill for 10 minutes if you have time.","Fry in the oil over medium heat for 3–4 minutes per side until golden.","Serve with lettuce dressed with lemon juice."],"substitutions":[{"ingredientId":"cod-raw","alternatives":["haddock-raw","salmon-raw"]},{"ingredientId":"potato-raw","alternatives":["sweet-potato-raw"]}]}'::jsonb),
  ('saithe-corn-tacos', 'Crispy saithe tacos with lime slaw', 'lunch', 2, '{"id":"saithe-corn-tacos","name":"Crispy saithe tacos with lime slaw","meal":"lunch","servings":2,"prepMinutes":15,"cookMinutes":8,"ingredients":[{"ingredientId":"saithe-raw","grams":300,"display":"300 g","prep":"cut into strips"},{"ingredientId":"tortilla-corn","grams":156,"display":"6 small tortillas"},{"ingredientId":"cabbage","grams":150,"display":"1½ cups","prep":"finely shredded"},{"ingredientId":"avocado","grams":70,"display":"½ avocado","prep":"sliced"},{"ingredientId":"lime-juice","grams":30,"display":"2 tbsp"},{"ingredientId":"rapeseed-oil","grams":10,"display":"2 tsp"},{"ingredientId":"spices","grams":3,"display":"chilli powder, cumin, salt"}],"steps":["Toss the cabbage with half the lime juice and a pinch of salt.","Rub the fish strips with the spices and fry in the oil for 2–3 minutes per side.","Warm the tortillas in a dry pan.","Fill with slaw, fish and avocado, then squeeze over the rest of the lime."],"substitutions":[{"ingredientId":"saithe-raw","alternatives":["cod-raw","chicken-breast-raw"]},{"ingredientId":"tortilla-corn","alternatives":["tortilla-wheat"]}]}'::jsonb),
  ('saithe-couscous-salad', 'Lemon saithe & couscous salad', 'lunch', 2, '{"id":"saithe-couscous-salad","name":"Lemon saithe & couscous salad","meal":"lunch","servings":2,"prepMinutes":10,"cookMinutes":15,"ingredients":[{"ingredientId":"saithe-raw","grams":300,"display":"2 fillets (300 g)"},{"ingredientId":"couscous-dry","grams":120,"display":"⅔ cup","prep":"dry"},{"ingredientId":"tomato","grams":150,"display":"1 large tomato","prep":"diced"},{"ingredientId":"cucumber","grams":120,"display":"⅓ cucumber","prep":"diced"},{"ingredientId":"lemon-juice","grams":30,"display":"2 tbsp"},{"ingredientId":"olive-oil","grams":14,"display":"1 tbsp"},{"ingredientId":"spices","grams":3,"display":"oregano, parsley, salt & pepper"}],"steps":["Heat the oven to 200 °C. Season the fish with oregano, salt and a little lemon and bake for 12–15 minutes.","Pour 180 ml boiling water over the couscous, cover for 5 minutes, then fluff with a fork.","Stir the tomato, cucumber, parsley, oil and remaining lemon into the couscous.","Flake the fish over the salad and serve warm or cold."],"substitutions":[{"ingredientId":"saithe-raw","alternatives":["cod-raw","chickpeas-cooked"]},{"ingredientId":"couscous-dry","alternatives":["quinoa-dry","bulgur-dry"]}],"notes":"Packs well for lunch boxes; keeps 2 days in the fridge."}'::jsonb),
  ('haddock-sweetcorn-chowder', 'Haddock & sweetcorn chowder', 'lunch', 4, '{"id":"haddock-sweetcorn-chowder","name":"Haddock & sweetcorn chowder","meal":"lunch","servings":4,"prepMinutes":15,"cookMinutes":25,"ingredients":[{"ingredientId":"haddock-raw","grams":600,"display":"600 g","prep":"cut into chunks"},{"ingredientId":"potato-raw","grams":500,"display":"2–3 potatoes","prep":"diced"},{"ingredientId":"sweetcorn-canned","grams":200,"display":"1 can (200 g)","prep":"drained"},{"ingredientId":"milk","grams":500,"display":"2 cups"},{"ingredientId":"leek","grams":90,"display":"1 leek","prep":"sliced"},{"ingredientId":"onion","grams":110,"display":"1 onion","prep":"diced"},{"ingredientId":"butter","grams":14,"display":"1 tbsp"},{"ingredientId":"spices","grams":3,"display":"bay leaf, thyme, salt & pepper"}],"steps":["Melt the butter in a large pot and soften the onion and leek for 5 minutes.","Add the potatoes, herbs and 400 ml water. Simmer for 12 minutes until the potatoes are tender.","Pour in the milk and sweetcorn and bring back to a gentle simmer.","Add the haddock and cook for 5 minutes without boiling. Season and serve."],"substitutions":[{"ingredientId":"haddock-raw","alternatives":["cod-raw","saithe-raw"]},{"ingredientId":"milk","alternatives":["soy-drink","oat-drink"]}],"notes":"Keeps 2 days in the fridge. Reheat without boiling."}'::jsonb),
  ('cod-ginger-noodle-soup', 'Ginger cod noodle soup', 'lunch', 2, '{"id":"cod-ginger-noodle-soup","name":"Ginger cod noodle soup","meal":"lunch","servings":2,"prepMinutes":10,"cookMinutes":10,"ingredients":[{"ingredientId":"cod-raw","grams":320,"display":"320 g","prep":"cut into chunks"},{"ingredientId":"rice-noodles-cooked","grams":300,"display":"2 cups cooked"},{"ingredientId":"vegetable-stock","grams":800,"display":"3⅓ cups"},{"ingredientId":"spinach","grams":60,"display":"2 handfuls"},{"ingredientId":"ginger","grams":10,"display":"2 tsp","prep":"grated"},{"ingredientId":"soy-sauce","grams":16,"display":"1 tbsp"},{"ingredientId":"spring-onion","grams":30,"display":"2 spring onions","prep":"sliced"},{"ingredientId":"lime-juice","grams":15,"display":"1 tbsp"}],"steps":["Bring the stock, ginger and soy sauce to a simmer.","Add the cod and poach for 4–5 minutes until it turns white and flakes.","Stir in the spinach and noodles until hot.","Ladle into bowls and top with spring onion and lime juice."],"substitutions":[{"ingredientId":"cod-raw","alternatives":["saithe-raw","tofu-firm"]},{"ingredientId":"rice-noodles-cooked","alternatives":["rice-white-cooked"]}]}'::jsonb),
  ('saithe-coconut-curry', 'Saithe coconut curry with rice', 'dinner', 2, '{"id":"saithe-coconut-curry","name":"Saithe coconut curry with rice","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":20,"ingredients":[{"ingredientId":"saithe-raw","grams":320,"display":"320 g","prep":"cut into chunks"},{"ingredientId":"rice-white-dry","grams":140,"display":"¾ cup","prep":"dry"},{"ingredientId":"coconut-milk-light","grams":200,"display":"½ can"},{"ingredientId":"tomatoes-canned","grams":200,"display":"½ can"},{"ingredientId":"onion","grams":110,"display":"1 onion","prep":"diced"},{"ingredientId":"spinach","grams":60,"display":"2 handfuls"},{"ingredientId":"ginger","grams":10,"display":"2 tsp","prep":"grated"},{"ingredientId":"spices","grams":4,"display":"curry powder, turmeric, salt"}],"steps":["Cook the rice according to the packet.","Soften the onion in a splash of water in a deep pan, then stir in the ginger and spices for 1 minute.","Add the coconut milk and tomatoes and simmer for 8 minutes.","Add the fish and simmer gently for 5 minutes, then stir in the spinach. Serve over the rice."],"substitutions":[{"ingredientId":"saithe-raw","alternatives":["cod-raw","chickpeas-cooked"]},{"ingredientId":"rice-white-dry","alternatives":["quinoa-dry"]}]}'::jsonb),
  ('herb-cod-sweet-potato-wedges', 'Herby cod with sweet potato wedges', 'dinner', 2, '{"id":"herb-cod-sweet-potato-wedges","name":"Herby cod with sweet potato wedges","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":30,"ingredients":[{"ingredientId":"cod-raw","grams":340,"display":"2 fillets (340 g)"},{"ingredientId":"sweet-potato-raw","grams":400,"display":"2 medium","prep":"cut into wedges"},{"ingredientId":"broccoli","grams":200,"display":"1 small head","prep":"florets"},{"ingredientId":"olive-oil","grams":14,"display":"1 tbsp"},{"ingredientId":"lemon-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"spices","grams":3,"display":"parsley, garlic powder, paprika, salt"}],"steps":["Heat the oven to 210 °C. Toss the wedges with half the oil and the paprika and roast for 15 minutes.","Add the broccoli to the tray and lay the cod on top. Brush with the rest of the oil, lemon and herbs.","Roast for 12–15 minutes more until the fish flakes easily."],"substitutions":[{"ingredientId":"cod-raw","alternatives":["haddock-raw","chicken-breast-raw"]},{"ingredientId":"sweet-potato-raw","alternatives":["potato-raw"]}]}'::jsonb),
  ('haddock-spinach-pasta-bake', 'Haddock & spinach pasta bake', 'dinner', 4, '{"id":"haddock-spinach-pasta-bake","name":"Haddock & spinach pasta bake","meal":"dinner","servings":4,"prepMinutes":15,"cookMinutes":30,"ingredients":[{"ingredientId":"haddock-raw","grams":600,"display":"600 g","prep":"cut into chunks"},{"ingredientId":"pasta-dry","grams":300,"display":"300 g","prep":"dry"},{"ingredientId":"passata","grams":500,"display":"2 cups"},{"ingredientId":"spinach","grams":150,"display":"5 handfuls"},{"ingredientId":"mozzarella-light","grams":125,"display":"1 ball","prep":"torn"},{"ingredientId":"onion","grams":110,"display":"1 onion","prep":"diced"},{"ingredientId":"garlic","grams":6,"display":"2 cloves","prep":"crushed"},{"ingredientId":"spices","grams":3,"display":"basil, oregano, salt & pepper"}],"steps":["Heat the oven to 200 °C. Cook the pasta for 2 minutes less than the packet says and drain.","Simmer the onion, garlic and passata with the herbs for 5 minutes, then stir in the spinach to wilt.","Mix the pasta, sauce and raw haddock chunks in a baking dish.","Top with mozzarella and bake for 20 minutes until bubbling."],"substitutions":[{"ingredientId":"haddock-raw","alternatives":["cod-raw","chicken-breast-raw"]},{"ingredientId":"mozzarella-light","alternatives":["gouda"]}],"notes":"Keeps 3 days in the fridge; portions reheat well."}'::jsonb),
  ('lemon-butter-cod-quinoa', 'Lemon butter cod with quinoa & beans', 'dinner', 2, '{"id":"lemon-butter-cod-quinoa","name":"Lemon butter cod with quinoa & beans","meal":"dinner","servings":2,"prepMinutes":5,"cookMinutes":20,"ingredients":[{"ingredientId":"cod-raw","grams":340,"display":"2 fillets (340 g)"},{"ingredientId":"quinoa-dry","grams":120,"display":"⅔ cup","prep":"rinsed"},{"ingredientId":"green-beans","grams":200,"display":"2 cups","prep":"trimmed"},{"ingredientId":"butter","grams":14,"display":"1 tbsp"},{"ingredientId":"lemon-juice","grams":20,"display":"1½ tbsp"},{"ingredientId":"garlic","grams":3,"display":"1 clove","prep":"sliced"},{"ingredientId":"spices","grams":2,"display":"salt & pepper"}],"steps":["Simmer the quinoa in twice its volume of water for 15 minutes. Steam the beans over it for the last 5.","Season the cod and sear in half the butter for 3–4 minutes per side.","Add the remaining butter, garlic and lemon to the pan and spoon over the fish.","Serve the cod on the quinoa and beans with the pan juices."],"substitutions":[{"ingredientId":"cod-raw","alternatives":["saithe-raw","salmon-raw"]},{"ingredientId":"butter","alternatives":["olive-oil"]}]}'::jsonb),
  ('smoked-salmon-eggs-toast', 'Smoked salmon scrambled eggs on toast', 'breakfast', 1, '{"id":"smoked-salmon-eggs-toast","name":"Smoked salmon scrambled eggs on toast","meal":"breakfast","servings":1,"prepMinutes":3,"cookMinutes":5,"ingredients":[{"ingredientId":"smoked-salmon","grams":120,"display":"120 g","prep":"torn"},{"ingredientId":"egg","grams":100,"display":"2 eggs"},{"ingredientId":"wholewheat-bread","grams":64,"display":"2 slices"},{"ingredientId":"olive-oil","grams":4,"display":"1 tsp"},{"ingredientId":"spices","grams":1,"display":"dill, black pepper"}],"steps":["Beat the eggs with pepper and dill.","Warm the oil in a non-stick pan and stir the eggs gently over low heat until softly set.","Toast the bread and pile on the eggs with the smoked salmon."],"substitutions":[{"ingredientId":"smoked-salmon","alternatives":["tuna-canned","ham-sliced"]},{"ingredientId":"wholewheat-bread","alternatives":["rye-bread"]}]}'::jsonb),
  ('sardine-avocado-toast', 'Sardine & avocado toast', 'breakfast', 1, '{"id":"sardine-avocado-toast","name":"Sardine & avocado toast","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":3,"ingredients":[{"ingredientId":"sardines-canned","grams":90,"display":"1 can (90 g)","prep":"drained"},{"ingredientId":"wholewheat-bread","grams":64,"display":"2 slices"},{"ingredientId":"avocado","grams":60,"display":"½ small avocado"},{"ingredientId":"tomato","grams":60,"display":"½ tomato","prep":"sliced"},{"ingredientId":"lemon-juice","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":1,"display":"chilli flakes, salt & pepper"}],"steps":["Toast the bread.","Mash the avocado with lemon, salt and pepper and spread on the toast.","Top with tomato slices and the sardines, then sprinkle with chilli flakes."],"substitutions":[{"ingredientId":"sardines-canned","alternatives":["mackerel-canned","egg"]},{"ingredientId":"wholewheat-bread","alternatives":["rye-bread"]}]}'::jsonb),
  ('smoked-salmon-rice-cakes', 'Smoked salmon rice cakes', 'snack', 1, '{"id":"smoked-salmon-rice-cakes","name":"Smoked salmon rice cakes","meal":"snack","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"smoked-salmon","grams":60,"display":"60 g"},{"ingredientId":"cottage-cheese","grams":50,"display":"3 tbsp"},{"ingredientId":"rice-cakes","grams":18,"display":"2 rice cakes"},{"ingredientId":"cucumber","grams":30,"display":"6 thin slices"},{"ingredientId":"spices","grams":1,"display":"dill, black pepper"}],"steps":["Spread the cottage cheese over the rice cakes.","Layer on the cucumber and smoked salmon.","Finish with dill and black pepper."],"substitutions":[{"ingredientId":"smoked-salmon","alternatives":["tuna-canned","ham-sliced"]},{"ingredientId":"cottage-cheese","alternatives":["skyr-plain","hummus"]}]}'::jsonb),
  ('smoked-salmon-edamame-bowl', 'Smoked salmon & edamame rice bowl', 'lunch', 1, '{"id":"smoked-salmon-edamame-bowl","name":"Smoked salmon & edamame rice bowl","meal":"lunch","servings":1,"prepMinutes":8,"cookMinutes":0,"ingredients":[{"ingredientId":"smoked-salmon","grams":120,"display":"120 g","prep":"sliced"},{"ingredientId":"rice-white-cooked","grams":180,"display":"1 heaped cup","prep":"cooked"},{"ingredientId":"edamame","grams":70,"display":"½ cup","prep":"thawed"},{"ingredientId":"cucumber","grams":80,"display":"¼ cucumber","prep":"diced"},{"ingredientId":"avocado","grams":40,"display":"¼ avocado","prep":"sliced"},{"ingredientId":"soy-sauce","grams":10,"display":"2 tsp"},{"ingredientId":"sesame-oil","grams":4,"display":"1 tsp"}],"steps":["Put the rice in a bowl (warm it up first if you prefer).","Arrange the salmon, edamame, cucumber and avocado on top.","Whisk the soy sauce and sesame oil and drizzle over."],"substitutions":[{"ingredientId":"smoked-salmon","alternatives":["salmon-raw","tofu-firm"]},{"ingredientId":"rice-white-cooked","alternatives":["quinoa-cooked"]}]}'::jsonb),
  ('mackerel-potato-salad', 'Nordic mackerel potato salad', 'lunch', 1, '{"id":"mackerel-potato-salad","name":"Nordic mackerel potato salad","meal":"lunch","servings":1,"prepMinutes":8,"cookMinutes":15,"ingredients":[{"ingredientId":"mackerel-canned","grams":125,"display":"1 can (125 g)","prep":"drained, flaked"},{"ingredientId":"potato-raw","grams":250,"display":"3 small potatoes","prep":"halved"},{"ingredientId":"greek-yogurt-0","grams":60,"display":"¼ cup"},{"ingredientId":"cucumber","grams":80,"display":"¼ cucumber","prep":"diced"},{"ingredientId":"onion","grams":25,"display":"¼ red onion","prep":"finely sliced"},{"ingredientId":"mustard","grams":10,"display":"2 tsp"},{"ingredientId":"spices","grams":1,"display":"dill, salt & pepper"}],"steps":["Boil the potatoes for 12–15 minutes until tender, drain and cool a little.","Mix the yogurt, mustard and dill into a dressing.","Toss the potatoes, cucumber and onion with the dressing and fold in the mackerel."],"substitutions":[{"ingredientId":"mackerel-canned","alternatives":["smoked-salmon","egg"]},{"ingredientId":"greek-yogurt-0","alternatives":["skyr-plain","soy-yogurt"]}],"notes":"Make it the night before: the flavours get better in the fridge."}'::jsonb),
  ('sardine-tomato-spaghetti', 'Sardine & chilli tomato spaghetti', 'lunch', 2, '{"id":"sardine-tomato-spaghetti","name":"Sardine & chilli tomato spaghetti","meal":"lunch","servings":2,"prepMinutes":5,"cookMinutes":15,"ingredients":[{"ingredientId":"sardines-canned","grams":180,"display":"2 cans (180 g)","prep":"drained"},{"ingredientId":"pasta-dry","grams":160,"display":"160 g","prep":"dry"},{"ingredientId":"tomatoes-canned","grams":400,"display":"1 can (400 g)"},{"ingredientId":"spinach","grams":60,"display":"2 handfuls"},{"ingredientId":"garlic","grams":6,"display":"2 cloves","prep":"sliced"},{"ingredientId":"olive-oil","grams":7,"display":"½ tbsp"},{"ingredientId":"spices","grams":2,"display":"chilli flakes, salt & pepper"}],"steps":["Cook the spaghetti according to the packet.","Warm the oil with the garlic and chilli for 1 minute, add the tomatoes and simmer for 8 minutes.","Break the sardines into the sauce and stir in the spinach until wilted.","Toss with the drained spaghetti and a splash of pasta water."],"substitutions":[{"ingredientId":"sardines-canned","alternatives":["mackerel-canned","tuna-canned"]},{"ingredientId":"pasta-dry","alternatives":["rice-white-dry"]}]}'::jsonb),
  ('salmon-quinoa-rocket-salad', 'Warm salmon, quinoa & rocket salad', 'lunch', 2, '{"id":"salmon-quinoa-rocket-salad","name":"Warm salmon, quinoa & rocket salad","meal":"lunch","servings":2,"prepMinutes":10,"cookMinutes":15,"ingredients":[{"ingredientId":"salmon-raw","grams":260,"display":"2 fillets (260 g)"},{"ingredientId":"quinoa-cooked","grams":300,"display":"1⅔ cups cooked"},{"ingredientId":"rocket","grams":40,"display":"2 cups"},{"ingredientId":"tomato","grams":150,"display":"1 large tomato","prep":"chopped"},{"ingredientId":"cucumber","grams":100,"display":"⅓ cucumber","prep":"chopped"},{"ingredientId":"lemon-juice","grams":20,"display":"1½ tbsp"},{"ingredientId":"olive-oil","grams":7,"display":"½ tbsp"},{"ingredientId":"spices","grams":2,"display":"salt & pepper"}],"steps":["Heat the oven to 200 °C and bake the seasoned salmon for 12–15 minutes.","Toss the quinoa, rocket, tomato and cucumber with the lemon juice and oil.","Flake the salmon over the salad and serve."],"substitutions":[{"ingredientId":"salmon-raw","alternatives":["mackerel-canned","chicken-breast-cooked"]},{"ingredientId":"quinoa-cooked","alternatives":["rice-white-cooked"]}]}'::jsonb),
  ('mackerel-hummus-pitta', 'Mackerel & hummus pitta pockets', 'lunch', 1, '{"id":"mackerel-hummus-pitta","name":"Mackerel & hummus pitta pockets","meal":"lunch","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"mackerel-canned","grams":125,"display":"1 can (125 g)","prep":"drained"},{"ingredientId":"pita-wholewheat","grams":64,"display":"1 pitta"},{"ingredientId":"hummus","grams":30,"display":"2 tbsp"},{"ingredientId":"lettuce","grams":30,"display":"1 handful","prep":"shredded"},{"ingredientId":"tomato","grams":60,"display":"½ tomato","prep":"sliced"},{"ingredientId":"lemon-juice","grams":5,"display":"1 tsp"}],"steps":["Split the pitta open into a pocket.","Spread the hummus inside and add the lettuce and tomato.","Flake in the mackerel and squeeze over the lemon."],"substitutions":[{"ingredientId":"mackerel-canned","alternatives":["sardines-canned","chickpeas-cooked"]},{"ingredientId":"pita-wholewheat","alternatives":["tortilla-wheat"]}]}'::jsonb),
  ('honey-soy-salmon-noodles', 'Honey soy salmon noodles', 'dinner', 2, '{"id":"honey-soy-salmon-noodles","name":"Honey soy salmon noodles","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":12,"ingredients":[{"ingredientId":"salmon-raw","grams":260,"display":"2 fillets (260 g)","prep":"cubed"},{"ingredientId":"egg-noodles-dry","grams":130,"display":"2 nests","prep":"dry"},{"ingredientId":"broccoli","grams":150,"display":"1½ cups","prep":"small florets"},{"ingredientId":"bell-pepper","grams":120,"display":"1 pepper","prep":"sliced"},{"ingredientId":"soy-sauce","grams":30,"display":"2 tbsp"},{"ingredientId":"honey","grams":14,"display":"2 tsp"},{"ingredientId":"ginger","grams":6,"display":"1 tbsp","prep":"grated"},{"ingredientId":"garlic","grams":6,"display":"2 cloves","prep":"crushed"}],"steps":["Cook the noodles according to the packet and drain.","Sear the salmon cubes in a hot non-stick wok for 3 minutes, then set aside.","Stir-fry the broccoli and pepper for 4 minutes with a splash of water.","Add the garlic, ginger, soy and honey, then toss in the noodles and salmon until glossy."],"substitutions":[{"ingredientId":"salmon-raw","alternatives":["chicken-breast-raw","tofu-firm"]},{"ingredientId":"egg-noodles-dry","alternatives":["rice-noodles-cooked"]}]}'::jsonb),
  ('salmon-leek-potato-traybake', 'Salmon, leek & potato traybake', 'dinner', 2, '{"id":"salmon-leek-potato-traybake","name":"Salmon, leek & potato traybake","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":35,"ingredients":[{"ingredientId":"salmon-raw","grams":260,"display":"2 fillets (260 g)"},{"ingredientId":"potato-raw","grams":450,"display":"4 small potatoes","prep":"sliced thick"},{"ingredientId":"leek","grams":180,"display":"2 leeks","prep":"sliced"},{"ingredientId":"olive-oil","grams":10,"display":"2 tsp"},{"ingredientId":"mustard","grams":10,"display":"2 tsp"},{"ingredientId":"lemon-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"spices","grams":2,"display":"dill, salt & pepper"}],"steps":["Heat the oven to 200 °C. Toss the potatoes with the oil and salt and roast for 20 minutes.","Stir the leeks into the tray. Brush the salmon with mustard and lemon and nestle it on top.","Roast for 12–15 minutes until the salmon is just cooked. Scatter with dill."],"substitutions":[{"ingredientId":"salmon-raw","alternatives":["cod-raw","chicken-thigh-raw"]},{"ingredientId":"potato-raw","alternatives":["sweet-potato-raw"]}]}'::jsonb),
  ('creamy-salmon-spinach-pasta', 'Creamy salmon & spinach pasta', 'dinner', 4, '{"id":"creamy-salmon-spinach-pasta","name":"Creamy salmon & spinach pasta","meal":"dinner","servings":4,"prepMinutes":10,"cookMinutes":15,"ingredients":[{"ingredientId":"salmon-raw","grams":500,"display":"500 g","prep":"skinned, cubed"},{"ingredientId":"pasta-dry","grams":320,"display":"320 g","prep":"dry"},{"ingredientId":"ricotta","grams":200,"display":"200 g"},{"ingredientId":"spinach","grams":150,"display":"5 handfuls"},{"ingredientId":"parmesan","grams":20,"display":"4 tbsp","prep":"grated"},{"ingredientId":"lemon-juice","grams":20,"display":"1½ tbsp"},{"ingredientId":"garlic","grams":6,"display":"2 cloves","prep":"crushed"},{"ingredientId":"spices","grams":2,"display":"salt & pepper"}],"steps":["Cook the pasta according to the packet. Keep a cup of the cooking water.","Fry the salmon cubes in a large non-stick pan for 4 minutes until just cooked, then add the garlic.","Stir in the ricotta, lemon and a splash of pasta water to make a sauce, then wilt in the spinach.","Toss through the pasta, season and top with parmesan."],"substitutions":[{"ingredientId":"salmon-raw","alternatives":["smoked-salmon","chicken-breast-raw"]},{"ingredientId":"ricotta","alternatives":["cottage-cheese"]}],"notes":"Keeps 2 days in the fridge; loosen with a little milk when reheating."}'::jsonb),
  ('salmon-cauliflower-chickpea-curry', 'Salmon, cauliflower & chickpea curry', 'dinner', 2, '{"id":"salmon-cauliflower-chickpea-curry","name":"Salmon, cauliflower & chickpea curry","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":20,"ingredients":[{"ingredientId":"salmon-raw","grams":260,"display":"2 fillets (260 g)","prep":"cubed"},{"ingredientId":"rice-white-dry","grams":120,"display":"⅔ cup","prep":"dry"},{"ingredientId":"coconut-milk-light","grams":200,"display":"½ can"},{"ingredientId":"cauliflower","grams":200,"display":"2 cups","prep":"small florets"},{"ingredientId":"chickpeas-cooked","grams":120,"display":"½ can","prep":"drained"},{"ingredientId":"onion","grams":80,"display":"¾ onion","prep":"diced"},{"ingredientId":"spices","grams":4,"display":"garam masala, turmeric, chilli, salt"}],"steps":["Cook the rice according to the packet.","Soften the onion in a splash of water, then stir in the spices for 1 minute.","Add the cauliflower, chickpeas, coconut milk and 100 ml water and simmer for 10 minutes.","Add the salmon and simmer for 5 minutes more. Serve with the rice."],"substitutions":[{"ingredientId":"salmon-raw","alternatives":["cod-raw","tofu-firm"]},{"ingredientId":"chickpeas-cooked","alternatives":["lentils-cooked"]}]}'::jsonb),
  ('salmon-fajita-wraps', 'Salmon fajita wraps', 'dinner', 2, '{"id":"salmon-fajita-wraps","name":"Salmon fajita wraps","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":10,"ingredients":[{"ingredientId":"salmon-raw","grams":260,"display":"2 fillets (260 g)","prep":"cut into strips"},{"ingredientId":"tortilla-wheat","grams":180,"display":"4 tortillas"},{"ingredientId":"bell-pepper","grams":150,"display":"1 large pepper","prep":"sliced"},{"ingredientId":"onion","grams":80,"display":"¾ onion","prep":"sliced"},{"ingredientId":"greek-yogurt-0","grams":80,"display":"⅓ cup"},{"ingredientId":"lime-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"spices","grams":4,"display":"fajita spice (cumin, paprika, chilli), salt"}],"steps":["Toss the salmon strips with half the spice mix.","Fry the pepper and onion in a hot non-stick pan for 5 minutes with the remaining spice.","Push the veg aside and cook the salmon for 3–4 minutes, turning gently.","Warm the tortillas, fill with salmon and veg, and top with yogurt mixed with the lime juice."],"substitutions":[{"ingredientId":"salmon-raw","alternatives":["chicken-breast-raw","black-beans-cooked"]},{"ingredientId":"greek-yogurt-0","alternatives":["soy-yogurt"]}]}'::jsonb),
  ('smoked-salmon-pea-risotto', 'Smoked salmon & pea risotto', 'dinner', 2, '{"id":"smoked-salmon-pea-risotto","name":"Smoked salmon & pea risotto","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":25,"ingredients":[{"ingredientId":"smoked-salmon","grams":200,"display":"200 g","prep":"torn"},{"ingredientId":"rice-white-dry","grams":150,"display":"¾ cup","prep":"risotto rice, dry"},{"ingredientId":"peas-green","grams":150,"display":"1 cup","prep":"frozen"},{"ingredientId":"onion","grams":80,"display":"¾ onion","prep":"finely diced"},{"ingredientId":"vegetable-stock","grams":700,"display":"3 cups","prep":"hot"},{"ingredientId":"parmesan","grams":20,"display":"4 tbsp","prep":"grated"},{"ingredientId":"butter","grams":10,"display":"2 tsp"},{"ingredientId":"lemon-juice","grams":10,"display":"2 tsp"}],"steps":["Melt the butter in a wide pan and soften the onion for 4 minutes. Stir in the rice for 1 minute.","Add the hot stock a ladle at a time, stirring, and simmer for about 18 minutes until creamy.","Stir in the peas for the last 3 minutes.","Off the heat, fold in the parmesan, lemon and most of the salmon. Top with the rest."],"substitutions":[{"ingredientId":"smoked-salmon","alternatives":["salmon-raw","chicken-breast-cooked"]},{"ingredientId":"parmesan","alternatives":["gouda"]}]}'::jsonb),
  ('tuna-spinach-omelette', 'Tuna & spinach omelette', 'breakfast', 1, '{"id":"tuna-spinach-omelette","name":"Tuna & spinach omelette","meal":"breakfast","servings":1,"prepMinutes":3,"cookMinutes":5,"ingredients":[{"ingredientId":"tuna-canned","grams":120,"display":"1 can (120 g)","prep":"drained"},{"ingredientId":"egg","grams":100,"display":"2 eggs"},{"ingredientId":"spinach","grams":30,"display":"1 large handful"},{"ingredientId":"tomato","grams":80,"display":"1 small tomato","prep":"diced"},{"ingredientId":"avocado","grams":50,"display":"⅓ avocado","prep":"sliced"},{"ingredientId":"olive-oil","grams":4,"display":"1 tsp"},{"ingredientId":"spices","grams":1,"display":"salt & pepper"}],"steps":["Beat the eggs with salt and pepper.","Warm the oil in a non-stick pan, wilt the spinach, then pour in the eggs.","When almost set, scatter the tuna and tomato over one half and fold.","Serve with the avocado on the side."],"substitutions":[{"ingredientId":"tuna-canned","alternatives":["smoked-salmon","cottage-cheese"]},{"ingredientId":"egg","alternatives":["egg-white"]}]}'::jsonb),
  ('tuna-black-bean-breakfast-burrito', 'Tuna & black bean breakfast burrito', 'breakfast', 1, '{"id":"tuna-black-bean-breakfast-burrito","name":"Tuna & black bean breakfast burrito","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":5,"ingredients":[{"ingredientId":"tuna-canned","grams":120,"display":"1 can (120 g)","prep":"drained"},{"ingredientId":"tortilla-wheat","grams":60,"display":"1 large tortilla"},{"ingredientId":"egg","grams":50,"display":"1 egg"},{"ingredientId":"black-beans-cooked","grams":60,"display":"¼ can","prep":"drained"},{"ingredientId":"tomato","grams":60,"display":"½ tomato","prep":"diced"},{"ingredientId":"spices","grams":2,"display":"cumin, chilli, salt"}],"steps":["Scramble the egg in a non-stick pan with the beans and spices for 2 minutes.","Stir in the tuna and tomato until warm.","Spoon into the tortilla, roll up tightly and toast seam-side down for 1 minute."],"substitutions":[{"ingredientId":"tuna-canned","alternatives":["chicken-breast-cooked","tofu-firm"]},{"ingredientId":"tortilla-wheat","alternatives":["tortilla-corn"]}]}'::jsonb),
  ('tuna-hummus-veg-sticks', 'Tuna hummus with veg sticks', 'snack', 1, '{"id":"tuna-hummus-veg-sticks","name":"Tuna hummus with veg sticks","meal":"snack","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"tuna-canned","grams":60,"display":"½ can (60 g)","prep":"drained"},{"ingredientId":"hummus","grams":30,"display":"2 tbsp"},{"ingredientId":"carrot","grams":80,"display":"1 large carrot","prep":"cut into sticks"},{"ingredientId":"cucumber","grams":80,"display":"¼ cucumber","prep":"cut into sticks"},{"ingredientId":"lemon-juice","grams":5,"display":"1 tsp"}],"steps":["Mash the tuna into the hummus with the lemon juice.","Cut the carrot and cucumber into sticks.","Dip and eat."],"substitutions":[{"ingredientId":"tuna-canned","alternatives":["chickpeas-cooked","mackerel-canned"]},{"ingredientId":"carrot","alternatives":["bell-pepper"]}]}'::jsonb),
  ('tuna-nicoise-salad', 'Tuna niçoise salad', 'lunch', 1, '{"id":"tuna-nicoise-salad","name":"Tuna niçoise salad","meal":"lunch","servings":1,"prepMinutes":10,"cookMinutes":15,"ingredients":[{"ingredientId":"tuna-canned","grams":120,"display":"1 can (120 g)","prep":"drained"},{"ingredientId":"egg","grams":50,"display":"1 egg"},{"ingredientId":"potato-raw","grams":200,"display":"3 baby potatoes","prep":"halved"},{"ingredientId":"green-beans","grams":100,"display":"1 cup","prep":"trimmed"},{"ingredientId":"tomato","grams":80,"display":"1 small tomato","prep":"wedges"},{"ingredientId":"lettuce","grams":50,"display":"1 cup","prep":"torn"},{"ingredientId":"olive-oil","grams":7,"display":"½ tbsp"},{"ingredientId":"spices","grams":2,"display":"mustard powder, salt & pepper"}],"steps":["Boil the potatoes for 12 minutes. Add the egg for the last 8 and the beans for the last 4.","Drain, cool the egg in cold water and peel it.","Arrange the lettuce, potatoes, beans, tomato and tuna on a plate with the egg halved.","Drizzle with the oil, salt and pepper."],"substitutions":[{"ingredientId":"tuna-canned","alternatives":["salmon-raw","white-beans-cooked"]},{"ingredientId":"potato-raw","alternatives":["quinoa-cooked"]}]}'::jsonb),
  ('tuna-sweetcorn-wrap', 'Tuna sweetcorn wrap', 'lunch', 1, '{"id":"tuna-sweetcorn-wrap","name":"Tuna sweetcorn wrap","meal":"lunch","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"tuna-canned","grams":120,"display":"1 can (120 g)","prep":"drained"},{"ingredientId":"tortilla-wheat","grams":90,"display":"2 tortillas"},{"ingredientId":"sweetcorn-canned","grams":60,"display":"⅓ cup","prep":"drained"},{"ingredientId":"greek-yogurt-0","grams":50,"display":"3 tbsp"},{"ingredientId":"lettuce","grams":30,"display":"1 handful","prep":"shredded"},{"ingredientId":"spring-onion","grams":15,"display":"1 spring onion","prep":"sliced"},{"ingredientId":"spices","grams":1,"display":"salt & pepper"}],"steps":["Mix the tuna, sweetcorn, yogurt and spring onion with salt and pepper.","Lay the lettuce down the middle of each tortilla.","Spoon on the tuna mix and roll up tightly."],"substitutions":[{"ingredientId":"tuna-canned","alternatives":["chicken-breast-cooked","chickpeas-cooked"]},{"ingredientId":"greek-yogurt-0","alternatives":["skyr-plain","soy-yogurt"]}]}'::jsonb),
  ('tuna-edamame-quinoa-bowl', 'Sesame tuna & edamame quinoa bowl', 'lunch', 1, '{"id":"tuna-edamame-quinoa-bowl","name":"Sesame tuna & edamame quinoa bowl","meal":"lunch","servings":1,"prepMinutes":8,"cookMinutes":0,"ingredients":[{"ingredientId":"tuna-canned","grams":120,"display":"1 can (120 g)","prep":"drained"},{"ingredientId":"quinoa-cooked","grams":180,"display":"1 cup cooked"},{"ingredientId":"edamame","grams":60,"display":"⅓ cup","prep":"thawed"},{"ingredientId":"carrot","grams":60,"display":"1 carrot","prep":"grated"},{"ingredientId":"cucumber","grams":60,"display":"¼ cucumber","prep":"diced"},{"ingredientId":"lime-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"sesame-oil","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":1,"display":"chilli flakes, salt"}],"steps":["Put the quinoa in a bowl.","Top with the tuna, edamame, carrot and cucumber.","Whisk the lime juice, sesame oil and chilli flakes and pour over."],"substitutions":[{"ingredientId":"tuna-canned","alternatives":["smoked-salmon","tofu-firm"]},{"ingredientId":"quinoa-cooked","alternatives":["rice-white-cooked"]}]}'::jsonb),
  ('tuna-sweetcorn-pasta-bake', 'Cheesy tuna & sweetcorn pasta bake', 'dinner', 4, '{"id":"tuna-sweetcorn-pasta-bake","name":"Cheesy tuna & sweetcorn pasta bake","meal":"dinner","servings":4,"prepMinutes":10,"cookMinutes":30,"ingredients":[{"ingredientId":"tuna-canned","grams":360,"display":"3 cans (360 g)","prep":"drained"},{"ingredientId":"pasta-dry","grams":300,"display":"300 g","prep":"dry"},{"ingredientId":"sweetcorn-canned","grams":200,"display":"1 can (200 g)","prep":"drained"},{"ingredientId":"passata","grams":500,"display":"2 cups"},{"ingredientId":"gouda","grams":80,"display":"4 slices","prep":"grated"},{"ingredientId":"onion","grams":110,"display":"1 onion","prep":"diced"},{"ingredientId":"spices","grams":3,"display":"oregano, salt & pepper"}],"steps":["Heat the oven to 200 °C. Cook the pasta for 2 minutes less than the packet says and drain.","Simmer the onion in the passata with the oregano for 5 minutes.","Stir in the pasta, tuna and sweetcorn and tip into a baking dish.","Scatter with the cheese and bake for 20 minutes until golden."],"substitutions":[{"ingredientId":"tuna-canned","alternatives":["chicken-breast-cooked","white-beans-cooked"]},{"ingredientId":"gouda","alternatives":["mozzarella-light"]}],"notes":"Keeps 3 days in the fridge, or freeze portions for up to a month."}'::jsonb),
  ('tuna-egg-fried-rice', 'Tuna egg fried rice', 'dinner', 2, '{"id":"tuna-egg-fried-rice","name":"Tuna egg fried rice","meal":"dinner","servings":2,"prepMinutes":5,"cookMinutes":10,"ingredients":[{"ingredientId":"tuna-canned","grams":240,"display":"2 cans (240 g)","prep":"drained"},{"ingredientId":"rice-white-cooked","grams":400,"display":"2½ cups","prep":"cooked, cold"},{"ingredientId":"egg","grams":100,"display":"2 eggs","prep":"beaten"},{"ingredientId":"peas-green","grams":120,"display":"1 cup","prep":"frozen"},{"ingredientId":"spring-onion","grams":30,"display":"2 spring onions","prep":"sliced"},{"ingredientId":"soy-sauce","grams":24,"display":"1½ tbsp"},{"ingredientId":"rapeseed-oil","grams":10,"display":"2 tsp"}],"steps":["Heat the oil in a wok, add the eggs and scramble until just set. Push to one side.","Add the rice and peas and stir-fry for 4 minutes until hot.","Toss in the tuna and soy sauce and stir-fry for 2 minutes more.","Finish with the spring onions."],"substitutions":[{"ingredientId":"tuna-canned","alternatives":["chicken-breast-cooked","tofu-firm"]},{"ingredientId":"rice-white-cooked","alternatives":["quinoa-cooked"]}]}'::jsonb),
  ('tuna-tomato-garlic-spaghetti', 'Tuna & garlic tomato spaghetti', 'dinner', 2, '{"id":"tuna-tomato-garlic-spaghetti","name":"Tuna & garlic tomato spaghetti","meal":"dinner","servings":2,"prepMinutes":5,"cookMinutes":15,"ingredients":[{"ingredientId":"tuna-canned","grams":240,"display":"2 cans (240 g)","prep":"drained"},{"ingredientId":"pasta-dry","grams":160,"display":"160 g","prep":"dry"},{"ingredientId":"tomatoes-canned","grams":400,"display":"1 can (400 g)"},{"ingredientId":"onion","grams":80,"display":"¾ onion","prep":"diced"},{"ingredientId":"garlic","grams":9,"display":"3 cloves","prep":"sliced"},{"ingredientId":"olive-oil","grams":10,"display":"2 tsp"},{"ingredientId":"spices","grams":2,"display":"oregano, chilli flakes, salt"}],"steps":["Cook the spaghetti according to the packet.","Soften the onion and garlic in the oil for 4 minutes.","Add the tomatoes and oregano and simmer for 8 minutes, then stir in the tuna.","Toss with the drained spaghetti and a little cooking water."],"substitutions":[{"ingredientId":"tuna-canned","alternatives":["sardines-canned","white-beans-cooked"]},{"ingredientId":"pasta-dry","alternatives":["rice-white-dry"]}]}'::jsonb),
  ('tuna-sweet-potato-cakes', 'Tuna sweet potato cakes', 'dinner', 2, '{"id":"tuna-sweet-potato-cakes","name":"Tuna sweet potato cakes","meal":"dinner","servings":2,"prepMinutes":15,"cookMinutes":25,"ingredients":[{"ingredientId":"tuna-canned","grams":240,"display":"2 cans (240 g)","prep":"drained"},{"ingredientId":"sweet-potato-raw","grams":400,"display":"2 medium","prep":"peeled, chunked"},{"ingredientId":"egg","grams":50,"display":"1 egg","prep":"beaten"},{"ingredientId":"spring-onion","grams":30,"display":"2 spring onions","prep":"sliced"},{"ingredientId":"lettuce","grams":80,"display":"2 cups","prep":"to serve"},{"ingredientId":"lemon-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"olive-oil","grams":7,"display":"½ tbsp"},{"ingredientId":"spices","grams":2,"display":"smoked paprika, salt & pepper"}],"steps":["Steam or microwave the sweet potato until soft, then mash and let it cool a little.","Mix in the tuna, egg, spring onion and spices, and shape into 6 cakes.","Heat the oven to 200 °C, brush the cakes with oil on a lined tray and bake for 20 minutes, turning once.","Serve with lettuce and lemon juice."],"substitutions":[{"ingredientId":"tuna-canned","alternatives":["salmon-raw","chickpeas-cooked"]},{"ingredientId":"sweet-potato-raw","alternatives":["potato-raw"]}]}'::jsonb),
  ('tuna-kidney-bean-chilli', 'Tuna & kidney bean chilli with rice', 'dinner', 4, '{"id":"tuna-kidney-bean-chilli","name":"Tuna & kidney bean chilli with rice","meal":"dinner","servings":4,"prepMinutes":10,"cookMinutes":25,"ingredients":[{"ingredientId":"tuna-canned","grams":480,"display":"4 cans (480 g)","prep":"drained"},{"ingredientId":"kidney-beans-cooked","grams":480,"display":"2 cans","prep":"drained"},{"ingredientId":"tomatoes-canned","grams":800,"display":"2 cans (800 g)"},{"ingredientId":"bell-pepper","grams":240,"display":"2 peppers","prep":"diced"},{"ingredientId":"onion","grams":110,"display":"1 onion","prep":"diced"},{"ingredientId":"rice-white-dry","grams":260,"display":"1⅓ cups","prep":"dry"},{"ingredientId":"rapeseed-oil","grams":10,"display":"2 tsp"},{"ingredientId":"spices","grams":4,"display":"chilli, cumin, smoked paprika, salt"}],"steps":["Soften the onion and pepper in the oil in a large pot for 5 minutes. Stir in the spices.","Add the tomatoes and beans and simmer for 15 minutes until thick.","Meanwhile cook the rice according to the packet.","Fold the tuna into the chilli for the last 3 minutes so it stays in chunks. Serve with the rice."],"substitutions":[{"ingredientId":"tuna-canned","alternatives":["turkey-mince-raw","black-beans-cooked"]},{"ingredientId":"rice-white-dry","alternatives":["quinoa-dry"]}],"notes":"Keeps 3 days in the fridge; the chilli freezes well without the rice."}'::jsonb),
  ('tuna-peanut-rice-noodles', 'Peanut tuna rice noodles', 'dinner', 2, '{"id":"tuna-peanut-rice-noodles","name":"Peanut tuna rice noodles","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":8,"ingredients":[{"ingredientId":"tuna-canned","grams":240,"display":"2 cans (240 g)","prep":"drained"},{"ingredientId":"rice-noodles-cooked","grams":350,"display":"2 cups cooked"},{"ingredientId":"cabbage","grams":150,"display":"1½ cups","prep":"shredded"},{"ingredientId":"carrot","grams":100,"display":"1 large carrot","prep":"cut into matchsticks"},{"ingredientId":"peanut-butter","grams":32,"display":"2 tbsp"},{"ingredientId":"soy-sauce","grams":16,"display":"1 tbsp"},{"ingredientId":"lime-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"spring-onion","grams":30,"display":"2 spring onions","prep":"sliced"}],"steps":["Whisk the peanut butter, soy sauce, lime and 3 tbsp hot water into a sauce.","Stir-fry the cabbage and carrot in a hot wok with a splash of water for 3 minutes.","Add the noodles and sauce and toss until coated and hot.","Fold in the tuna and scatter with spring onions."],"substitutions":[{"ingredientId":"tuna-canned","alternatives":["chicken-breast-cooked","tofu-firm"]},{"ingredientId":"peanut-butter","alternatives":["tahini"]}]}'::jsonb),
  ('tuna-stuffed-jacket-potatoes', 'Tuna-stuffed jacket potatoes', 'dinner', 2, '{"id":"tuna-stuffed-jacket-potatoes","name":"Tuna-stuffed jacket potatoes","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":50,"ingredients":[{"ingredientId":"potato-raw","grams":500,"display":"2 large potatoes"},{"ingredientId":"tuna-canned","grams":240,"display":"2 cans (240 g)","prep":"drained"},{"ingredientId":"greek-yogurt-0","grams":100,"display":"⅓ cup"},{"ingredientId":"sweetcorn-canned","grams":80,"display":"½ cup","prep":"drained"},{"ingredientId":"spring-onion","grams":20,"display":"1 spring onion","prep":"sliced"},{"ingredientId":"gouda","grams":40,"display":"2 slices","prep":"grated"},{"ingredientId":"broccoli","grams":150,"display":"1½ cups","prep":"florets, to serve"},{"ingredientId":"spices","grams":1,"display":"salt & pepper"}],"steps":["Heat the oven to 200 °C. Prick the potatoes and bake for 45–50 minutes until soft inside.","Mix the tuna, yogurt, sweetcorn and spring onion with salt and pepper.","Steam the broccoli for 5 minutes.","Split the potatoes, pile in the tuna mix, top with cheese and return to the oven for 5 minutes."],"substitutions":[{"ingredientId":"tuna-canned","alternatives":["mackerel-canned","cottage-cheese"]},{"ingredientId":"potato-raw","alternatives":["sweet-potato-raw"]}],"notes":"Microwave the potatoes for 10 minutes first to cut the oven time in half."}'::jsonb),
  ('prawn-cocktail-lettuce-cups', 'Prawn cocktail lettuce cups', 'snack', 1, '{"id":"prawn-cocktail-lettuce-cups","name":"Prawn cocktail lettuce cups","meal":"snack","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"shrimp-cooked","grams":80,"display":"80 g","prep":"thawed if frozen"},{"ingredientId":"greek-yogurt-0","grams":30,"display":"2 tbsp"},{"ingredientId":"passata","grams":10,"display":"2 tsp"},{"ingredientId":"lettuce","grams":40,"display":"4 leaves"},{"ingredientId":"avocado","grams":30,"display":"¼ small avocado","prep":"diced"},{"ingredientId":"lemon-juice","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":1,"display":"paprika, salt & pepper"}],"steps":["Stir the yogurt, passata, lemon and a pinch of paprika into a pink sauce.","Fold in the prawns and avocado.","Spoon into the lettuce leaves and dust with a little more paprika."],"substitutions":[{"ingredientId":"shrimp-cooked","alternatives":["chicken-breast-cooked","tuna-canned"]},{"ingredientId":"greek-yogurt-0","alternatives":["soy-yogurt"]}]}'::jsonb),
  ('prawn-mango-couscous', 'Prawn & mango couscous salad', 'lunch', 1, '{"id":"prawn-mango-couscous","name":"Prawn & mango couscous salad","meal":"lunch","servings":1,"prepMinutes":10,"cookMinutes":5,"ingredients":[{"ingredientId":"shrimp-cooked","grams":150,"display":"150 g","prep":"thawed if frozen"},{"ingredientId":"couscous-dry","grams":60,"display":"⅓ cup","prep":"dry"},{"ingredientId":"mango","grams":80,"display":"½ cup","prep":"diced"},{"ingredientId":"cucumber","grams":60,"display":"¼ cucumber","prep":"diced"},{"ingredientId":"spring-onion","grams":15,"display":"1 spring onion","prep":"sliced"},{"ingredientId":"lime-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"olive-oil","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":1,"display":"mint, chilli, salt"}],"steps":["Pour 90 ml boiling water over the couscous, cover for 5 minutes and fluff with a fork.","Stir in the lime juice, oil, mint and chilli.","Fold through the mango, cucumber, spring onion and prawns."],"substitutions":[{"ingredientId":"shrimp-cooked","alternatives":["chicken-breast-cooked","tofu-firm"]},{"ingredientId":"couscous-dry","alternatives":["quinoa-cooked"]}]}'::jsonb),
  ('prawn-avocado-rye-open-sandwich', 'Prawn & avocado rye open sandwich', 'lunch', 1, '{"id":"prawn-avocado-rye-open-sandwich","name":"Prawn & avocado rye open sandwich","meal":"lunch","servings":1,"prepMinutes":7,"cookMinutes":0,"ingredients":[{"ingredientId":"shrimp-cooked","grams":130,"display":"130 g","prep":"thawed if frozen"},{"ingredientId":"rye-bread","grams":64,"display":"2 slices"},{"ingredientId":"avocado","grams":50,"display":"⅓ avocado"},{"ingredientId":"cucumber","grams":40,"display":"8 thin slices"},{"ingredientId":"lemon-juice","grams":10,"display":"2 tsp"},{"ingredientId":"spices","grams":1,"display":"dill, salt & pepper"}],"steps":["Mash the avocado with half the lemon and a pinch of salt.","Spread it on the rye and layer on the cucumber.","Pile on the prawns, squeeze over the rest of the lemon and finish with dill and pepper."],"substitutions":[{"ingredientId":"shrimp-cooked","alternatives":["smoked-salmon","chicken-breast-cooked"]},{"ingredientId":"rye-bread","alternatives":["rye-crispbread"]}]}'::jsonb),
  ('prawn-coconut-curry', 'Prawn & courgette coconut curry', 'dinner', 2, '{"id":"prawn-coconut-curry","name":"Prawn & courgette coconut curry","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":15,"ingredients":[{"ingredientId":"shrimp-cooked","grams":280,"display":"280 g","prep":"thawed if frozen"},{"ingredientId":"rice-white-dry","grams":140,"display":"¾ cup","prep":"dry"},{"ingredientId":"coconut-milk-light","grams":240,"display":"1 cup"},{"ingredientId":"zucchini","grams":200,"display":"1 courgette","prep":"diced"},{"ingredientId":"bell-pepper","grams":120,"display":"1 pepper","prep":"sliced"},{"ingredientId":"garlic","grams":6,"display":"2 cloves","prep":"crushed"},{"ingredientId":"spices","grams":4,"display":"curry paste or powder, salt"},{"ingredientId":"lime-juice","grams":15,"display":"1 tbsp"}],"steps":["Cook the rice according to the packet.","Fry the garlic and curry spices in a splash of water for 1 minute, then add the courgette and pepper.","Pour in the coconut milk and simmer for 8 minutes until the veg is tender.","Add the prawns and heat through for 2 minutes. Stir in the lime and serve with the rice."],"substitutions":[{"ingredientId":"shrimp-cooked","alternatives":["cod-raw","chicken-breast-cooked","tofu-firm"]},{"ingredientId":"rice-white-dry","alternatives":["rice-noodles-cooked"]}]}'::jsonb),
  ('spanish-prawn-pepper-rice', 'Spanish prawn & pepper rice', 'dinner', 2, '{"id":"spanish-prawn-pepper-rice","name":"Spanish prawn & pepper rice","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":25,"ingredients":[{"ingredientId":"shrimp-cooked","grams":280,"display":"280 g","prep":"thawed if frozen"},{"ingredientId":"rice-white-dry","grams":150,"display":"¾ cup","prep":"dry"},{"ingredientId":"bell-pepper","grams":150,"display":"1 large pepper","prep":"sliced"},{"ingredientId":"peas-green","grams":100,"display":"¾ cup","prep":"frozen"},{"ingredientId":"onion","grams":80,"display":"¾ onion","prep":"diced"},{"ingredientId":"tomatoes-canned","grams":200,"display":"½ can"},{"ingredientId":"vegetable-stock","grams":450,"display":"2 cups"},{"ingredientId":"spices","grams":3,"display":"smoked paprika, turmeric, salt"}],"steps":["Soften the onion and pepper in a wide pan with a splash of stock for 5 minutes.","Stir in the rice, spices and tomatoes, then pour in the stock.","Simmer without stirring for 18 minutes until the rice is tender.","Scatter over the peas and prawns, cover and heat for 3 minutes."],"substitutions":[{"ingredientId":"shrimp-cooked","alternatives":["chicken-breast-cooked","cod-raw"]},{"ingredientId":"peas-green","alternatives":["green-beans"]}]}'::jsonb),
