  ('mussel-white-bean-tomato-soup', 'Mussel, white bean & tomato soup', 'lunch', 2, '{"id":"mussel-white-bean-tomato-soup","name":"Mussel, white bean & tomato soup","meal":"lunch","servings":2,"prepMinutes":10,"cookMinutes":20,"ingredients":[{"ingredientId":"mussels-cooked","grams":250,"display":"250 g","prep":"thawed"},{"ingredientId":"white-beans-cooked","grams":120,"display":"½ can","prep":"drained"},{"ingredientId":"tomatoes-canned","grams":400,"display":"1 can (400 g)"},{"ingredientId":"vegetable-stock","grams":400,"display":"1⅔ cups"},{"ingredientId":"onion","grams":110,"display":"1 onion","prep":"diced"},{"ingredientId":"garlic","grams":6,"display":"2 cloves","prep":"crushed"},{"ingredientId":"wholewheat-bread","grams":64,"display":"2 slices","prep":"to serve"},{"ingredientId":"spices","grams":2,"display":"fennel seeds, chilli, parsley, salt"}],"steps":["Soften the onion and garlic in a splash of stock for 5 minutes.","Add the tomatoes, remaining stock, beans and spices and simmer for 10 minutes.","Stir in the mussels and simmer for 3 minutes until hot.","Serve with the bread for dipping."],"substitutions":[{"ingredientId":"mussels-cooked","alternatives":["cod-raw","saithe-raw"]},{"ingredientId":"wholewheat-bread","alternatives":["rye-bread"]}]}'::jsonb),
  ('warm-squid-chickpea-salad', 'Warm garlic squid & chickpea salad', 'lunch', 1, '{"id":"warm-squid-chickpea-salad","name":"Warm garlic squid & chickpea salad","meal":"lunch","servings":1,"prepMinutes":8,"cookMinutes":4,"ingredients":[{"ingredientId":"squid-raw","grams":200,"display":"200 g rings"},{"ingredientId":"chickpeas-cooked","grams":100,"display":"⅖ can","prep":"drained"},{"ingredientId":"rocket","grams":30,"display":"1½ cups"},{"ingredientId":"tomato","grams":120,"display":"1 tomato","prep":"chopped"},{"ingredientId":"garlic","grams":3,"display":"1 clove","prep":"sliced"},{"ingredientId":"lemon-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"olive-oil","grams":7,"display":"½ tbsp"},{"ingredientId":"spices","grams":1,"display":"paprika, parsley, salt"}],"steps":["Pat the squid dry and season with paprika and salt.","Heat the oil in a pan until very hot and fry the squid and garlic for 2–3 minutes only.","Add the chickpeas for 1 minute to warm through.","Tip over the rocket and tomato and squeeze over the lemon."],"substitutions":[{"ingredientId":"squid-raw","alternatives":["cod-raw","chicken-breast-raw"]},{"ingredientId":"chickpeas-cooked","alternatives":["white-beans-cooked"]}]}'::jsonb),
  ('mussel-potato-mustard-salad', 'Mussel & potato salad with mustard dressing', 'lunch', 1, '{"id":"mussel-potato-mustard-salad","name":"Mussel & potato salad with mustard dressing","meal":"lunch","servings":1,"prepMinutes":8,"cookMinutes":15,"ingredients":[{"ingredientId":"mussels-cooked","grams":180,"display":"180 g","prep":"thawed"},{"ingredientId":"potato-raw","grams":250,"display":"3 small potatoes","prep":"halved"},{"ingredientId":"green-beans","grams":80,"display":"¾ cup","prep":"trimmed"},{"ingredientId":"spring-onion","grams":15,"display":"1 spring onion","prep":"sliced"},{"ingredientId":"mustard","grams":10,"display":"2 tsp"},{"ingredientId":"lemon-juice","grams":10,"display":"2 tsp"},{"ingredientId":"olive-oil","grams":7,"display":"½ tbsp"},{"ingredientId":"spices","grams":1,"display":"parsley, salt & pepper"}],"steps":["Boil the potatoes for 12 minutes, adding the beans for the last 4. Drain.","Whisk the mustard, lemon, oil and parsley into a dressing.","Toss the warm potatoes and beans with the mussels, spring onion and dressing."],"substitutions":[{"ingredientId":"mussels-cooked","alternatives":["saithe-raw","chicken-breast-cooked"]},{"ingredientId":"potato-raw","alternatives":["quinoa-cooked"]}]}'::jsonb),
