  ('squid-green-bean-stir-fry', 'Ginger squid & green bean stir-fry', 'dinner', 2, '{"id":"squid-green-bean-stir-fry","name":"Ginger squid & green bean stir-fry","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":15,"ingredients":[{"ingredientId":"squid-raw","grams":360,"display":"360 g rings"},{"ingredientId":"rice-white-dry","grams":140,"display":"¾ cup","prep":"dry"},{"ingredientId":"green-beans","grams":150,"display":"1½ cups","prep":"halved"},{"ingredientId":"carrot","grams":80,"display":"1 carrot","prep":"thinly sliced"},{"ingredientId":"ginger","grams":10,"display":"2 tsp","prep":"grated"},{"ingredientId":"garlic","grams":6,"display":"2 cloves","prep":"sliced"},{"ingredientId":"soy-sauce","grams":24,"display":"1½ tbsp"},{"ingredientId":"rapeseed-oil","grams":10,"display":"2 tsp"}],"steps":["Cook the rice according to the packet.","Heat the oil in a wok and stir-fry the beans and carrot for 4 minutes.","Add the ginger, garlic and squid and stir-fry over high heat for 2–3 minutes.","Splash in the soy sauce, toss and serve over the rice."],"substitutions":[{"ingredientId":"squid-raw","alternatives":["chicken-breast-raw","tofu-firm"]},{"ingredientId":"rice-white-dry","alternatives":["rice-noodles-cooked"]}]}'::jsonb),
  ('mussel-bulgur-pilaf', 'Spiced mussel & pea bulgur pilaf', 'dinner', 2, '{"id":"mussel-bulgur-pilaf","name":"Spiced mussel & pea bulgur pilaf","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":20,"ingredients":[{"ingredientId":"mussels-cooked","grams":300,"display":"300 g","prep":"thawed"},{"ingredientId":"bulgur-dry","grams":140,"display":"1 cup","prep":"dry"},{"ingredientId":"tomatoes-canned","grams":200,"display":"½ can"},{"ingredientId":"peas-green","grams":100,"display":"¾ cup","prep":"frozen"},{"ingredientId":"onion","grams":80,"display":"¾ onion","prep":"diced"},{"ingredientId":"vegetable-stock","grams":350,"display":"1½ cups"},{"ingredientId":"olive-oil","grams":7,"display":"½ tbsp"},{"ingredientId":"spices","grams":3,"display":"cumin, cinnamon, paprika, salt"}],"steps":["Soften the onion in the oil for 4 minutes, then stir in the spices and bulgur.","Add the tomatoes and stock, cover and simmer for 12 minutes.","Stir in the peas and mussels, cover and cook for 4 minutes more until hot.","Fluff with a fork and serve."],"substitutions":[{"ingredientId":"mussels-cooked","alternatives":["chicken-breast-cooked","chickpeas-cooked"]},{"ingredientId":"bulgur-dry","alternatives":["couscous-dry","quinoa-dry"]}]}'::jsonb),
  ('greek-squid-potato-stew', 'Greek squid & potato stew', 'dinner', 4, '{"id":"greek-squid-potato-stew","name":"Greek squid & potato stew","meal":"dinner","servings":4,"prepMinutes":15,"cookMinutes":40,"ingredients":[{"ingredientId":"squid-raw","grams":750,"display":"750 g rings"},{"ingredientId":"potato-raw","grams":700,"display":"3 large potatoes","prep":"chunked"},{"ingredientId":"tomatoes-canned","grams":800,"display":"2 cans (800 g)"},{"ingredientId":"onion","grams":150,"display":"1 large onion","prep":"diced"},{"ingredientId":"garlic","grams":9,"display":"3 cloves","prep":"sliced"},{"ingredientId":"olive-oil","grams":20,"display":"1½ tbsp"},{"ingredientId":"spices","grams":4,"display":"oregano, bay leaf, cinnamon, salt"}],"steps":["Soften the onion and garlic in the oil in a large pot for 5 minutes.","Add the squid and cook for 3 minutes, then add the tomatoes, spices and 200 ml water.","Cover and simmer gently for 20 minutes.","Add the potatoes and simmer for 15–20 minutes more until tender and the squid is soft."],"substitutions":[{"ingredientId":"squid-raw","alternatives":["cod-raw","chicken-thigh-raw"]},{"ingredientId":"potato-raw","alternatives":["white-beans-cooked"]}],"notes":"Keeps 3 days in the fridge and tastes even better the next day."}'::jsonb),
  ('egg-avocado-corn-tacos', 'Scrambled egg tacos with avocado salsa', 'breakfast', 1, '{"id":"egg-avocado-corn-tacos","name":"Scrambled egg tacos with avocado salsa","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":5,"ingredients":[{"ingredientId":"egg","grams":150,"display":"3 eggs"},{"ingredientId":"egg-white","grams":66,"display":"2 egg whites"},{"ingredientId":"tortilla-corn","grams":52,"display":"2 small corn tortillas"},{"ingredientId":"avocado","grams":40,"display":"¼ avocado","prep":"diced"},{"ingredientId":"tomato","grams":60,"display":"½ tomato","prep":"diced"},{"ingredientId":"spring-onion","grams":15,"display":"1 spring onion","prep":"sliced"},{"ingredientId":"lime-juice","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":2,"display":"chilli flakes, salt & pepper"}],"steps":["Mix the avocado, tomato, spring onion and lime juice with a pinch of salt for a quick salsa.","Whisk the eggs and egg whites with salt and pepper.","Scramble in a non-stick pan over medium-low heat for 2–3 minutes until just set.","Warm the tortillas in a dry pan, fill with the eggs and top with the salsa and chilli."],"substitutions":[{"ingredientId":"egg","alternatives":["tofu-firm"]},{"ingredientId":"tortilla-corn","alternatives":["tortilla-wheat"]},{"ingredientId":"avocado","alternatives":["bell-pepper"]}]}'::jsonb),
  ('egg-white-banana-pancakes', 'Banana egg-white oat pancakes', 'breakfast', 1, '{"id":"egg-white-banana-pancakes","name":"Banana egg-white oat pancakes","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":8,"ingredients":[{"ingredientId":"egg-white","grams":165,"display":"5 egg whites"},{"ingredientId":"egg","grams":50,"display":"1 egg"},{"ingredientId":"oats-dry","grams":40,"display":"½ cup","prep":"dry"},{"ingredientId":"banana","grams":80,"display":"⅔ banana","prep":"mashed"},{"ingredientId":"rapeseed-oil","grams":3,"display":"½ tsp"},{"ingredientId":"spices","grams":1,"display":"cinnamon & a pinch of salt"},{"ingredientId":"maple-syrup","grams":10,"display":"½ tbsp","optional":true}],"steps":["Mash the banana in a bowl, then whisk in the egg, egg whites, oats and cinnamon. Rest 2 minutes.","Brush a non-stick pan with the oil and heat over medium.","Cook small pancakes for 2 minutes per side until golden and set.","Serve stacked, with a drizzle of maple syrup if you like."],"substitutions":[{"ingredientId":"egg-white","alternatives":["skyr-plain"]},{"ingredientId":"banana","alternatives":["apple","blueberries"]}]}'::jsonb),
  ('mushroom-gouda-omelette-toast', 'Mushroom & cheese omelette with toast', 'breakfast', 1, '{"id":"mushroom-gouda-omelette-toast","name":"Mushroom & cheese omelette with toast","meal":"breakfast","servings":1,"prepMinutes":3,"cookMinutes":6,"ingredients":[{"ingredientId":"egg","grams":150,"display":"3 eggs"},{"ingredientId":"egg-white","grams":66,"display":"2 egg whites"},{"ingredientId":"mushrooms","grams":80,"display":"1 cup","prep":"sliced"},{"ingredientId":"gouda","grams":20,"display":"1 slice","prep":"grated"},{"ingredientId":"spring-onion","grams":15,"display":"1 spring onion","prep":"sliced"},{"ingredientId":"butter","grams":5,"display":"1 tsp"},{"ingredientId":"wholewheat-bread","grams":32,"display":"1 slice","prep":"toasted"},{"ingredientId":"spices","grams":1,"display":"salt & pepper"}],"steps":["Melt the butter in a non-stick pan and fry the mushrooms for 3 minutes until browned. Tip onto a plate.","Whisk the eggs and egg whites with salt and pepper and pour into the pan.","Cook over medium heat, pulling the edges in, until almost set.","Scatter over the mushrooms, cheese and spring onion, fold and serve with the toast."],"substitutions":[{"ingredientId":"gouda","alternatives":["feta","mozzarella-light"]},{"ingredientId":"wholewheat-bread","alternatives":["rye-bread"]}]}'::jsonb),
  ('pepper-potato-hash-eggs', 'Pepper potato hash with fried eggs', 'breakfast', 1, '{"id":"pepper-potato-hash-eggs","name":"Pepper potato hash with fried eggs","meal":"breakfast","servings":1,"prepMinutes":8,"cookMinutes":15,"ingredients":[{"ingredientId":"potato-raw","grams":200,"display":"1 medium potato","prep":"diced small"},{"ingredientId":"egg","grams":150,"display":"3 eggs"},{"ingredientId":"egg-white","grams":66,"display":"2 egg whites"},{"ingredientId":"bell-pepper","grams":80,"display":"⅔ pepper","prep":"diced"},{"ingredientId":"onion","grams":50,"display":"½ small onion","prep":"diced"},{"ingredientId":"rapeseed-oil","grams":7,"display":"½ tbsp"},{"ingredientId":"spices","grams":2,"display":"smoked paprika, salt & pepper"}],"steps":["Microwave the diced potato in a covered bowl for 4 minutes to soften.","Fry the potato in the oil in a large pan over medium-high heat for 6 minutes until crisp.","Add the pepper, onion and paprika and fry for 3 more minutes.","Make three wells, crack in the eggs and pour the whites around them. Cover and cook for 3 minutes until set."],"substitutions":[{"ingredientId":"potato-raw","alternatives":["sweet-potato-raw"]},{"ingredientId":"egg","alternatives":["tofu-firm"]}]}'::jsonb),
  ('boiled-egg-avocado-crispbread', 'Boiled egg & avocado crispbreads', 'breakfast', 1, '{"id":"boiled-egg-avocado-crispbread","name":"Boiled egg & avocado crispbreads","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":9,"ingredients":[{"ingredientId":"egg","grams":150,"display":"3 eggs"},{"ingredientId":"rye-crispbread","grams":30,"display":"3 crispbreads"},{"ingredientId":"cottage-cheese","grams":80,"display":"⅓ cup"},{"ingredientId":"avocado","grams":50,"display":"⅓ avocado","prep":"sliced"},{"ingredientId":"cucumber","grams":60,"display":"5 cm piece","prep":"sliced"},{"ingredientId":"spices","grams":1,"display":"chilli flakes, salt & pepper"}],"steps":["Lower the eggs into boiling water and simmer for 8 minutes. Cool in cold water and peel.","Spread the cottage cheese over the crispbreads.","Top with cucumber, avocado and sliced egg.","Season with chilli flakes, salt and pepper."],"substitutions":[{"ingredientId":"cottage-cheese","alternatives":["hummus","skyr-plain"]},{"ingredientId":"rye-crispbread","alternatives":["rice-cakes","rye-bread"]}],"notes":"Boil a few extra eggs; peeled eggs keep 3 days in the fridge."}'::jsonb),
  ('baked-eggs-white-beans', 'Baked eggs with white beans & spinach', 'breakfast', 1, '{"id":"baked-eggs-white-beans","name":"Baked eggs with white beans & spinach","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":15,"ingredients":[{"ingredientId":"egg","grams":150,"display":"3 eggs"},{"ingredientId":"white-beans-cooked","grams":100,"display":"⅖ can","prep":"drained"},{"ingredientId":"spinach","grams":60,"display":"2 handfuls"},{"ingredientId":"passata","grams":100,"display":"⅖ cup"},{"ingredientId":"garlic","grams":3,"display":"1 clove","prep":"crushed"},{"ingredientId":"olive-oil","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":2,"display":"smoked paprika, salt & pepper"}],"steps":["Heat the oven to 200 °C.","Mix the passata, beans, garlic, oil and paprika in a small baking dish, then stir in the spinach.","Make three hollows and crack in the eggs. Season.","Bake for 12–15 minutes until the whites are set and the yolks still soft."],"substitutions":[{"ingredientId":"white-beans-cooked","alternatives":["chickpeas-cooked","kidney-beans-cooked"]},{"ingredientId":"spinach","alternatives":["kale"]}]}'::jsonb),
  ('egg-white-spinach-wrap', 'Egg white & spinach breakfast wrap', 'breakfast', 1, '{"id":"egg-white-spinach-wrap","name":"Egg white & spinach breakfast wrap","meal":"breakfast","servings":1,"prepMinutes":4,"cookMinutes":5,"ingredients":[{"ingredientId":"egg-white","grams":165,"display":"5 egg whites"},{"ingredientId":"egg","grams":50,"display":"1 egg"},{"ingredientId":"tortilla-wheat","grams":60,"display":"1 large tortilla"},{"ingredientId":"spinach","grams":30,"display":"1 large handful"},{"ingredientId":"tomato","grams":50,"display":"½ small tomato","prep":"diced"},{"ingredientId":"gouda","grams":15,"display":"¾ slice","prep":"grated"},{"ingredientId":"rapeseed-oil","grams":3,"display":"½ tsp"},{"ingredientId":"spices","grams":1,"display":"salt & pepper"}],"steps":["Heat the oil in a non-stick pan and wilt the spinach for 30 seconds.","Whisk the egg and egg whites, pour over the spinach and stir gently until just set.","Warm the tortilla, then fill with the eggs, tomato and cheese.","Roll up tightly and cut in half."],"substitutions":[{"ingredientId":"egg-white","alternatives":["tofu-firm"]},{"ingredientId":"tortilla-wheat","alternatives":["tortilla-corn","pita-wholewheat"]}]}'::jsonb),
  ('leek-kale-egg-bake', 'Leek, kale & potato egg bake', 'breakfast', 4, '{"id":"leek-kale-egg-bake","name":"Leek, kale & potato egg bake","meal":"breakfast","servings":4,"prepMinutes":15,"cookMinutes":30,"ingredients":[{"ingredientId":"egg","grams":500,"display":"10 eggs"},{"ingredientId":"egg-white","grams":200,"display":"6 egg whites"},{"ingredientId":"cottage-cheese","grams":200,"display":"⅞ cup"},{"ingredientId":"potato-raw","grams":400,"display":"2 medium potatoes","prep":"thinly sliced"},{"ingredientId":"leek","grams":180,"display":"2 leeks","prep":"sliced"},{"ingredientId":"kale","grams":80,"display":"4 cups","prep":"stalks removed, chopped"},{"ingredientId":"gouda","grams":60,"display":"3 slices","prep":"grated"},{"ingredientId":"olive-oil","grams":10,"display":"2 tsp"}],"steps":["Heat the oven to 190 °C and oil a large baking dish.","Microwave the potato slices for 5 minutes to soften, then spread in the dish with the leek and kale.","Whisk the eggs, egg whites and cottage cheese with salt and pepper and pour over the vegetables.","Scatter with the cheese and bake for 25–30 minutes until set and golden.","Cool for 5 minutes, then cut into 4 portions."],"substitutions":[{"ingredientId":"kale","alternatives":["spinach"]},{"ingredientId":"gouda","alternatives":["feta","parmesan"]}],"notes":"Keeps 4 days in the fridge; reheat a slice in the microwave for 1 minute."}'::jsonb),
  ('skyr-devilled-eggs', 'Skyr devilled eggs', 'snack', 1, '{"id":"skyr-devilled-eggs","name":"Skyr devilled eggs","meal":"snack","servings":1,"prepMinutes":5,"cookMinutes":9,"ingredients":[{"ingredientId":"egg","grams":100,"display":"2 eggs"},{"ingredientId":"skyr-plain","grams":30,"display":"2 tbsp"},{"ingredientId":"mustard","grams":5,"display":"1 tsp"},{"ingredientId":"cucumber","grams":80,"display":"¼ cucumber","prep":"cut into sticks"},{"ingredientId":"spices","grams":1,"display":"paprika, salt & pepper"}],"steps":["Lower the eggs into boiling water and simmer for 9 minutes. Cool in cold water and peel.","Halve the eggs and scoop the yolks into a bowl.","Mash the yolks with the skyr, mustard, salt and pepper, then spoon back into the whites.","Dust with paprika and serve with the cucumber sticks."],"substitutions":[{"ingredientId":"skyr-plain","alternatives":["greek-yogurt-0","soy-yogurt"]}]}'::jsonb),
  ('egg-white-mug-omelette', 'Microwave egg white mug omelette', 'snack', 1, '{"id":"egg-white-mug-omelette","name":"Microwave egg white mug omelette","meal":"snack","servings":1,"prepMinutes":3,"cookMinutes":2,"ingredients":[{"ingredientId":"egg-white","grams":132,"display":"4 egg whites"},{"ingredientId":"egg","grams":50,"display":"1 egg"},{"ingredientId":"spinach","grams":20,"display":"a small handful","prep":"chopped"},{"ingredientId":"tomato","grams":40,"display":"⅓ tomato","prep":"diced"},{"ingredientId":"parmesan","grams":5,"display":"1 tbsp","prep":"grated"},{"ingredientId":"spices","grams":1,"display":"dried herbs, salt & pepper"}],"steps":["Whisk the egg and egg whites in a large microwave-safe mug.","Stir in the spinach, tomato, cheese and seasoning.","Microwave for 60 seconds, stir, then cook in 20-second bursts until just set."],"substitutions":[{"ingredientId":"parmesan","alternatives":["gouda","feta"]},{"ingredientId":"spinach","alternatives":["bell-pepper"]}]}'::jsonb),
  ('egg-ham-open-rye', 'Egg & ham open rye sandwiches', 'lunch', 1, '{"id":"egg-ham-open-rye","name":"Egg & ham open rye sandwiches","meal":"lunch","servings":1,"prepMinutes":5,"cookMinutes":9,"ingredients":[{"ingredientId":"egg","grams":150,"display":"3 eggs"},{"ingredientId":"ham-sliced","grams":60,"display":"4 slices"},{"ingredientId":"rye-bread","grams":64,"display":"2 slices"},{"ingredientId":"lettuce","grams":30,"display":"2 leaves"},{"ingredientId":"tomato","grams":60,"display":"½ tomato","prep":"sliced"},{"ingredientId":"mustard","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":1,"display":"cress or chives, salt & pepper"}],"steps":["Lower the eggs into boiling water and simmer for 9 minutes. Cool in cold water, peel and slice.","Spread the rye bread thinly with mustard.","Layer with lettuce, ham, tomato and sliced egg.","Season with pepper and top with herbs."],"substitutions":[{"ingredientId":"ham-sliced","alternatives":["smoked-salmon","cottage-cheese"]},{"ingredientId":"rye-bread","alternatives":["wholewheat-bread","rye-crispbread"]}]}'::jsonb),
  ('veggie-egg-fried-rice', 'Veggie egg fried rice with peas', 'lunch', 1, '{"id":"veggie-egg-fried-rice","name":"Veggie egg fried rice with peas","meal":"lunch","servings":1,"prepMinutes":5,"cookMinutes":8,"ingredients":[{"ingredientId":"rice-white-cooked","grams":200,"display":"1¼ cups","prep":"cold, cooked"},{"ingredientId":"egg","grams":150,"display":"3 eggs"},{"ingredientId":"egg-white","grams":66,"display":"2 egg whites"},{"ingredientId":"peas-green","grams":80,"display":"½ cup","prep":"frozen"},{"ingredientId":"spring-onion","grams":20,"display":"1–2 spring onions","prep":"sliced"},{"ingredientId":"soy-sauce","grams":10,"display":"2 tsp"},{"ingredientId":"sesame-oil","grams":5,"display":"1 tsp"}],"steps":["Heat the sesame oil in a wok or large pan over high heat.","Add the eggs and whites and stir-fry for 1 minute until softly scrambled.","Add the rice and peas and fry for 4–5 minutes, breaking up any clumps.","Stir through the soy sauce and spring onion and serve hot."],"substitutions":[{"ingredientId":"egg","alternatives":["tofu-firm"]},{"ingredientId":"rice-white-cooked","alternatives":["quinoa-cooked"]},{"ingredientId":"peas-green","alternatives":["edamame","sweetcorn-canned"]}],"notes":"Day-old rice fries best."}'::jsonb),
  ('nordic-egg-potato-salad', 'Nordic egg & potato salad', 'lunch', 1, '{"id":"nordic-egg-potato-salad","name":"Nordic egg & potato salad","meal":"lunch","servings":1,"prepMinutes":10,"cookMinutes":15,"ingredients":[{"ingredientId":"potato-raw","grams":250,"display":"2 small potatoes","prep":"cubed"},{"ingredientId":"egg","grams":150,"display":"3 eggs"},{"ingredientId":"skyr-plain","grams":60,"display":"¼ cup"},{"ingredientId":"cucumber","grams":80,"display":"¼ cucumber","prep":"diced"},{"ingredientId":"spring-onion","grams":15,"display":"1 spring onion","prep":"sliced"},{"ingredientId":"mustard","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":1,"display":"dill, salt & pepper"}],"steps":["Simmer the potatoes in salted water for 12–15 minutes until tender, adding the eggs for the last 9 minutes.","Drain, cool the eggs in cold water, peel and quarter.","Mix the skyr, mustard, dill, salt and pepper.","Toss the potatoes, cucumber and spring onion in the dressing and top with the eggs."],"substitutions":[{"ingredientId":"skyr-plain","alternatives":["greek-yogurt-0","soy-yogurt"]},{"ingredientId":"potato-raw","alternatives":["sweet-potato-raw"]}],"notes":"Packs well for lunch; keeps 2 days in the fridge."}'::jsonb),
  ('spinach-feta-frittata', 'Spinach & feta potato frittata', 'dinner', 2, '{"id":"spinach-feta-frittata","name":"Spinach & feta potato frittata","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":20,"ingredients":[{"ingredientId":"egg","grams":300,"display":"6 eggs"},{"ingredientId":"feta","grams":130,"display":"130 g","prep":"crumbled"},{"ingredientId":"potato-raw","grams":300,"display":"2 medium potatoes","prep":"thinly sliced"},{"ingredientId":"spinach","grams":120,"display":"4 handfuls"},{"ingredientId":"onion","grams":80,"display":"1 small onion","prep":"sliced"},{"ingredientId":"olive-oil","grams":10,"display":"2 tsp"},{"ingredientId":"spices","grams":2,"display":"oregano, salt & pepper"}],"steps":["Heat the oil in an ovenproof pan and cook the potato and onion, covered, over medium heat for 10 minutes until tender.","Stir in the spinach until wilted.","Whisk the eggs with oregano and pepper, pour over and scatter with the feta.","Cook for 4 minutes until the base sets, then finish under a hot grill for 4–5 minutes until puffed and golden."],"substitutions":[{"ingredientId":"feta","alternatives":["gouda","cottage-cheese"]},{"ingredientId":"spinach","alternatives":["kale"]}]}'::jsonb),
  ('ham-pea-carbonara', 'Ham & pea carbonara', 'dinner', 2, '{"id":"ham-pea-carbonara","name":"Ham & pea carbonara","meal":"dinner","servings":2,"prepMinutes":5,"cookMinutes":12,"ingredients":[{"ingredientId":"pasta-dry","grams":150,"display":"150 g","prep":"spaghetti or penne"},{"ingredientId":"egg","grams":200,"display":"4 eggs"},{"ingredientId":"ham-sliced","grams":120,"display":"8 slices","prep":"cut into strips"},{"ingredientId":"parmesan","grams":20,"display":"4 tbsp","prep":"finely grated"},{"ingredientId":"peas-green","grams":100,"display":"¾ cup","prep":"frozen"},{"ingredientId":"spices","grams":2,"display":"plenty of black pepper"}],"steps":["Cook the pasta in salted boiling water, adding the peas for the last 2 minutes. Keep a mug of the water.","Whisk the eggs with the cheese and lots of black pepper.","Fry the ham strips in a large dry pan for 2 minutes.","Take the pan off the heat, add the drained pasta and peas, then stir in the egg mix with a splash of pasta water until creamy, not scrambled."],"substitutions":[{"ingredientId":"ham-sliced","alternatives":["mushrooms","smoked-salmon"]},{"ingredientId":"pasta-dry","alternatives":["egg-noodles-dry"]}]}'::jsonb),
  ('egg-curry-coconut-rice', 'Coconut egg curry with rice', 'dinner', 2, '{"id":"egg-curry-coconut-rice","name":"Coconut egg curry with rice","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":20,"ingredients":[{"ingredientId":"egg","grams":400,"display":"8 eggs"},{"ingredientId":"rice-white-dry","grams":120,"display":"⅔ cup","prep":"dry"},{"ingredientId":"coconut-milk-light","grams":200,"display":"½ can"},{"ingredientId":"tomatoes-canned","grams":200,"display":"½ can"},{"ingredientId":"onion","grams":100,"display":"1 onion","prep":"diced"},{"ingredientId":"ginger","grams":6,"display":"1 tbsp","prep":"grated"},{"ingredientId":"peas-green","grams":100,"display":"¾ cup","prep":"frozen"},{"ingredientId":"spices","grams":4,"display":"curry powder, turmeric & salt"}],"steps":["Cook the rice following the pack. Boil the eggs for 9 minutes, cool in cold water and peel.","Soften the onion and ginger in a splash of water in a deep pan for 5 minutes, then stir in the spices for 1 minute.","Add the tomatoes and coconut milk and simmer for 8 minutes.","Add the peas and halved eggs and simmer for 3 minutes more. Serve over the rice."],"substitutions":[{"ingredientId":"egg","alternatives":["chickpeas-cooked","tofu-firm"]},{"ingredientId":"rice-white-dry","alternatives":["quinoa-dry"]}]}'::jsonb),
  ('egg-noodle-veg-stir-fry', 'Egg & broccoli noodle stir-fry', 'dinner', 2, '{"id":"egg-noodle-veg-stir-fry","name":"Egg & broccoli noodle stir-fry","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":10,"ingredients":[{"ingredientId":"egg-noodles-dry","grams":120,"display":"2 nests"},{"ingredientId":"egg","grams":200,"display":"4 eggs"},{"ingredientId":"egg-white","grams":132,"display":"4 egg whites"},{"ingredientId":"broccoli","grams":150,"display":"1½ cups","prep":"small florets"},{"ingredientId":"bell-pepper","grams":100,"display":"1 small pepper","prep":"sliced"},{"ingredientId":"soy-sauce","grams":20,"display":"1 tbsp"},{"ingredientId":"ginger","grams":6,"display":"1 tbsp","prep":"grated"},{"ingredientId":"sesame-oil","grams":8,"display":"2 tsp"}],"steps":["Cook the noodles following the pack, drain and rinse briefly.","Heat half the oil in a wok and scramble the eggs and whites until just set. Tip out.","Add the rest of the oil and stir-fry the broccoli, pepper and ginger for 4 minutes.","Add the noodles, eggs and soy sauce and toss over high heat for 1 minute."],"substitutions":[{"ingredientId":"egg-noodles-dry","alternatives":["rice-noodles-cooked"]},{"ingredientId":"egg","alternatives":["tofu-firm"]},{"ingredientId":"broccoli","alternatives":["green-beans","cabbage"]}]}'::jsonb),
  ('turkish-eggs-garlic-yogurt', 'Turkish poached eggs with garlic yogurt', 'dinner', 1, '{"id":"turkish-eggs-garlic-yogurt","name":"Turkish poached eggs with garlic yogurt","meal":"dinner","servings":1,"prepMinutes":5,"cookMinutes":6,"ingredients":[{"ingredientId":"egg","grams":150,"display":"3 eggs"},{"ingredientId":"greek-yogurt-0","grams":150,"display":"⅔ cup"},{"ingredientId":"garlic","grams":3,"display":"1 small clove","prep":"grated"},{"ingredientId":"butter","grams":7,"display":"½ tbsp"},{"ingredientId":"pita-wholewheat","grams":64,"display":"1 pitta","prep":"warmed"},{"ingredientId":"spinach","grams":30,"display":"1 large handful"},{"ingredientId":"spices","grams":2,"display":"chilli flakes, paprika & salt"}],"steps":["Stir the garlic and a pinch of salt into the yogurt and spread over a plate.","Poach the eggs in gently simmering water for 3 minutes.","Melt the butter with the chilli and paprika until it sizzles.","Set the spinach and eggs on the yogurt, spoon over the chilli butter and serve with the pitta."],"substitutions":[{"ingredientId":"greek-yogurt-0","alternatives":["skyr-plain","soy-yogurt"]},{"ingredientId":"pita-wholewheat","alternatives":["rye-bread"]}]}'::jsonb),
  ('courgette-potato-tortilla', 'Courgette & potato Spanish tortilla', 'dinner', 4, '{"id":"courgette-potato-tortilla","name":"Courgette & potato Spanish tortilla","meal":"dinner","servings":4,"prepMinutes":15,"cookMinutes":25,"ingredients":[{"ingredientId":"egg","grams":700,"display":"14 eggs"},{"ingredientId":"egg-white","grams":200,"display":"6 egg whites"},{"ingredientId":"potato-raw","grams":600,"display":"3 medium potatoes","prep":"thinly sliced"},{"ingredientId":"zucchini","grams":250,"display":"1 large courgette","prep":"diced"},{"ingredientId":"onion","grams":150,"display":"1 large onion","prep":"sliced"},{"ingredientId":"olive-oil","grams":30,"display":"2 tbsp"},{"ingredientId":"spices","grams":3,"display":"salt & pepper"}],"steps":["Fry the potato and onion in the oil in a large non-stick pan, covered, over medium heat for 12 minutes until soft.","Add the courgette and cook for 3 minutes more.","Whisk the eggs and whites with salt and pepper, pour into the pan and stir once.","Cook gently for 8 minutes until almost set, then flip onto a plate and slide back to cook the top for 2 minutes.","Cut into 4 wedges. Good warm or cold."],"substitutions":[{"ingredientId":"zucchini","alternatives":["bell-pepper","spinach"]},{"ingredientId":"potato-raw","alternatives":["sweet-potato-raw"]}],"notes":"Keeps 3 days in the fridge; serve with a green salad."}'::jsonb),
  ('lemon-ricotta-pancakes', 'Lemon ricotta pancakes with raspberries', 'breakfast', 1, '{"id":"lemon-ricotta-pancakes","name":"Lemon ricotta pancakes with raspberries","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":8,"ingredients":[{"ingredientId":"ricotta","grams":120,"display":"½ cup"},{"ingredientId":"egg","grams":100,"display":"2 eggs"},{"ingredientId":"oats-dry","grams":35,"display":"⅓ cup","prep":"finely ground"},{"ingredientId":"greek-yogurt-0","grams":80,"display":"⅓ cup","prep":"to serve"},{"ingredientId":"raspberries","grams":80,"display":"⅔ cup"},{"ingredientId":"lemon-juice","grams":10,"display":"2 tsp","prep":"plus a little zest"},{"ingredientId":"butter","grams":5,"display":"1 tsp"}],"steps":["Whisk the ricotta, eggs, ground oats and lemon juice into a thick batter.","Melt the butter in a non-stick pan over medium heat.","Cook spoonfuls of batter for 2–3 minutes per side until golden.","Serve with the yogurt and raspberries."],"substitutions":[{"ingredientId":"ricotta","alternatives":["cottage-cheese"]},{"ingredientId":"raspberries","alternatives":["blueberries","strawberries"]}]}'::jsonb),
  ('mango-skyr-lassi', 'Mango skyr lassi', 'breakfast', 1, '{"id":"mango-skyr-lassi","name":"Mango skyr lassi","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"skyr-plain","grams":300,"display":"1¼ cups"},{"ingredientId":"mango","grams":120,"display":"¾ cup","prep":"frozen chunks"},{"ingredientId":"milk","grams":100,"display":"⅖ cup"},{"ingredientId":"chia-seeds","grams":10,"display":"1 tbsp"},{"ingredientId":"spices","grams":1,"display":"pinch of cardamom"}],"steps":["Put the skyr, mango, milk and cardamom in a blender.","Blend until smooth, adding a splash more milk if it is too thick.","Pour into a glass and stir in the chia seeds."],"substitutions":[{"ingredientId":"skyr-plain","alternatives":["greek-yogurt-0","soy-yogurt"]},{"ingredientId":"milk","alternatives":["soy-drink"]},{"ingredientId":"mango","alternatives":["strawberries","banana"]}]}'::jsonb),
  ('apple-baked-skyr-oats', 'Apple cinnamon baked skyr oats', 'breakfast', 1, '{"id":"apple-baked-skyr-oats","name":"Apple cinnamon baked skyr oats","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":25,"ingredients":[{"ingredientId":"skyr-plain","grams":200,"display":"¾ cup"},{"ingredientId":"oats-dry","grams":45,"display":"½ cup","prep":"dry"},{"ingredientId":"egg","grams":50,"display":"1 egg"},{"ingredientId":"apple","grams":100,"display":"½ apple","prep":"grated"},{"ingredientId":"raisins","grams":15,"display":"1½ tbsp"},{"ingredientId":"spices","grams":1,"display":"cinnamon & ½ tsp baking powder"}],"steps":["Heat the oven to 180 °C.","Mix the skyr, oats, egg, apple, raisins, cinnamon and baking powder in a small ovenproof dish.","Bake for 22–25 minutes until risen and set in the middle.","Cool for a few minutes before eating."],"substitutions":[{"ingredientId":"skyr-plain","alternatives":["greek-yogurt-0","soy-yogurt"]},{"ingredientId":"apple","alternatives":["banana","blueberries"]}],"notes":"Mix the night before and bake in the morning."}'::jsonb),
  ('cottage-spinach-quesadilla', 'Cottage cheese & spinach breakfast quesadilla', 'breakfast', 1, '{"id":"cottage-spinach-quesadilla","name":"Cottage cheese & spinach breakfast quesadilla","meal":"breakfast","servings":1,"prepMinutes":4,"cookMinutes":6,"ingredients":[{"ingredientId":"tortilla-wheat","grams":60,"display":"1 large tortilla"},{"ingredientId":"cottage-cheese","grams":150,"display":"⅔ cup","prep":"drained"},{"ingredientId":"mozzarella-light","grams":50,"display":"50 g","prep":"grated"},{"ingredientId":"spinach","grams":40,"display":"1 large handful","prep":"chopped"},{"ingredientId":"spring-onion","grams":15,"display":"1 spring onion","prep":"sliced"},{"ingredientId":"spices","grams":1,"display":"chilli flakes & black pepper"}],"steps":["Mix the cottage cheese, mozzarella, spinach, spring onion and chilli.","Spread over half the tortilla and fold over.","Toast in a dry pan over medium heat for 3 minutes per side until crisp and melted.","Cut into wedges."],"substitutions":[{"ingredientId":"mozzarella-light","alternatives":["gouda"]},{"ingredientId":"tortilla-wheat","alternatives":["tortilla-corn"]}]}'::jsonb),
  ('blueberry-ricotta-oat-muffins', 'Blueberry ricotta oat muffins', 'breakfast', 4, '{"id":"blueberry-ricotta-oat-muffins","name":"Blueberry ricotta oat muffins","meal":"breakfast","servings":4,"prepMinutes":10,"cookMinutes":22,"ingredients":[{"ingredientId":"oats-dry","grams":160,"display":"2 cups","prep":"blitzed to a flour"},{"ingredientId":"ricotta","grams":300,"display":"1¼ cups"},{"ingredientId":"skyr-plain","grams":200,"display":"¾ cup"},{"ingredientId":"egg","grams":100,"display":"2 eggs"},{"ingredientId":"apple","grams":150,"display":"1 small apple","prep":"grated"},{"ingredientId":"blueberries","grams":150,"display":"1 cup"},{"ingredientId":"spices","grams":4,"display":"2 tsp baking powder & cinnamon"},{"ingredientId":"maple-syrup","grams":30,"display":"1½ tbsp","optional":true}],"steps":["Heat the oven to 180 °C and line an 8-hole muffin tin.","Mix the oat flour, baking powder and cinnamon in a bowl.","Whisk the ricotta, skyr, eggs, apple and maple syrup, then fold into the dry mix with the blueberries.","Divide between the cases and bake for 20–22 minutes until golden and springy."],"substitutions":[{"ingredientId":"ricotta","alternatives":["cottage-cheese"]},{"ingredientId":"blueberries","alternatives":["raspberries"]},{"ingredientId":"apple","alternatives":["banana"]}],"notes":"Two muffins per serving. Keeps 3 days in the fridge or 1 month frozen."}'::jsonb),
  ('tzatziki-veg-sticks', 'Tzatziki with veg sticks', 'snack', 1, '{"id":"tzatziki-veg-sticks","name":"Tzatziki with veg sticks","meal":"snack","servings":1,"prepMinutes":7,"cookMinutes":0,"ingredients":[{"ingredientId":"greek-yogurt-0","grams":200,"display":"⅞ cup"},{"ingredientId":"cucumber","grams":100,"display":"⅓ cucumber","prep":"half grated, half in sticks"},{"ingredientId":"carrot","grams":80,"display":"1 carrot","prep":"cut into sticks"},{"ingredientId":"bell-pepper","grams":60,"display":"½ pepper","prep":"cut into strips"},{"ingredientId":"garlic","grams":3,"display":"1 small clove","prep":"grated"},{"ingredientId":"lemon-juice","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":1,"display":"dill or mint, salt"}],"steps":["Squeeze the grated cucumber in your hands to remove excess water.","Stir it into the yogurt with the garlic, lemon juice, herbs and salt.","Serve with the carrot, pepper and cucumber sticks for dipping."],"substitutions":[{"ingredientId":"greek-yogurt-0","alternatives":["skyr-plain","soy-yogurt"]},{"ingredientId":"carrot","alternatives":["zucchini"]}]}'::jsonb),
  ('caprese-snack-plate', 'Caprese snack plate with rocket', 'snack', 1, '{"id":"caprese-snack-plate","name":"Caprese snack plate with rocket","meal":"snack","servings":1,"prepMinutes":4,"cookMinutes":0,"ingredients":[{"ingredientId":"mozzarella-light","grams":60,"display":"½ ball","prep":"sliced"},{"ingredientId":"tomato","grams":120,"display":"1 tomato","prep":"sliced"},{"ingredientId":"rocket","grams":15,"display":"1 small handful"},{"ingredientId":"olive-oil","grams":3,"display":"½ tsp"},{"ingredientId":"spices","grams":1,"display":"basil, salt & pepper"}],"steps":["Arrange the tomato and mozzarella slices on a plate, overlapping.","Scatter over the rocket and basil.","Drizzle with the oil and season with salt and pepper."],"substitutions":[{"ingredientId":"mozzarella-light","alternatives":["feta","tofu-firm"]},{"ingredientId":"rocket","alternatives":["spinach"]}]}'::jsonb),
  ('chocolate-cottage-mousse', 'Chocolate cottage cheese mousse', 'snack', 1, '{"id":"chocolate-cottage-mousse","name":"Chocolate cottage cheese mousse","meal":"snack","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"cottage-cheese","grams":150,"display":"⅔ cup"},{"ingredientId":"cocoa-powder","grams":6,"display":"1 tbsp"},{"ingredientId":"maple-syrup","grams":10,"display":"½ tbsp"},{"ingredientId":"strawberries","grams":80,"display":"½ cup","prep":"sliced"}],"steps":["Blend the cottage cheese, cocoa and maple syrup until completely smooth.","Spoon into a glass and chill for 10 minutes if you have time.","Top with the strawberries."],"substitutions":[{"ingredientId":"cottage-cheese","alternatives":["skyr-plain","soy-yogurt"]},{"ingredientId":"strawberries","alternatives":["raspberries","banana"]}]}'::jsonb),
  ('greek-quinoa-cottage-salad', 'Greek quinoa & cottage cheese salad', 'lunch', 1, '{"id":"greek-quinoa-cottage-salad","name":"Greek quinoa & cottage cheese salad","meal":"lunch","servings":1,"prepMinutes":10,"cookMinutes":0,"ingredients":[{"ingredientId":"quinoa-cooked","grams":150,"display":"⅘ cup","prep":"cooked, cooled"},{"ingredientId":"cottage-cheese","grams":200,"display":"⅞ cup"},{"ingredientId":"feta","grams":30,"display":"30 g","prep":"crumbled"},{"ingredientId":"cucumber","grams":80,"display":"¼ cucumber","prep":"diced"},{"ingredientId":"tomato","grams":80,"display":"⅔ tomato","prep":"diced"},{"ingredientId":"olive-oil","grams":5,"display":"1 tsp"},{"ingredientId":"lemon-juice","grams":10,"display":"2 tsp"},{"ingredientId":"spices","grams":1,"display":"oregano, salt & pepper"}],"steps":["Toss the quinoa with the cucumber, tomato, oil, lemon juice and oregano.","Season with salt and pepper.","Top with spoonfuls of cottage cheese and the crumbled feta."],"substitutions":[{"ingredientId":"cottage-cheese","alternatives":["chickpeas-cooked","skyr-plain"]},{"ingredientId":"quinoa-cooked","alternatives":["rice-white-cooked"]}],"notes":"Keep the cottage cheese separate if packing it for later."}'::jsonb),
  ('caprese-toastie', 'Mozzarella & tomato toastie', 'lunch', 1, '{"id":"caprese-toastie","name":"Mozzarella & tomato toastie","meal":"lunch","servings":1,"prepMinutes":5,"cookMinutes":5,"ingredients":[{"ingredientId":"wholewheat-bread","grams":80,"display":"2 large slices"},{"ingredientId":"mozzarella-light","grams":80,"display":"⅔ ball","prep":"sliced"},{"ingredientId":"tomato","grams":60,"display":"½ tomato","prep":"sliced"},{"ingredientId":"spinach","grams":20,"display":"a small handful"},{"ingredientId":"olive-oil","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":1,"display":"dried basil & black pepper"}],"steps":["Brush the outsides of the bread with the oil.","Fill with mozzarella, tomato, spinach, basil and pepper.","Toast in a pan over medium heat, pressing down, for 2–3 minutes per side until golden and melted."],"substitutions":[{"ingredientId":"mozzarella-light","alternatives":["gouda","ham-sliced"]},{"ingredientId":"wholewheat-bread","alternatives":["rye-bread"]}]}'::jsonb),
  ('spinach-ricotta-pasta-bake', 'Spinach & ricotta pasta bake', 'dinner', 4, '{"id":"spinach-ricotta-pasta-bake","name":"Spinach & ricotta pasta bake","meal":"dinner","servings":4,"prepMinutes":15,"cookMinutes":30,"ingredients":[{"ingredientId":"pasta-dry","grams":300,"display":"300 g","prep":"penne or rigatoni"},{"ingredientId":"ricotta","grams":400,"display":"1¾ cups"},{"ingredientId":"passata","grams":500,"display":"2 cups"},{"ingredientId":"spinach","grams":150,"display":"5 handfuls"},{"ingredientId":"mozzarella-light","grams":125,"display":"1 ball","prep":"torn"},{"ingredientId":"parmesan","grams":30,"display":"6 tbsp","prep":"grated"},{"ingredientId":"garlic","grams":6,"display":"2 cloves","prep":"crushed"},{"ingredientId":"spices","grams":2,"display":"oregano, salt & pepper"}],"steps":["Heat the oven to 200 °C. Cook the pasta for 2 minutes less than the pack says and drain.","Stir the garlic and oregano into the passata. Mix the ricotta with half the parmesan and the spinach.","Toss the pasta with the passata and the ricotta mix, then tip into a baking dish.","Top with mozzarella and the rest of the parmesan and bake for 20 minutes until bubbling."],"substitutions":[{"ingredientId":"ricotta","alternatives":["cottage-cheese"]},{"ingredientId":"mozzarella-light","alternatives":["gouda"]}],"notes":"Keeps 4 days in the fridge; reheat portions covered."}'::jsonb),
  ('leek-cheese-potato-gratin', 'Leek & cheese potato gratin', 'dinner', 2, '{"id":"leek-cheese-potato-gratin","name":"Leek & cheese potato gratin","meal":"dinner","servings":2,"prepMinutes":15,"cookMinutes":40,"ingredients":[{"ingredientId":"potato-raw","grams":500,"display":"2–3 large potatoes","prep":"thinly sliced"},{"ingredientId":"leek","grams":200,"display":"2 leeks","prep":"sliced"},{"ingredientId":"cottage-cheese","grams":200,"display":"⅞ cup"},{"ingredientId":"gouda","grams":100,"display":"5 slices","prep":"grated"},{"ingredientId":"milk","grams":200,"display":"⅘ cup"},{"ingredientId":"spices","grams":2,"display":"nutmeg, thyme, salt & pepper"},{"ingredientId":"broccoli","grams":200,"display":"2 cups","prep":"florets, to serve","optional":true}],"steps":["Heat the oven to 190 °C.","Whisk the cottage cheese, milk, nutmeg, thyme, salt and pepper.","Layer the potato and leek in a baking dish, pouring a little of the milk mix over each layer.","Top with the cheese, cover with foil and bake for 25 minutes, then uncover and bake 15 minutes until golden.","Serve with steamed broccoli if you like."],"substitutions":[{"ingredientId":"gouda","alternatives":["mozzarella-light","parmesan"]},{"ingredientId":"potato-raw","alternatives":["sweet-potato-raw"]}]}'::jsonb),
  ('aubergine-ricotta-parmigiana', 'Aubergine parmigiana with ricotta', 'dinner', 2, '{"id":"aubergine-ricotta-parmigiana","name":"Aubergine parmigiana with ricotta","meal":"dinner","servings":2,"prepMinutes":15,"cookMinutes":35,"ingredients":[{"ingredientId":"aubergine","grams":450,"display":"1 large aubergine","prep":"sliced 1 cm thick"},{"ingredientId":"passata","grams":300,"display":"1¼ cups"},{"ingredientId":"ricotta","grams":150,"display":"⅔ cup"},{"ingredientId":"mozzarella-light","grams":125,"display":"1 ball","prep":"torn"},{"ingredientId":"parmesan","grams":25,"display":"5 tbsp","prep":"grated"},{"ingredientId":"olive-oil","grams":15,"display":"1 tbsp"},{"ingredientId":"garlic","grams":3,"display":"1 clove","prep":"crushed"},{"ingredientId":"spices","grams":2,"display":"basil, oregano, salt & pepper"}],"steps":["Heat the oven to 210 °C. Brush the aubergine with the oil and roast on a tray for 15 minutes.","Stir the garlic, herbs and seasoning into the passata.","Layer aubergine, passata and spoonfuls of ricotta in a baking dish, finishing with passata.","Top with mozzarella and parmesan and bake for 20 minutes until bubbling."],"substitutions":[{"ingredientId":"ricotta","alternatives":["cottage-cheese"]},{"ingredientId":"aubergine","alternatives":["zucchini"]}],"notes":"Serve with a green salad or crusty bread."}'::jsonb),
  ('pea-parmesan-cottage-risotto', 'Pea & parmesan risotto', 'dinner', 2, '{"id":"pea-parmesan-cottage-risotto","name":"Pea & parmesan risotto","meal":"dinner","servings":2,"prepMinutes":5,"cookMinutes":22,"ingredients":[{"ingredientId":"rice-white-dry","grams":140,"display":"¾ cup","prep":"risotto rice"},{"ingredientId":"cottage-cheese","grams":300,"display":"1⅓ cups"},{"ingredientId":"parmesan","grams":30,"display":"6 tbsp","prep":"grated"},{"ingredientId":"peas-green","grams":150,"display":"1 cup","prep":"frozen"},{"ingredientId":"onion","grams":80,"display":"1 small onion","prep":"finely diced"},{"ingredientId":"vegetable-stock","grams":600,"display":"2½ cups","prep":"hot"},{"ingredientId":"olive-oil","grams":10,"display":"2 tsp"},{"ingredientId":"spices","grams":1,"display":"black pepper"}],"steps":["Soften the onion in the oil in a wide pan for 4 minutes, then stir in the rice for 1 minute.","Add the stock a ladle at a time, stirring, and simmer for 18 minutes until the rice is just tender.","Stir in the peas for the last 3 minutes.","Off the heat, stir in the cottage cheese and parmesan until creamy. Season with pepper."],"substitutions":[{"ingredientId":"cottage-cheese","alternatives":["ricotta"]},{"ingredientId":"peas-green","alternatives":["spinach","mushrooms"]}]}'::jsonb),
  ('baked-feta-pepper-couscous', 'Baked feta with peppers & couscous', 'dinner', 2, '{"id":"baked-feta-pepper-couscous","name":"Baked feta with peppers & couscous","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":25,"ingredients":[{"ingredientId":"feta","grams":200,"display":"200 g block"},{"ingredientId":"couscous-dry","grams":120,"display":"⅔ cup","prep":"dry"},{"ingredientId":"bell-pepper","grams":200,"display":"2 peppers","prep":"chopped"},{"ingredientId":"tomato","grams":200,"display":"2 tomatoes","prep":"quartered"},{"ingredientId":"greek-yogurt-0","grams":150,"display":"⅔ cup"},{"ingredientId":"olive-oil","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":2,"display":"oregano, chilli flakes & pepper"}],"steps":["Heat the oven to 200 °C. Toss the peppers and tomatoes with the oil and oregano in a baking dish.","Set the feta in the middle, sprinkle with chilli and bake for 25 minutes.","Meanwhile pour 180 ml boiling water over the couscous, cover for 5 minutes and fluff with a fork.","Break up the feta into the vegetables and serve over the couscous with a spoonful of yogurt."],"substitutions":[{"ingredientId":"feta","alternatives":["tofu-firm","mozzarella-light"]},{"ingredientId":"couscous-dry","alternatives":["bulgur-dry","quinoa-dry"]}]}'::jsonb),
  ('banana-protein-porridge', 'Banana protein porridge', 'breakfast', 1, '{"id":"banana-protein-porridge","name":"Banana protein porridge","meal":"breakfast","servings":1,"prepMinutes":2,"cookMinutes":5,"ingredients":[{"ingredientId":"oats-dry","grams":50,"display":"½ cup","prep":"dry"},{"ingredientId":"milk","grams":200,"display":"⅘ cup"},{"ingredientId":"whey-protein","grams":25,"display":"1 scoop"},{"ingredientId":"banana","grams":60,"display":"½ banana","prep":"sliced"},{"ingredientId":"spices","grams":1,"display":"cinnamon & a pinch of salt"}],"steps":["Simmer the oats and milk in a small pan for 4–5 minutes, stirring, until creamy.","Take off the heat and stir in the protein powder with a splash of water until smooth.","Top with banana and cinnamon."],"substitutions":[{"ingredientId":"whey-protein","alternatives":["pea-protein","skyr-plain"]},{"ingredientId":"milk","alternatives":["soy-drink"]}],"notes":"Stir the powder in off the heat so it does not go lumpy."}'::jsonb),
  ('blender-protein-pancakes', 'Blender banana protein pancakes', 'breakfast', 1, '{"id":"blender-protein-pancakes","name":"Blender banana protein pancakes","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":8,"ingredients":[{"ingredientId":"whey-protein","grams":30,"display":"1 heaped scoop"},{"ingredientId":"egg","grams":100,"display":"2 eggs"},{"ingredientId":"oats-dry","grams":30,"display":"⅓ cup","prep":"dry"},{"ingredientId":"banana","grams":80,"display":"⅔ banana"},{"ingredientId":"raspberries","grams":60,"display":"½ cup","prep":"to serve"},{"ingredientId":"rapeseed-oil","grams":4,"display":"1 tsp"}],"steps":["Blend the protein powder, eggs, oats and banana until smooth. Rest for 2 minutes.","Heat the oil in a non-stick pan over medium-low heat.","Cook small pancakes for about 90 seconds per side; they brown quickly.","Serve topped with raspberries."],"substitutions":[{"ingredientId":"whey-protein","alternatives":["pea-protein"]},{"ingredientId":"raspberries","alternatives":["blueberries","strawberries"]}]}'::jsonb),
  ('chocolate-peanut-protein-smoothie', 'Chocolate peanut protein smoothie', 'breakfast', 1, '{"id":"chocolate-peanut-protein-smoothie","name":"Chocolate peanut protein smoothie","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"whey-protein","grams":30,"display":"1 heaped scoop"},{"ingredientId":"milk","grams":250,"display":"1 cup"},{"ingredientId":"banana","grams":100,"display":"1 small banana","prep":"frozen"},{"ingredientId":"peanut-butter","grams":16,"display":"1 tbsp"},{"ingredientId":"cocoa-powder","grams":5,"display":"1 tbsp"}],"steps":["Put everything in a blender with a few ice cubes.","Blend for 30–45 seconds until thick and smooth.","Pour into a glass and drink straight away."],"substitutions":[{"ingredientId":"whey-protein","alternatives":["pea-protein"]},{"ingredientId":"milk","alternatives":["soy-drink"]},{"ingredientId":"peanut-butter","alternatives":["almonds"]}]}'::jsonb),
  ('protein-french-toast', 'Protein French toast with strawberries', 'breakfast', 1, '{"id":"protein-french-toast","name":"Protein French toast with strawberries","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":6,"ingredients":[{"ingredientId":"wholewheat-bread","grams":96,"display":"3 slices"},{"ingredientId":"whey-protein","grams":25,"display":"1 scoop"},{"ingredientId":"egg","grams":50,"display":"1 egg"},{"ingredientId":"egg-white","grams":66,"display":"2 egg whites"},{"ingredientId":"milk","grams":60,"display":"¼ cup"},{"ingredientId":"strawberries","grams":100,"display":"⅔ cup","prep":"sliced"},{"ingredientId":"butter","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":1,"display":"cinnamon"}],"steps":["Whisk the protein powder, egg, egg whites, milk and cinnamon in a shallow dish until smooth.","Dip each slice of bread in the mix for a few seconds per side.","Fry in the butter in a non-stick pan over medium heat for 2–3 minutes per side until golden.","Serve topped with the strawberries."],"substitutions":[{"ingredientId":"whey-protein","alternatives":["pea-protein"]},{"ingredientId":"strawberries","alternatives":["blueberries","banana"]},{"ingredientId":"wholewheat-bread","alternatives":["rye-bread"]}]}'::jsonb),
  ('banana-blueberry-protein-muffins', 'Banana blueberry protein muffins', 'breakfast', 4, '{"id":"banana-blueberry-protein-muffins","name":"Banana blueberry protein muffins","meal":"breakfast","servings":4,"prepMinutes":10,"cookMinutes":20,"ingredients":[{"ingredientId":"oats-dry","grams":160,"display":"2 cups","prep":"blitzed to a flour"},{"ingredientId":"whey-protein","grams":100,"display":"4 scoops"},{"ingredientId":"egg","grams":150,"display":"3 eggs"},{"ingredientId":"banana","grams":240,"display":"2 ripe bananas","prep":"mashed"},{"ingredientId":"milk","grams":150,"display":"⅔ cup"},{"ingredientId":"blueberries","grams":150,"display":"1 cup"},{"ingredientId":"spices","grams":4,"display":"2 tsp baking powder & cinnamon"}],"steps":["Heat the oven to 180 °C and line an 8-hole muffin tin.","Mix the oat flour, protein powder, baking powder and cinnamon.","Whisk the eggs, banana and milk, stir into the dry mix, then fold in the blueberries.","Divide between the cases and bake for 18–20 minutes until a skewer comes out clean."],"substitutions":[{"ingredientId":"whey-protein","alternatives":["pea-protein"]},{"ingredientId":"milk","alternatives":["soy-drink","oat-drink"]},{"ingredientId":"blueberries","alternatives":["raspberries","raisins"]}],"notes":"Two muffins per serving. Freeze well for grab-and-go breakfasts."}'::jsonb),
  ('green-protein-smoothie', 'Green mango protein smoothie', 'breakfast', 1, '{"id":"green-protein-smoothie","name":"Green mango protein smoothie","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"whey-protein","grams":30,"display":"1 heaped scoop"},{"ingredientId":"milk","grams":200,"display":"⅘ cup"},{"ingredientId":"spinach","grams":40,"display":"1 large handful"},{"ingredientId":"mango","grams":100,"display":"⅔ cup","prep":"frozen chunks"},{"ingredientId":"banana","grams":80,"display":"⅔ banana"},{"ingredientId":"chia-seeds","grams":10,"display":"1 tbsp"}],"steps":["Put the milk and spinach in the blender first and blend until no leaves remain.","Add the mango, banana, protein powder and chia seeds.","Blend until smooth and drink straight away."],"substitutions":[{"ingredientId":"whey-protein","alternatives":["pea-protein","skyr-plain"]},{"ingredientId":"spinach","alternatives":["kale"]}]}'::jsonb),
  ('peanut-protein-oat-bites', 'No-bake peanut protein oat bites', 'snack', 4, '{"id":"peanut-protein-oat-bites","name":"No-bake peanut protein oat bites","meal":"snack","servings":4,"prepMinutes":10,"cookMinutes":0,"ingredients":[{"ingredientId":"oats-dry","grams":80,"display":"1 cup","prep":"dry"},{"ingredientId":"whey-protein","grams":60,"display":"2 scoops"},{"ingredientId":"peanut-butter","grams":64,"display":"4 tbsp"},{"ingredientId":"honey","grams":40,"display":"2 tbsp"},{"ingredientId":"raisins","grams":30,"display":"3 tbsp"},{"ingredientId":"milk","grams":30,"display":"2 tbsp"}],"steps":["Stir the peanut butter, honey and milk together until smooth.","Mix in the oats, protein powder and raisins until it forms a firm dough.","Roll into 12 balls and chill for 20 minutes to firm up."],"substitutions":[{"ingredientId":"whey-protein","alternatives":["pea-protein"]},{"ingredientId":"peanut-butter","alternatives":["tahini"]},{"ingredientId":"honey","alternatives":["maple-syrup"]}],"notes":"Three bites per serving. Keeps a week in the fridge."}'::jsonb),
  ('chocolate-protein-chia-pudding', 'Chocolate protein chia pudding', 'snack', 1, '{"id":"chocolate-protein-chia-pudding","name":"Chocolate protein chia pudding","meal":"snack","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"milk","grams":200,"display":"⅘ cup"},{"ingredientId":"whey-protein","grams":20,"display":"⅔ scoop"},{"ingredientId":"chia-seeds","grams":20,"display":"1½ tbsp"},{"ingredientId":"cocoa-powder","grams":5,"display":"1 tbsp"},{"ingredientId":"raspberries","grams":60,"display":"½ cup"}],"steps":["Whisk the protein powder and cocoa into the milk until lump-free.","Stir in the chia seeds, wait 5 minutes and stir again.","Chill for at least 2 hours or overnight, then top with raspberries."],"substitutions":[{"ingredientId":"whey-protein","alternatives":["pea-protein"]},{"ingredientId":"milk","alternatives":["soy-drink"]}]}'::jsonb),
  ('strawberry-protein-shake', 'Strawberry protein shake', 'snack', 1, '{"id":"strawberry-protein-shake","name":"Strawberry protein shake","meal":"snack","servings":1,"prepMinutes":3,"cookMinutes":0,"ingredients":[{"ingredientId":"whey-protein","grams":30,"display":"1 heaped scoop"},{"ingredientId":"milk","grams":250,"display":"1 cup"},{"ingredientId":"strawberries","grams":100,"display":"⅔ cup","prep":"frozen"}],"steps":["Put the milk, strawberries and protein powder in a blender.","Blend for 30 seconds until smooth and frothy.","Pour and drink straight away, after training or between meals."],"substitutions":[{"ingredientId":"whey-protein","alternatives":["pea-protein"]},{"ingredientId":"milk","alternatives":["soy-drink"]},{"ingredientId":"strawberries","alternatives":["raspberries","mango"]}]}'::jsonb),
  ('chocolate-protein-mug-cake', 'Chocolate protein mug cake', 'snack', 1, '{"id":"chocolate-protein-mug-cake","name":"Chocolate protein mug cake","meal":"snack","servings":1,"prepMinutes":3,"cookMinutes":2,"ingredients":[{"ingredientId":"whey-protein","grams":25,"display":"1 scoop"},{"ingredientId":"egg","grams":50,"display":"1 egg"},{"ingredientId":"banana","grams":40,"display":"⅓ banana","prep":"mashed"},{"ingredientId":"cocoa-powder","grams":8,"display":"1½ tbsp"},{"ingredientId":"milk","grams":20,"display":"1 tbsp"},{"ingredientId":"spices","grams":1,"display":"¼ tsp baking powder"}],"steps":["Mash the banana in a large mug, then beat in the egg and milk.","Stir in the protein powder, cocoa and baking powder until smooth.","Microwave for 60–75 seconds until just set in the middle. Cool for a minute before eating."],"substitutions":[{"ingredientId":"whey-protein","alternatives":["pea-protein"]},{"ingredientId":"banana","alternatives":["apple"]}]}'::jsonb),
  ('peanut-whey-rice-cakes', 'Peanut protein rice cakes with apple', 'snack', 1, '{"id":"peanut-whey-rice-cakes","name":"Peanut protein rice cakes with apple","meal":"snack","servings":1,"prepMinutes":4,"cookMinutes":0,"ingredients":[{"ingredientId":"rice-cakes","grams":18,"display":"2 rice cakes"},{"ingredientId":"whey-protein","grams":15,"display":"½ scoop"},{"ingredientId":"peanut-butter","grams":16,"display":"1 tbsp"},{"ingredientId":"milk","grams":15,"display":"1 tbsp"},{"ingredientId":"apple","grams":60,"display":"⅓ apple","prep":"thinly sliced"}],"steps":["Stir the protein powder, peanut butter and milk into a smooth, spreadable paste.","Spread over the rice cakes.","Top with the apple slices and a pinch of cinnamon if you like."],"substitutions":[{"ingredientId":"whey-protein","alternatives":["pea-protein"]},{"ingredientId":"rice-cakes","alternatives":["rye-crispbread"]}]}'::jsonb),
  ('vegan-blueberry-protein-porridge', 'Vegan blueberry protein porridge', 'breakfast', 1, '{"id":"vegan-blueberry-protein-porridge","name":"Vegan blueberry protein porridge","meal":"breakfast","servings":1,"prepMinutes":2,"cookMinutes":5,"ingredients":[{"ingredientId":"oats-dry","grams":50,"display":"½ cup","prep":"dry"},{"ingredientId":"soy-drink","grams":250,"display":"1 cup"},{"ingredientId":"pea-protein","grams":25,"display":"1 scoop"},{"ingredientId":"blueberries","grams":80,"display":"½ cup"},{"ingredientId":"pumpkin-seeds","grams":9,"display":"1 tbsp"},{"ingredientId":"maple-syrup","grams":7,"display":"1 tsp","optional":true}],"steps":["Simmer the oats in the soy drink for 4–5 minutes, stirring, until thick.","Off the heat, whisk in the protein powder with a splash of water.","Top with blueberries, pumpkin seeds and maple syrup if using."],"substitutions":[{"ingredientId":"pea-protein","alternatives":["whey-protein","soy-yogurt"]},{"ingredientId":"soy-drink","alternatives":["oat-drink"]}]}'::jsonb),
  ('vegan-peanut-strawberry-smoothie', 'Vegan peanut & strawberry protein smoothie', 'breakfast', 1, '{"id":"vegan-peanut-strawberry-smoothie","name":"Vegan peanut & strawberry protein smoothie","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"pea-protein","grams":30,"display":"1 heaped scoop"},{"ingredientId":"soy-drink","grams":250,"display":"1 cup"},{"ingredientId":"banana","grams":100,"display":"1 small banana","prep":"frozen"},{"ingredientId":"strawberries","grams":80,"display":"½ cup","prep":"frozen"},{"ingredientId":"peanut-butter","grams":16,"display":"1 tbsp"}],"steps":["Add the soy drink to the blender first, then the rest.","Blend for 45 seconds until thick and smooth.","Drink straight away."],"substitutions":[{"ingredientId":"pea-protein","alternatives":["whey-protein","tofu-firm"]},{"ingredientId":"peanut-butter","alternatives":["almonds"]}]}'::jsonb),
  ('vegan-raspberry-protein-pancakes', 'Vegan raspberry protein pancakes', 'breakfast', 1, '{"id":"vegan-raspberry-protein-pancakes","name":"Vegan raspberry protein pancakes","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":8,"ingredients":[{"ingredientId":"oats-dry","grams":50,"display":"½ cup","prep":"finely ground"},{"ingredientId":"pea-protein","grams":25,"display":"1 scoop"},{"ingredientId":"banana","grams":80,"display":"⅔ banana","prep":"mashed"},{"ingredientId":"soy-drink","grams":120,"display":"½ cup"},{"ingredientId":"raspberries","grams":80,"display":"⅔ cup"},{"ingredientId":"rapeseed-oil","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":2,"display":"½ tsp baking powder & a pinch of salt"},{"ingredientId":"maple-syrup","grams":10,"display":"½ tbsp","optional":true}],"steps":["Whisk the ground oats, protein powder and baking powder with the mashed banana and soy drink. Rest for 5 minutes.","Heat the oil in a non-stick pan over medium heat.","Cook small pancakes for 2 minutes per side, pressing a few raspberries into each.","Serve with the rest of the raspberries and maple syrup if you like."],"substitutions":[{"ingredientId":"pea-protein","alternatives":["whey-protein"]},{"ingredientId":"raspberries","alternatives":["blueberries"]}]}'::jsonb),
  ('vegan-chocolate-protein-oats', 'Vegan chocolate protein overnight oats', 'breakfast', 1, '{"id":"vegan-chocolate-protein-oats","name":"Vegan chocolate protein overnight oats","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"oats-dry","grams":50,"display":"½ cup","prep":"dry"},{"ingredientId":"soy-yogurt","grams":150,"display":"⅔ cup"},{"ingredientId":"soy-drink","grams":100,"display":"⅖ cup"},{"ingredientId":"pea-protein","grams":25,"display":"1 scoop"},{"ingredientId":"cocoa-powder","grams":5,"display":"1 tbsp"},{"ingredientId":"chia-seeds","grams":10,"display":"1 tbsp"},{"ingredientId":"banana","grams":60,"display":"½ banana","prep":"sliced"}],"steps":["Whisk the protein powder and cocoa into the soy drink until smooth.","Stir in the oats, chia seeds and soy yogurt. Cover and refrigerate overnight.","Top with sliced banana in the morning."],"substitutions":[{"ingredientId":"pea-protein","alternatives":["whey-protein"]},{"ingredientId":"banana","alternatives":["raspberries","strawberries"]}]}'::jsonb),
  ('vegan-chocolate-protein-shake', 'Vegan chocolate banana protein shake', 'snack', 1, '{"id":"vegan-chocolate-protein-shake","name":"Vegan chocolate banana protein shake","meal":"snack","servings":1,"prepMinutes":3,"cookMinutes":0,"ingredients":[{"ingredientId":"pea-protein","grams":25,"display":"1 scoop"},{"ingredientId":"soy-drink","grams":300,"display":"1¼ cups"},{"ingredientId":"banana","grams":60,"display":"½ banana","prep":"frozen"},{"ingredientId":"cocoa-powder","grams":5,"display":"1 tbsp"}],"steps":["Put everything in a blender with a couple of ice cubes.","Blend for 30 seconds until smooth.","Drink straight away."],"substitutions":[{"ingredientId":"pea-protein","alternatives":["whey-protein"]},{"ingredientId":"soy-drink","alternatives":["oat-drink"]}]}'::jsonb),
  ('chocolate-almond-protein-balls', 'Chocolate almond protein balls', 'snack', 4, '{"id":"chocolate-almond-protein-balls","name":"Chocolate almond protein balls","meal":"snack","servings":4,"prepMinutes":15,"cookMinutes":0,"ingredients":[{"ingredientId":"oats-dry","grams":80,"display":"1 cup","prep":"dry"},{"ingredientId":"pea-protein","grams":60,"display":"2 scoops"},{"ingredientId":"almonds","grams":40,"display":"4½ tbsp","prep":"finely chopped"},{"ingredientId":"maple-syrup","grams":50,"display":"2½ tbsp"},{"ingredientId":"cocoa-powder","grams":10,"display":"2 tbsp"},{"ingredientId":"soy-drink","grams":50,"display":"3 tbsp"}],"steps":["Mix the oats, protein powder, almonds and cocoa in a bowl.","Stir in the maple syrup and soy drink until it clumps into a firm dough. Add a splash more drink if dry.","Roll into 12 balls and chill for 20 minutes."],"substitutions":[{"ingredientId":"pea-protein","alternatives":["whey-protein"]},{"ingredientId":"almonds","alternatives":["cashews","sunflower-seeds"]}],"notes":"Three balls per serving. Keeps a week in the fridge."}'::jsonb),
  ('soy-yogurt-protein-berry-pot', 'Soy yogurt protein berry pot', 'snack', 1, '{"id":"soy-yogurt-protein-berry-pot","name":"Soy yogurt protein berry pot","meal":"snack","servings":1,"prepMinutes":3,"cookMinutes":0,"ingredients":[{"ingredientId":"soy-yogurt","grams":200,"display":"⅚ cup"},{"ingredientId":"pea-protein","grams":15,"display":"½ scoop"},{"ingredientId":"raspberries","grams":80,"display":"⅔ cup"},{"ingredientId":"pumpkin-seeds","grams":10,"display":"1 tbsp"}],"steps":["Stir the protein powder into the soy yogurt until smooth.","Spoon into a pot or glass.","Top with raspberries and pumpkin seeds."],"substitutions":[{"ingredientId":"pea-protein","alternatives":["whey-protein"]},{"ingredientId":"raspberries","alternatives":["blueberries","mango"]}]}'::jsonb),
  ('tofu-shakshuka-rye', 'Tofu shakshuka with rye', 'breakfast', 1, '{"id":"tofu-shakshuka-rye","name":"Tofu shakshuka with rye","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":12,"ingredients":[{"ingredientId":"tofu-firm","grams":200,"display":"200 g","prep":"drained, cut into thick slices"},{"ingredientId":"tomatoes-canned","grams":200,"display":"½ can (200 g)"},{"ingredientId":"bell-pepper","grams":60,"display":"½ pepper","prep":"sliced"},{"ingredientId":"onion","grams":40,"display":"⅓ onion","prep":"sliced"},{"ingredientId":"olive-oil","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":3,"display":"cumin, smoked paprika, chilli flakes, salt & pepper"},{"ingredientId":"rye-bread","grams":64,"display":"2 slices"}],"steps":["Soften the onion and pepper in the oil in a small pan for 4 minutes.","Add the spices and tomatoes and simmer for 3 minutes until slightly thickened.","Nestle the tofu slices into the sauce, cover and simmer for 5 minutes until hot through.","Serve straight from the pan with the rye bread for dipping."],"substitutions":[{"ingredientId":"tofu-firm","alternatives":["egg","white-beans-cooked"]},{"ingredientId":"rye-bread","alternatives":["wholewheat-bread","pita-wholewheat"]}]}'::jsonb),
  ('smoky-baked-tofu-bites', 'Smoky baked tofu bites', 'snack', 2, '{"id":"smoky-baked-tofu-bites","name":"Smoky baked tofu bites","meal":"snack","servings":2,"prepMinutes":5,"cookMinutes":25,"ingredients":[{"ingredientId":"tofu-firm","grams":280,"display":"280 g","prep":"pressed, cubed"},{"ingredientId":"rapeseed-oil","grams":5,"display":"1 tsp"},{"ingredientId":"lime-juice","grams":10,"display":"2 tsp"},{"ingredientId":"spices","grams":3,"display":"smoked paprika, garlic powder & salt"}],"steps":["Heat the oven to 200°C and line a tray with baking paper.","Toss the tofu cubes with the oil, lime juice and spices.","Spread out on the tray and bake for 25 minutes, turning once, until golden and chewy.","Eat warm or keep in the fridge for snacking."],"substitutions":[{"ingredientId":"tofu-firm","alternatives":["tempeh","chickpeas-cooked"]},{"ingredientId":"lime-juice","alternatives":["lemon-juice"]}],"notes":"Keeps 4 days in the fridge in a sealed box."}'::jsonb),
  ('crispy-tofu-carrot-sandwich', 'Crispy tofu sandwich with quick pickles', 'lunch', 1, '{"id":"crispy-tofu-carrot-sandwich","name":"Crispy tofu sandwich with quick pickles","meal":"lunch","servings":1,"prepMinutes":10,"cookMinutes":6,"ingredients":[{"ingredientId":"tofu-firm","grams":180,"display":"180 g","prep":"pressed, sliced"},{"ingredientId":"wholewheat-bread","grams":64,"display":"2 slices"},{"ingredientId":"carrot","grams":50,"display":"1 small carrot","prep":"cut into thin strips"},{"ingredientId":"cucumber","grams":40,"display":"¼ cucumber","prep":"thinly sliced"},{"ingredientId":"lime-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"soy-sauce","grams":8,"display":"½ tbsp"},{"ingredientId":"rapeseed-oil","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":1,"display":"chilli flakes & coriander"}],"steps":["Toss the carrot and cucumber with the lime juice and a pinch of salt and leave to pickle.","Fry the tofu slices in the oil for 3 minutes a side until crisp, then splash in the soy sauce.","Pile the tofu and drained pickles between the bread and add chilli and coriander."],"substitutions":[{"ingredientId":"tofu-firm","alternatives":["tempeh","chicken-breast-cooked"]},{"ingredientId":"wholewheat-bread","alternatives":["rye-bread","pita-wholewheat"]}]}'::jsonb),
  ('tempeh-quinoa-kale-salad', 'Tempeh, quinoa & kale salad', 'lunch', 2, '{"id":"tempeh-quinoa-kale-salad","name":"Tempeh, quinoa & kale salad","meal":"lunch","servings":2,"prepMinutes":10,"cookMinutes":8,"ingredients":[{"ingredientId":"tempeh","grams":300,"display":"300 g","prep":"cubed"},{"ingredientId":"quinoa-cooked","grams":300,"display":"1½ cups cooked"},{"ingredientId":"kale","grams":60,"display":"3 handfuls","prep":"stalks removed, shredded"},{"ingredientId":"bell-pepper","grams":100,"display":"1 small pepper","prep":"diced"},{"ingredientId":"lemon-juice","grams":30,"display":"2 tbsp"},{"ingredientId":"olive-oil","grams":14,"display":"1 tbsp"},{"ingredientId":"spices","grams":2,"display":"smoked paprika, salt & pepper"}],"steps":["Fry the tempeh in half the oil with the paprika for 6–8 minutes until browned on all sides.","Rub the kale with the lemon juice, the rest of the oil and a pinch of salt until it softens.","Toss with the quinoa and pepper, then top with the warm tempeh."],"substitutions":[{"ingredientId":"tempeh","alternatives":["tofu-firm","chickpeas-cooked"]},{"ingredientId":"kale","alternatives":["spinach","rocket"]}],"notes":"Packs well for two lunches; add the tempeh just before eating."}'::jsonb),
  ('teriyaki-tofu-rice-bowl', 'Teriyaki tofu rice bowl', 'lunch', 1, '{"id":"teriyaki-tofu-rice-bowl","name":"Teriyaki tofu rice bowl","meal":"lunch","servings":1,"prepMinutes":5,"cookMinutes":10,"ingredients":[{"ingredientId":"tofu-firm","grams":200,"display":"200 g","prep":"pressed, cubed"},{"ingredientId":"rice-white-cooked","grams":150,"display":"1 cup cooked"},{"ingredientId":"bell-pepper","grams":60,"display":"½ pepper","prep":"sliced"},{"ingredientId":"spring-onion","grams":15,"display":"1 spring onion","prep":"sliced"},{"ingredientId":"soy-sauce","grams":16,"display":"1 tbsp"},{"ingredientId":"maple-syrup","grams":10,"display":"½ tbsp"},{"ingredientId":"ginger","grams":4,"display":"2 tsp","prep":"grated"},{"ingredientId":"sesame-oil","grams":5,"display":"1 tsp"}],"steps":["Mix the soy sauce, maple syrup and ginger in a cup.","Fry the tofu in the sesame oil for 6 minutes until golden, adding the pepper for the last 2 minutes.","Pour in the sauce and let it bubble and coat the tofu.","Spoon over warm rice and finish with spring onion."],"substitutions":[{"ingredientId":"tofu-firm","alternatives":["tempeh","chicken-breast-raw"]},{"ingredientId":"rice-white-cooked","alternatives":["quinoa-cooked","rice-noodles-cooked"]}]}'::jsonb),
  ('tofu-tikka-wrap', 'Tofu tikka wrap', 'lunch', 1, '{"id":"tofu-tikka-wrap","name":"Tofu tikka wrap","meal":"lunch","servings":1,"prepMinutes":8,"cookMinutes":8,"ingredients":[{"ingredientId":"tofu-firm","grams":180,"display":"180 g","prep":"pressed, cubed"},{"ingredientId":"soy-yogurt","grams":60,"display":"¼ cup"},{"ingredientId":"tortilla-wheat","grams":60,"display":"1 large tortilla"},{"ingredientId":"lettuce","grams":30,"display":"1 handful","prep":"shredded"},{"ingredientId":"cucumber","grams":40,"display":"¼ cucumber","prep":"diced"},{"ingredientId":"lemon-juice","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":3,"display":"garam masala, chilli powder & salt"}],"steps":["Coat the tofu in half the yogurt, the spices and lemon juice.","Fry in a dry non-stick pan for 8 minutes, turning, until charred at the edges.","Warm the tortilla, spread with the remaining yogurt and add lettuce and cucumber.","Top with the tofu, roll up tightly and cut in half."],"substitutions":[{"ingredientId":"tofu-firm","alternatives":["chickpeas-cooked","chicken-breast-raw"]},{"ingredientId":"soy-yogurt","alternatives":["greek-yogurt-0"]}]}'::jsonb),
  ('peanut-tofu-noodle-salad', 'Peanut tofu rice noodle salad', 'lunch', 1, '{"id":"peanut-tofu-noodle-salad","name":"Peanut tofu rice noodle salad","meal":"lunch","servings":1,"prepMinutes":10,"cookMinutes":6,"ingredients":[{"ingredientId":"tofu-firm","grams":180,"display":"180 g","prep":"pressed, cubed"},{"ingredientId":"rice-noodles-cooked","grams":150,"display":"1 cup cooked","prep":"rinsed cold"},{"ingredientId":"peanut-butter","grams":16,"display":"1 tbsp"},{"ingredientId":"lime-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"carrot","grams":50,"display":"1 small carrot","prep":"grated"},{"ingredientId":"cucumber","grams":60,"display":"⅕ cucumber","prep":"cut into sticks"},{"ingredientId":"spices","grams":1,"display":"chilli flakes & salt"}],"steps":["Fry the tofu in a dry non-stick pan for 6 minutes until golden, then let it cool a little.","Whisk the peanut butter, lime juice, chilli and 2 tbsp warm water into a smooth dressing.","Toss the noodles, carrot and cucumber with the dressing and top with the tofu."],"substitutions":[{"ingredientId":"tofu-firm","alternatives":["edamame","chicken-breast-cooked"]},{"ingredientId":"peanut-butter","alternatives":["tahini"]}]}'::jsonb),
  ('tofu-sweet-potato-curry-batch', 'Tofu & sweet potato coconut curry', 'dinner', 4, '{"id":"tofu-sweet-potato-curry-batch","name":"Tofu & sweet potato coconut curry","meal":"dinner","servings":4,"prepMinutes":15,"cookMinutes":25,"ingredients":[{"ingredientId":"tofu-firm","grams":600,"display":"600 g","prep":"pressed, cubed"},{"ingredientId":"sweet-potato-raw","grams":400,"display":"3 small","prep":"peeled, cubed"},{"ingredientId":"coconut-milk-light","grams":400,"display":"1 can (400 g)"},{"ingredientId":"onion","grams":110,"display":"1 onion","prep":"diced"},{"ingredientId":"spinach","grams":100,"display":"3 big handfuls"},{"ingredientId":"rice-white-dry","grams":280,"display":"1½ cups dry"},{"ingredientId":"spices","grams":4,"display":"curry powder, garlic, salt"}],"steps":["Put the rice on to cook. Soften the onion in a splash of water in a large pot for 4 minutes.","Stir in the curry powder, then add the sweet potato, coconut milk and 150 ml water.","Simmer for 12 minutes until the potato is nearly tender, then add the tofu and simmer 6 minutes more.","Stir in the spinach until wilted, season and serve over the rice."],"substitutions":[{"ingredientId":"tofu-firm","alternatives":["chickpeas-cooked","chicken-thigh-raw"]},{"ingredientId":"sweet-potato-raw","alternatives":["potato-raw","cauliflower"]}],"notes":"Freezes well for up to 3 months (without the rice)."}'::jsonb),
  ('tempeh-bolognese-batch', 'Tempeh bolognese', 'dinner', 4, '{"id":"tempeh-bolognese-batch","name":"Tempeh bolognese","meal":"dinner","servings":4,"prepMinutes":15,"cookMinutes":25,"ingredients":[{"ingredientId":"tempeh","grams":400,"display":"400 g","prep":"crumbled"},{"ingredientId":"pasta-dry","grams":300,"display":"300 g dry"},{"ingredientId":"passata","grams":500,"display":"2 cups"},{"ingredientId":"onion","grams":110,"display":"1 onion","prep":"finely diced"},{"ingredientId":"carrot","grams":120,"display":"2 carrots","prep":"grated"},{"ingredientId":"garlic","grams":9,"display":"3 cloves","prep":"crushed"},{"ingredientId":"olive-oil","grams":14,"display":"1 tbsp"},{"ingredientId":"spices","grams":3,"display":"dried oregano, salt & pepper"}],"steps":["Fry the onion, carrot and garlic in the oil for 5 minutes until soft.","Add the crumbled tempeh and fry for 5 minutes until it starts to brown.","Pour in the passata with the oregano and simmer for 15 minutes, adding water if it gets too thick.","Meanwhile cook the pasta, drain and toss with the sauce."],"substitutions":[{"ingredientId":"tempeh","alternatives":["lentils-cooked","beef-mince-10-raw"]},{"ingredientId":"pasta-dry","alternatives":["rice-white-dry"]}],"notes":"The sauce keeps 4 days in the fridge or 3 months frozen."}'::jsonb),
  ('sticky-ginger-tofu-cabbage', 'Sticky ginger tofu with cabbage & rice', 'dinner', 2, '{"id":"sticky-ginger-tofu-cabbage","name":"Sticky ginger tofu with cabbage & rice","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":15,"ingredients":[{"ingredientId":"tofu-firm","grams":400,"display":"400 g","prep":"pressed, cubed"},{"ingredientId":"rice-white-dry","grams":140,"display":"¾ cup dry"},{"ingredientId":"cabbage","grams":200,"display":"¼ small cabbage","prep":"finely shredded"},{"ingredientId":"ginger","grams":12,"display":"2 tbsp","prep":"grated"},{"ingredientId":"maple-syrup","grams":20,"display":"1 tbsp"},{"ingredientId":"lime-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"rapeseed-oil","grams":10,"display":"2 tsp"},{"ingredientId":"spring-onion","grams":30,"display":"2 spring onions","prep":"sliced"}],"steps":["Cook the rice. Mix the ginger, maple syrup, lime juice and a good pinch of salt.","Fry the tofu in the oil in a wok for 8 minutes until crisp on all sides, then push to one side.","Stir-fry the cabbage for 3 minutes, then pour in the ginger glaze and toss until sticky.","Serve over the rice with the spring onions."],"substitutions":[{"ingredientId":"tofu-firm","alternatives":["tempeh","pork-tenderloin-raw"]},{"ingredientId":"cabbage","alternatives":["broccoli","green-beans"]}]}'::jsonb),
  ('smoky-tempeh-roast-potatoes', 'Smoky tempeh with roast potatoes & green beans', 'dinner', 2, '{"id":"smoky-tempeh-roast-potatoes","name":"Smoky tempeh with roast potatoes & green beans","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":35,"ingredients":[{"ingredientId":"tempeh","grams":300,"display":"300 g","prep":"sliced"},{"ingredientId":"potato-raw","grams":500,"display":"3 medium","prep":"cut into wedges"},{"ingredientId":"green-beans","grams":200,"display":"2 cups","prep":"trimmed"},{"ingredientId":"olive-oil","grams":14,"display":"1 tbsp"},{"ingredientId":"mustard","grams":10,"display":"2 tsp"},{"ingredientId":"spices","grams":3,"display":"smoked paprika, garlic powder, salt & pepper"}],"steps":["Heat the oven to 210°C. Toss the potatoes with half the oil and some salt and roast for 15 minutes.","Brush the tempeh with the mustard, remaining oil and paprika.","Add the tempeh and green beans to the tray and roast for 20 minutes more until the potatoes are crisp."],"substitutions":[{"ingredientId":"tempeh","alternatives":["tofu-firm","chicken-thigh-raw"]},{"ingredientId":"potato-raw","alternatives":["sweet-potato-raw"]}]}'::jsonb),
  ('tofu-fajita-traybake', 'Tofu fajita traybake', 'dinner', 2, '{"id":"tofu-fajita-traybake","name":"Tofu fajita traybake","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":25,"ingredients":[{"ingredientId":"tofu-firm","grams":400,"display":"400 g","prep":"pressed, cut into strips"},{"ingredientId":"bell-pepper","grams":240,"display":"2 peppers","prep":"sliced"},{"ingredientId":"onion","grams":110,"display":"1 onion","prep":"sliced"},{"ingredientId":"tortilla-wheat","grams":180,"display":"4 tortillas"},{"ingredientId":"soy-yogurt","grams":100,"display":"⅖ cup"},{"ingredientId":"lime-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"olive-oil","grams":10,"display":"2 tsp"},{"ingredientId":"spices","grams":4,"display":"cumin, smoked paprika, chilli & salt"}],"steps":["Heat the oven to 200°C. Toss the tofu, peppers and onion with the oil and spices on a large tray.","Roast for 25 minutes, turning once, until the edges char.","Squeeze over the lime juice and warm the tortillas for the last 2 minutes.","Fill the tortillas with the tofu and veg and top with the yogurt."],"substitutions":[{"ingredientId":"tofu-firm","alternatives":["black-beans-cooked","chicken-breast-raw"]},{"ingredientId":"tortilla-wheat","alternatives":["tortilla-corn"]}]}'::jsonb),
  ('homemade-beans-wholemeal-toast', 'Homemade beans on wholemeal toast', 'breakfast', 1, '{"id":"homemade-beans-wholemeal-toast","name":"Homemade beans on wholemeal toast","meal":"breakfast","servings":1,"prepMinutes":3,"cookMinutes":8,"ingredients":[{"ingredientId":"white-beans-cooked","grams":240,"display":"1 can (240 g)","prep":"drained"},{"ingredientId":"passata","grams":100,"display":"⅖ cup"},{"ingredientId":"wholewheat-bread","grams":64,"display":"2 slices"},{"ingredientId":"spinach","grams":30,"display":"1 large handful"},{"ingredientId":"maple-syrup","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":2,"display":"smoked paprika, salt & pepper"}],"steps":["Put the beans, passata, maple syrup and paprika in a small pan.","Simmer for 6 minutes until the sauce thickens, then stir in the spinach to wilt.","Toast the bread and spoon the beans over the top."],"substitutions":[{"ingredientId":"white-beans-cooked","alternatives":["kidney-beans-cooked","chickpeas-cooked"]},{"ingredientId":"wholewheat-bread","alternatives":["rye-bread"]}]}'::jsonb),
  ('black-bean-breakfast-hash', 'Black bean breakfast hash', 'breakfast', 2, '{"id":"black-bean-breakfast-hash","name":"Black bean breakfast hash","meal":"breakfast","servings":2,"prepMinutes":10,"cookMinutes":15,"ingredients":[{"ingredientId":"black-beans-cooked","grams":360,"display":"1½ cans (360 g)","prep":"drained"},{"ingredientId":"potato-raw","grams":300,"display":"2 small","prep":"cut into 1 cm dice"},{"ingredientId":"bell-pepper","grams":120,"display":"1 pepper","prep":"diced"},{"ingredientId":"onion","grams":60,"display":"½ onion","prep":"diced"},{"ingredientId":"avocado","grams":70,"display":"½ avocado","prep":"sliced"},{"ingredientId":"pumpkin-seeds","grams":20,"display":"2 tbsp"},{"ingredientId":"olive-oil","grams":10,"display":"2 tsp"},{"ingredientId":"spices","grams":3,"display":"cumin, chilli, salt & pepper"}],"steps":["Fry the potato in the oil in a large non-stick pan, covered, for 8 minutes, stirring now and then.","Add the onion, pepper and spices and fry for 4 minutes until soft.","Stir in the beans and cook for 3 minutes until hot and a little crisp.","Top with avocado and pumpkin seeds."],"substitutions":[{"ingredientId":"black-beans-cooked","alternatives":["kidney-beans-cooked","egg"]},{"ingredientId":"potato-raw","alternatives":["sweet-potato-raw"]}]}'::jsonb),
  ('smashed-edamame-rice-cakes', 'Smashed edamame rice cakes', 'snack', 1, '{"id":"smashed-edamame-rice-cakes","name":"Smashed edamame rice cakes","meal":"snack","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"edamame","grams":120,"display":"¾ cup","prep":"thawed"},{"ingredientId":"rice-cakes","grams":18,"display":"2 rice cakes"},{"ingredientId":"cucumber","grams":40,"display":"¼ cucumber","prep":"thinly sliced"},{"ingredientId":"lime-juice","grams":10,"display":"2 tsp"},{"ingredientId":"sesame-oil","grams":2,"display":"½ tsp"},{"ingredientId":"spices","grams":1,"display":"chilli flakes & salt"}],"steps":["Roughly mash the edamame with the lime juice, sesame oil and a pinch of salt.","Spread thickly over the rice cakes and layer the cucumber on top.","Finish with chilli flakes and eat straight away so the rice cakes stay crisp."],"substitutions":[{"ingredientId":"edamame","alternatives":["peas-green","hummus"]},{"ingredientId":"rice-cakes","alternatives":["rye-crispbread"]}]}'::jsonb),
  ('spiced-lentil-wrap', 'Spiced lentil wrap', 'lunch', 1, '{"id":"spiced-lentil-wrap","name":"Spiced lentil wrap","meal":"lunch","servings":1,"prepMinutes":8,"cookMinutes":4,"ingredients":[{"ingredientId":"lentils-cooked","grams":200,"display":"1 cup","prep":"drained"},{"ingredientId":"tortilla-wheat","grams":90,"display":"2 tortillas"},{"ingredientId":"soy-yogurt","grams":60,"display":"¼ cup"},{"ingredientId":"lettuce","grams":30,"display":"1 handful","prep":"shredded"},{"ingredientId":"tomato","grams":80,"display":"1 small tomato","prep":"diced"},{"ingredientId":"pumpkin-seeds","grams":10,"display":"1 tbsp"},{"ingredientId":"spices","grams":3,"display":"cumin, smoked paprika, garlic powder & salt"}],"steps":["Warm the lentils with the spices and a splash of water in a pan for 4 minutes, mashing a few.","Spread the yogurt over the tortillas.","Add the lentils, lettuce, tomato and pumpkin seeds, then roll up."],"substitutions":[{"ingredientId":"lentils-cooked","alternatives":["black-beans-cooked","turkey-mince-raw"]},{"ingredientId":"tortilla-wheat","alternatives":["tortilla-corn"]}]}'::jsonb),
  ('lentil-shepherds-pie-batch', 'Lentil shepherd''s pie', 'dinner', 4, '{"id":"lentil-shepherds-pie-batch","name":"Lentil shepherd''s pie","meal":"dinner","servings":4,"prepMinutes":20,"cookMinutes":40,"ingredients":[{"ingredientId":"lentils-dry","grams":300,"display":"1½ cups dry","prep":"rinsed"},{"ingredientId":"potato-raw","grams":900,"display":"4 large","prep":"peeled, chunked"},{"ingredientId":"onion","grams":110,"display":"1 onion","prep":"diced"},{"ingredientId":"carrot","grams":150,"display":"2–3 carrots","prep":"diced"},{"ingredientId":"tomatoes-canned","grams":400,"display":"1 can (400 g)"},{"ingredientId":"peas-green","grams":150,"display":"1 cup"},{"ingredientId":"olive-oil","grams":14,"display":"1 tbsp"},{"ingredientId":"spices","grams":4,"display":"thyme, salt & pepper"}],"steps":["Boil the potatoes for 15 minutes until soft, then mash with half the oil and some salt.","Meanwhile soften the onion and carrot in the rest of the oil, then add the lentils, tomatoes, thyme and 500 ml water.","Simmer for 20 minutes until the lentils are tender and thick, stirring in the peas at the end.","Heat the oven to 200°C. Spread the lentils in a dish, top with the mash and bake for 20 minutes until golden."],"substitutions":[{"ingredientId":"lentils-dry","alternatives":["lamb-mince-raw","beef-mince-10-raw"]},{"ingredientId":"potato-raw","alternatives":["sweet-potato-raw"]}],"notes":"Freezes well in portions; reheat at 180°C for 25 minutes."}'::jsonb),
  ('white-bean-kale-pasta', 'White bean & kale garlic pasta', 'dinner', 2, '{"id":"white-bean-kale-pasta","name":"White bean & kale garlic pasta","meal":"dinner","servings":2,"prepMinutes":5,"cookMinutes":12,"ingredients":[{"ingredientId":"white-beans-cooked","grams":240,"display":"1 can (240 g)","prep":"drained"},{"ingredientId":"pasta-dry","grams":150,"display":"150 g dry"},{"ingredientId":"kale","grams":80,"display":"4 handfuls","prep":"shredded"},{"ingredientId":"garlic","grams":6,"display":"2 cloves","prep":"sliced"},{"ingredientId":"olive-oil","grams":14,"display":"1 tbsp"},{"ingredientId":"lemon-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"spices","grams":2,"display":"chilli flakes, salt & pepper"}],"steps":["Cook the pasta, adding the kale for the last 2 minutes. Save a mug of the water, then drain.","Gently fry the garlic and chilli in the oil in the empty pan for 1 minute.","Add the beans and a splash of pasta water and crush a few with a spoon.","Toss in the pasta and kale with the lemon juice and season well."],"substitutions":[{"ingredientId":"white-beans-cooked","alternatives":["chickpeas-cooked","chicken-breast-cooked"]},{"ingredientId":"kale","alternatives":["spinach","broccoli"]}]}'::jsonb),
  ('black-bean-enchilada-bake', 'Black bean enchilada bake', 'dinner', 4, '{"id":"black-bean-enchilada-bake","name":"Black bean enchilada bake","meal":"dinner","servings":4,"prepMinutes":15,"cookMinutes":30,"ingredients":[{"ingredientId":"black-beans-cooked","grams":480,"display":"2 cans (480 g)","prep":"drained"},{"ingredientId":"sweet-potato-raw","grams":500,"display":"2 large","prep":"peeled, small dice"},{"ingredientId":"tortilla-corn","grams":208,"display":"8 corn tortillas"},{"ingredientId":"passata","grams":500,"display":"2 cups"},{"ingredientId":"onion","grams":110,"display":"1 onion","prep":"diced"},{"ingredientId":"sweetcorn-canned","grams":150,"display":"¾ can","prep":"drained"},{"ingredientId":"spices","grams":4,"display":"cumin, chilli powder, oregano & salt"}],"steps":["Heat the oven to 200°C. Microwave the sweet potato with a splash of water for 6 minutes until just soft.","Mix the potato, beans, onion, sweetcorn and half the spices. Stir the rest of the spices into the passata.","Fill the tortillas with the bean mix, roll up and pack into a baking dish.","Pour the sauce over and bake for 25 minutes until bubbling."],"substitutions":[{"ingredientId":"black-beans-cooked","alternatives":["kidney-beans-cooked","chicken-breast-cooked"]},{"ingredientId":"tortilla-corn","alternatives":["tortilla-wheat"]}],"notes":"Keeps 3 days in the fridge; reheat portions in the microwave."}'::jsonb),
  ('smashed-chickpea-toast', 'Smashed chickpea toast with tomato', 'breakfast', 1, '{"id":"smashed-chickpea-toast","name":"Smashed chickpea toast with tomato","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":3,"ingredients":[{"ingredientId":"chickpeas-cooked","grams":120,"display":"½ can (120 g)","prep":"drained"},{"ingredientId":"hummus","grams":45,"display":"3 tbsp"},{"ingredientId":"wholewheat-bread","grams":64,"display":"2 slices"},{"ingredientId":"tomato","grams":80,"display":"1 small tomato","prep":"sliced"},{"ingredientId":"pumpkin-seeds","grams":15,"display":"1½ tbsp"},{"ingredientId":"lemon-juice","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":1,"display":"chilli flakes, salt & pepper"}],"steps":["Toast the bread.","Mash the chickpeas with the hummus, lemon juice and a pinch of salt.","Spread over the toast, layer on the tomato and finish with pumpkin seeds and chilli."],"substitutions":[{"ingredientId":"chickpeas-cooked","alternatives":["white-beans-cooked","egg"]},{"ingredientId":"wholewheat-bread","alternatives":["rye-bread"]}]}'::jsonb),
  ('cocoa-chickpea-bites-batch', 'Cocoa chickpea bites', 'snack', 4, '{"id":"cocoa-chickpea-bites-batch","name":"Cocoa chickpea bites","meal":"snack","servings":4,"prepMinutes":10,"cookMinutes":0,"ingredients":[{"ingredientId":"chickpeas-cooked","grams":240,"display":"1 can (240 g)","prep":"drained, patted dry"},{"ingredientId":"peanut-butter","grams":64,"display":"4 tbsp"},{"ingredientId":"almonds","grams":40,"display":"4½ tbsp"},{"ingredientId":"cocoa-powder","grams":15,"display":"3 tbsp"},{"ingredientId":"maple-syrup","grams":40,"display":"2 tbsp"}],"steps":["Blend the almonds to a coarse crumb.","Add the chickpeas, peanut butter, cocoa and maple syrup and blend until it clumps together.","Roll into 12 balls and chill for 30 minutes to firm up."],"substitutions":[{"ingredientId":"peanut-butter","alternatives":["tahini"]},{"ingredientId":"almonds","alternatives":["oats-dry","sunflower-seeds"]}],"notes":"Keeps a week in the fridge; 3 balls per serving."}'::jsonb),
  ('chickpea-cucumber-yogurt-pot', 'Chickpea cucumber yogurt pot', 'snack', 1, '{"id":"chickpea-cucumber-yogurt-pot","name":"Chickpea cucumber yogurt pot","meal":"snack","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"chickpeas-cooked","grams":120,"display":"½ can (120 g)","prep":"drained"},{"ingredientId":"soy-yogurt","grams":125,"display":"½ cup"},{"ingredientId":"cucumber","grams":60,"display":"⅕ cucumber","prep":"diced"},{"ingredientId":"lemon-juice","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":1,"display":"dried mint, cumin & salt"}],"steps":["Stir the lemon juice, mint and a pinch of salt into the yogurt.","Spoon into a jar or bowl and top with the chickpeas and cucumber.","Dust with cumin and eat with a spoon."],"substitutions":[{"ingredientId":"soy-yogurt","alternatives":["skyr-plain","greek-yogurt-0"]},{"ingredientId":"chickpeas-cooked","alternatives":["edamame"]}]}'::jsonb),
  ('baked-falafel-pitta', 'Baked falafel pitta', 'lunch', 1, '{"id":"baked-falafel-pitta","name":"Baked falafel pitta","meal":"lunch","servings":1,"prepMinutes":12,"cookMinutes":20,"ingredients":[{"ingredientId":"chickpeas-cooked","grams":240,"display":"1 can (240 g)","prep":"drained, patted dry"},{"ingredientId":"pita-wholewheat","grams":64,"display":"1 pitta"},{"ingredientId":"tahini","grams":15,"display":"1 tbsp"},{"ingredientId":"lettuce","grams":30,"display":"1 handful","prep":"shredded"},{"ingredientId":"tomato","grams":80,"display":"1 small tomato","prep":"diced"},{"ingredientId":"lemon-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"spices","grams":3,"display":"cumin, coriander, garlic powder & salt"}],"steps":["Heat the oven to 200°C. Mash the chickpeas with the spices until they hold together.","Shape into 6 small patties, place on a lined tray and bake for 20 minutes, turning once.","Whisk the tahini with the lemon juice and a little water.","Stuff the pitta with lettuce, tomato and falafel and drizzle with the tahini sauce."],"substitutions":[{"ingredientId":"chickpeas-cooked","alternatives":["white-beans-cooked","chicken-breast-cooked"]},{"ingredientId":"pita-wholewheat","alternatives":["tortilla-wheat"]}]}'::jsonb),
  ('chickpea-mayo-free-sandwich', 'Mustardy chickpea sandwich', 'lunch', 1, '{"id":"chickpea-mayo-free-sandwich","name":"Mustardy chickpea sandwich","meal":"lunch","servings":1,"prepMinutes":8,"cookMinutes":0,"ingredients":[{"ingredientId":"chickpeas-cooked","grams":200,"display":"⅘ can (200 g)","prep":"drained"},{"ingredientId":"wholewheat-bread","grams":64,"display":"2 slices"},{"ingredientId":"soy-yogurt","grams":40,"display":"2½ tbsp"},{"ingredientId":"mustard","grams":10,"display":"2 tsp"},{"ingredientId":"cucumber","grams":40,"display":"¼ cucumber","prep":"finely diced"},{"ingredientId":"spring-onion","grams":15,"display":"1 spring onion","prep":"sliced"},{"ingredientId":"lettuce","grams":20,"display":"2 leaves"}],"steps":["Mash the chickpeas roughly with a fork.","Stir in the yogurt, mustard, cucumber and spring onion, then season with salt and pepper.","Pile onto the bread with the lettuce and close the sandwich."],"substitutions":[{"ingredientId":"chickpeas-cooked","alternatives":["tuna-canned","white-beans-cooked"]},{"ingredientId":"soy-yogurt","alternatives":["greek-yogurt-0"]}]}'::jsonb),
  ('chickpea-quinoa-tabbouleh', 'Chickpea & edamame quinoa tabbouleh', 'lunch', 2, '{"id":"chickpea-quinoa-tabbouleh","name":"Chickpea & edamame quinoa tabbouleh","meal":"lunch","servings":2,"prepMinutes":15,"cookMinutes":0,"ingredients":[{"ingredientId":"chickpeas-cooked","grams":400,"display":"1⅔ cans (400 g)","prep":"drained"},{"ingredientId":"quinoa-cooked","grams":300,"display":"1½ cups cooked","prep":"cooled"},{"ingredientId":"edamame","grams":100,"display":"⅔ cup","prep":"thawed"},{"ingredientId":"tomato","grams":150,"display":"1 large tomato","prep":"diced"},{"ingredientId":"cucumber","grams":150,"display":"½ cucumber","prep":"diced"},{"ingredientId":"lemon-juice","grams":30,"display":"2 tbsp"},{"ingredientId":"olive-oil","grams":14,"display":"1 tbsp"},{"ingredientId":"spices","grams":3,"display":"parsley, mint, salt & pepper"}],"steps":["Whisk the lemon juice, oil, salt and pepper in a large bowl.","Add the quinoa, chickpeas, edamame, tomato and cucumber.","Fold through plenty of chopped parsley and mint and divide into two boxes."],"substitutions":[{"ingredientId":"quinoa-cooked","alternatives":["rice-white-cooked"]},{"ingredientId":"chickpeas-cooked","alternatives":["white-beans-cooked","chicken-breast-cooked"]}],"notes":"Keeps 3 days in the fridge."}'::jsonb),
  ('moroccan-chickpea-soup-batch', 'Moroccan chickpea & lentil soup', 'lunch', 4, '{"id":"moroccan-chickpea-soup-batch","name":"Moroccan chickpea & lentil soup","meal":"lunch","servings":4,"prepMinutes":10,"cookMinutes":30,"ingredients":[{"ingredientId":"chickpeas-cooked","grams":480,"display":"2 cans (480 g)","prep":"drained"},{"ingredientId":"lentils-dry","grams":100,"display":"½ cup dry","prep":"rinsed"},{"ingredientId":"tomatoes-canned","grams":400,"display":"1 can (400 g)"},{"ingredientId":"onion","grams":110,"display":"1 onion","prep":"diced"},{"ingredientId":"carrot","grams":120,"display":"2 carrots","prep":"diced"},{"ingredientId":"vegetable-stock","grams":1000,"display":"1 litre"},{"ingredientId":"olive-oil","grams":14,"display":"1 tbsp"},{"ingredientId":"spices","grams":4,"display":"cumin, cinnamon, paprika, salt & pepper"}],"steps":["Soften the onion and carrot in the oil in a large pot for 5 minutes.","Stir in the spices for 30 seconds, then add the lentils, tomatoes and stock.","Simmer for 20 minutes until the lentils break down.","Add the chickpeas, simmer 5 minutes more and season to taste."],"substitutions":[{"ingredientId":"chickpeas-cooked","alternatives":["white-beans-cooked","chicken-thigh-raw"]},{"ingredientId":"carrot","alternatives":["sweet-potato-raw"]}],"notes":"A hearty soup that freezes well in portions."}'::jsonb),
  ('roast-veg-hummus-wrap', 'Roast courgette & hummus wrap', 'lunch', 1, '{"id":"roast-veg-hummus-wrap","name":"Roast courgette & hummus wrap","meal":"lunch","servings":1,"prepMinutes":8,"cookMinutes":20,"ingredients":[{"ingredientId":"hummus","grams":80,"display":"5 tbsp"},{"ingredientId":"chickpeas-cooked","grams":120,"display":"½ can (120 g)","prep":"drained"},{"ingredientId":"tortilla-wheat","grams":60,"display":"1 large tortilla"},{"ingredientId":"zucchini","grams":120,"display":"½ courgette","prep":"sliced"},{"ingredientId":"bell-pepper","grams":60,"display":"½ pepper","prep":"sliced"},{"ingredientId":"rocket","grams":20,"display":"1 handful"},{"ingredientId":"olive-oil","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":2,"display":"za''atar or cumin, salt & pepper"}],"steps":["Heat the oven to 210°C. Toss the courgette, pepper and chickpeas with the oil and spices.","Roast on a tray for 20 minutes until the veg is soft and the chickpeas crisp.","Spread the hummus over the tortilla, add the rocket and the roast veg, then roll up."],"substitutions":[{"ingredientId":"tortilla-wheat","alternatives":["pita-wholewheat"]},{"ingredientId":"chickpeas-cooked","alternatives":["tofu-firm","chicken-breast-cooked"]}]}'::jsonb),
  ('chana-masala-rice-batch', 'Chana masala with rice', 'dinner', 4, '{"id":"chana-masala-rice-batch","name":"Chana masala with rice","meal":"dinner","servings":4,"prepMinutes":15,"cookMinutes":25,"ingredients":[{"ingredientId":"chickpeas-cooked","grams":720,"display":"3 cans (720 g)","prep":"drained"},{"ingredientId":"rice-white-dry","grams":280,"display":"1½ cups dry"},{"ingredientId":"onion","grams":220,"display":"2 onions","prep":"finely diced"},{"ingredientId":"tomatoes-canned","grams":400,"display":"1 can (400 g)"},{"ingredientId":"ginger","grams":12,"display":"2 tbsp","prep":"grated"},{"ingredientId":"garlic","grams":9,"display":"3 cloves","prep":"crushed"},{"ingredientId":"rapeseed-oil","grams":14,"display":"1 tbsp"},{"ingredientId":"spices","grams":4,"display":"garam masala, cumin, turmeric, chilli & salt"}],"steps":["Put the rice on to cook. Fry the onions in the oil for 8 minutes until golden.","Add the ginger, garlic and spices and stir for 1 minute.","Tip in the tomatoes and chickpeas with 150 ml water and simmer for 15 minutes until thick.","Crush some chickpeas against the pan to thicken, season and serve with the rice."],"substitutions":[{"ingredientId":"chickpeas-cooked","alternatives":["kidney-beans-cooked","chicken-thigh-raw"]},{"ingredientId":"rice-white-dry","alternatives":["quinoa-dry"]}],"notes":"Tastes even better the next day; freezes well."}'::jsonb),
  ('lemon-chickpea-spinach-pasta', 'Lemony chickpea & spinach pasta', 'dinner', 2, '{"id":"lemon-chickpea-spinach-pasta","name":"Lemony chickpea & spinach pasta","meal":"dinner","servings":2,"prepMinutes":5,"cookMinutes":12,"ingredients":[{"ingredientId":"chickpeas-cooked","grams":300,"display":"1¼ cans (300 g)","prep":"drained"},{"ingredientId":"pasta-dry","grams":150,"display":"150 g dry"},{"ingredientId":"spinach","grams":100,"display":"3 big handfuls"},{"ingredientId":"garlic","grams":6,"display":"2 cloves","prep":"sliced"},{"ingredientId":"olive-oil","grams":14,"display":"1 tbsp"},{"ingredientId":"lemon-juice","grams":30,"display":"2 tbsp"},{"ingredientId":"pumpkin-seeds","grams":20,"display":"2 tbsp"},{"ingredientId":"spices","grams":2,"display":"chilli flakes, salt & pepper"}],"steps":["Cook the pasta and save a mug of the cooking water before draining.","Fry the garlic and chickpeas in the oil for 5 minutes until the chickpeas pop and turn golden.","Add the spinach, pasta, lemon juice and a splash of pasta water and toss until glossy.","Season well and scatter with pumpkin seeds."],"substitutions":[{"ingredientId":"chickpeas-cooked","alternatives":["white-beans-cooked","tuna-canned"]},{"ingredientId":"pasta-dry","alternatives":["quinoa-dry"]}]}'::jsonb),
  ('chickpea-aubergine-feta-bulgur', 'Roast chickpeas & aubergine with feta bulgur', 'dinner', 2, '{"id":"chickpea-aubergine-feta-bulgur","name":"Roast chickpeas & aubergine with feta bulgur","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":30,"ingredients":[{"ingredientId":"chickpeas-cooked","grams":400,"display":"1⅔ cans (400 g)","prep":"drained"},{"ingredientId":"aubergine","grams":300,"display":"⅔ aubergine","prep":"cubed"},{"ingredientId":"bulgur-dry","grams":120,"display":"⅘ cup dry"},{"ingredientId":"feta","grams":60,"display":"60 g","prep":"crumbled"},{"ingredientId":"olive-oil","grams":14,"display":"1 tbsp"},{"ingredientId":"lemon-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"spices","grams":3,"display":"cumin, smoked paprika, salt & pepper"}],"steps":["Heat the oven to 210°C. Toss the aubergine and chickpeas with the oil and spices on a tray.","Roast for 30 minutes, stirring halfway, until the aubergine is soft and browned.","Meanwhile cover the bulgur with boiling water, leave for 15 minutes, then drain and fluff with the lemon juice.","Pile the roast veg over the bulgur and crumble the feta on top."],"substitutions":[{"ingredientId":"feta","alternatives":["tahini"]},{"ingredientId":"bulgur-dry","alternatives":["couscous-dry","quinoa-dry"]},{"ingredientId":"chickpeas-cooked","alternatives":["lamb-mince-raw"]}]}'::jsonb),
  ('chickpea-shawarma-couscous', 'Chickpea shawarma with couscous', 'dinner', 2, '{"id":"chickpea-shawarma-couscous","name":"Chickpea shawarma with couscous","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":20,"ingredients":[{"ingredientId":"chickpeas-cooked","grams":400,"display":"1⅔ cans (400 g)","prep":"drained, patted dry"},{"ingredientId":"couscous-dry","grams":120,"display":"⅔ cup dry"},{"ingredientId":"cucumber","grams":150,"display":"½ cucumber","prep":"diced"},{"ingredientId":"soy-yogurt","grams":150,"display":"⅗ cup"},{"ingredientId":"onion","grams":60,"display":"½ red onion","prep":"thinly sliced"},{"ingredientId":"olive-oil","grams":14,"display":"1 tbsp"},{"ingredientId":"spices","grams":4,"display":"cumin, coriander, cinnamon, paprika, garlic & salt"}],"steps":["Heat the oven to 220°C. Toss the chickpeas and onion with the oil and spices and roast for 20 minutes.","Pour boiling water over the couscous to just cover, put a lid on and leave for 5 minutes.","Mix half the cucumber into the yogurt with a pinch of salt.","Fluff the couscous, top with the shawarma chickpeas, the remaining cucumber and the yogurt sauce."],"substitutions":[{"ingredientId":"chickpeas-cooked","alternatives":["chicken-thigh-raw","tofu-firm"]},{"ingredientId":"couscous-dry","alternatives":["bulgur-dry","quinoa-dry"]}]}'::jsonb),
  ('spanish-chickpea-potato-stew', 'Spanish chickpea, spinach & potato stew', 'dinner', 4, '{"id":"spanish-chickpea-potato-stew","name":"Spanish chickpea, spinach & potato stew","meal":"dinner","servings":4,"prepMinutes":15,"cookMinutes":30,"ingredients":[{"ingredientId":"chickpeas-cooked","grams":720,"display":"3 cans (720 g)","prep":"drained"},{"ingredientId":"potato-raw","grams":600,"display":"3 medium","prep":"cubed"},{"ingredientId":"spinach","grams":200,"display":"1 bag (200 g)"},{"ingredientId":"tomatoes-canned","grams":400,"display":"1 can (400 g)"},{"ingredientId":"onion","grams":110,"display":"1 onion","prep":"diced"},{"ingredientId":"garlic","grams":9,"display":"3 cloves","prep":"sliced"},{"ingredientId":"olive-oil","grams":14,"display":"1 tbsp"},{"ingredientId":"spices","grams":4,"display":"smoked paprika, cumin, salt & pepper"}],"steps":["Soften the onion and garlic in the oil in a large pot for 5 minutes.","Stir in the paprika and cumin, then add the potatoes, tomatoes and 500 ml water.","Stew for 15 minutes until the potatoes are nearly tender.","Add the chickpeas, simmer 8 minutes more, then stir in the spinach until wilted."],"substitutions":[{"ingredientId":"chickpeas-cooked","alternatives":["white-beans-cooked","cod-raw"]},{"ingredientId":"spinach","alternatives":["kale"]}],"notes":"Keeps 4 days in the fridge and freezes well."}'::jsonb),
  ('chickpea-egg-fried-rice', 'Chickpea & vegetable egg fried rice', 'dinner', 2, '{"id":"chickpea-egg-fried-rice","name":"Chickpea & vegetable egg fried rice","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":10,"ingredients":[{"ingredientId":"chickpeas-cooked","grams":300,"display":"1¼ cans (300 g)","prep":"drained"},{"ingredientId":"rice-white-cooked","grams":400,"display":"2½ cups cooked","prep":"cold"},{"ingredientId":"egg","grams":100,"display":"2 eggs","prep":"beaten"},{"ingredientId":"peas-green","grams":100,"display":"¾ cup"},{"ingredientId":"carrot","grams":80,"display":"1 carrot","prep":"diced"},{"ingredientId":"spring-onion","grams":30,"display":"2 spring onions","prep":"sliced"},{"ingredientId":"soy-sauce","grams":20,"display":"1 tbsp + 1 tsp"},{"ingredientId":"rapeseed-oil","grams":10,"display":"2 tsp"}],"steps":["Heat the oil in a wok and fry the carrot and chickpeas for 4 minutes until the chickpeas crisp.","Add the peas and rice and stir-fry for 3 minutes until hot.","Push to one side, scramble the eggs in the space, then toss everything together.","Season with the soy sauce and finish with spring onions."],"substitutions":[{"ingredientId":"egg","alternatives":["tofu-firm"]},{"ingredientId":"chickpeas-cooked","alternatives":["edamame","chicken-breast-cooked"]}]}'::jsonb)
